update public.article_translations set title = 'Annapurna Base Camp oder Poon Hill: Welcher Trek passt zu Ihnen?', intro = 'Beide starten bei Pokhara, und beide bringen Sie nah an die Annapurnas heran. Ein Guide aus Ghandruk erklärt, wie sich die beiden Treks wirklich unterscheiden und wie Sie sich zwischen ihnen entscheiden.', card_text = 'Tage, Höhe, Schwierigkeit und Aussicht im Vergleich, von einem Guide aus Ghandruk.', cover_alt = 'Ein Steindorf mit Terrassenfeldern unterhalb der schneebedeckten Gipfel des Annapurna-Massivs', highlight_tag = '5 oder 11 Tage', updated_line = 'Aktualisiert für die Saison 2026/2027', facts = '[{"icon": "schedule", "label": "Poon Hill", "value": "5 Tage ab Pokhara"}, {"icon": "schedule", "label": "Annapurna Base Camp", "value": "11 Tage ab Kathmandu"}, {"icon": "altitude", "label": "Höchste Punkte", "value": "3.210 m vs. 4.130 m"}, {"icon": "hiking", "label": "Schwierigkeit", "value": "Leicht vs. mittelschwer"}]'::jsonb, seo_keyword = 'Annapurna Base Camp oder Poon Hill', seo_title = 'Annapurna Base Camp oder Poon Hill: Welcher Trek passt?', seo_description = 'Annapurna Base Camp oder Poon Hill? Ein Guide vor Ort vergleicht Tage, Höhe, Schwierigkeit und Aussicht, damit Sie den richtigen Annapurna Trek finden.' where article_id = '219c8f13-405e-45e5-96f5-4c55b3b9d3dd' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Wählen Sie ", "type": "text"}, {"text": "Poon Hill", "type": "text", "marks": [{"type": "bold"}]}, {"text": " als leichten Trek, wenn Sie etwa eine Woche in Nepal haben und den berühmten Sonnenaufgang über dem Dhaulagiri erleben möchten. Wählen Sie das ", "type": "text"}, {"text": "Annapurna Base Camp", "type": "text", "marks": [{"type": "bold"}]}, {"text": " bei 10–12 Tagen Zeit, wenn Sie mitten im Annapurna Sanctuary stehen möchten, umringt von Gipfeln über 7.000 m.", "type": "text"}]}]}}'::jsonb where section_id = '45c3ef0c-2f4d-41ff-b9a5-0f0fbb7f4ff4' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ich bin in Ghandruk aufgewachsen, einem Gurung-Dorf, das an beiden Routen liegt, und bin beide öfter gegangen, als ich zählen kann. Trekker fragen mich oft, welchen der beiden sie wählen sollen. Meine ehrliche Antwort: Es sind zwei verschiedene Arten von Reise, nicht eine bessere und eine schlechtere.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "So erkläre ich den Unterschied den Familien und Freundesgruppen, die ich führe.", "type": "text"}]}]}}'::jsonb where section_id = '974d8f7e-2479-4c2e-a1e5-1f4a4e584470' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Poon Hill ist eine Rundtour von 4–5 Tagen durch Dörfer und Rhododendronwälder. Der höchste Punkt ist der Aussichtspunkt selbst auf 3.210 m, den Sie im Morgengrauen von Ghorepani (2.860 m) aus besteigen. Die Höhe ist selten ein Problem, und Sie sind innerhalb einer Woche zurück in Pokhara.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Das Annapurna Base Camp führt viel tiefer in die Berge. Sie folgen dem Tal des Modi Khola hinauf ins Sanctuary und übernachten auf 4.130 m, umgeben von Annapurna I, Annapurna South, Hiunchuli und Machapuchare. Unser Reiseverlauf dauert 11 Tage ab Kathmandu, davon etwa 8 Tage auf dem Trek.", "type": "text"}]}]}, "heading": "Die kurze Antwort: Zeit und Höhe", "tocLabel": "Zeit und Höhe"}'::jsonb where section_id = '58ee1882-f0b2-4035-a289-8e1a503c1ae1' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Poon Hill", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Sonnenaufgang über dem Dhaulagiri und dem Massiv der Annapurna South vom Aussichtspunkt", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Steindörfer wie Ulleri, Ghorepani und Ghandruk", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Im Frühling einige der schönsten Rhododendronwälder Nepals", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Annapurna Base Camp", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Die Wände des Sanctuary von innen, mit der Annapurna I (8.091 m) über dem Gletscher", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Der Fischschwanzgipfel des Machapuchare direkt über Ihnen", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Die tiefe Schlucht des Modi Khola und die natürlichen heißen Quellen in Jhinu Danda auf dem Rückweg", "type": "text"}]}]}]}]}, "heading": "Was Sie auf jedem Trek sehen", "tocLabel": "Die Aussicht"}'::jsonb where section_id = '6bcc72e1-8d45-4aec-9662-a799c7f99e48' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Poon Hill ist leicht, aber nicht flach. Der Aufstieg von Tikhedhunga nach Ulleri führt über Tausende Steinstufen, und der Weg im Morgengrauen hinauf zum Aussichtspunkt ist etwa eine Stunde lang steil. Die Etappen dauern 4–6 Stunden, und wer regelmäßig wandert, schafft das gut.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Das Annapurna Base Camp ist mittelschwer. Die Etappen sind länger, rund um Chhomrong gibt es viel mehr Steinstufen, und Sie verbringen zwei Nächte über 3.000 m. Kletterkenntnisse brauchen Sie nicht, aber Sie sollten mehrere Tage hintereinander 6–7 Stunden gut gehen können.", "type": "text"}]}]}, "heading": "Wie anspruchsvoll ist jeder Trek?", "tocLabel": "Schwierigkeit"}'::jsonb where section_id = 'c9f53bd7-3ef4-4808-a2d7-bd5cc7485183' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Lawinengefahr auf dem Weg zum Base Camp:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Nach starkem Schneefall kann der Abschnitt zwischen Deurali und dem Machhapuchhre Base Camp gefährlich sein. Wir richten uns nach den Warnungen vor Ort und warten oder kehren um, wenn es nötig ist. Das ist ein Grund, warum wir das Sanctuary im Hochwinter meiden.", "type": "text"}]}]}}'::jsonb where section_id = 'e218e6f4-728b-4eb8-8a4c-9badf3a44052' and locale = 'de';
update public.article_section_translations set content = '{"text": "Wenn Sie sich nicht entscheiden können, beginnen Sie mit der Poon-Hill-Runde. Die beiden Routen treffen sich bei Tadapani und Ghandruk. Fühlen Sie sich stark und haben die Tage, kann aus dem kurzen Trek also der komplette Trek zum Base Camp werden."}'::jsonb where section_id = '03814edc-f38a-44e0-b79e-19f3d1f91a76' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja, und es ist einer der klassischen Treks in Nepal. Die übliche Kombination führt von Nayapul hinauf nach Ghorepani und zum Poon Hill, hinüber nach Tadapani und dann über Chhomrong ins Sanctuary. Zurück geht es über Jhinu Danda mit seinen heißen Quellen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Planen Sie 12–14 Tage ab Kathmandu ein. Den Sonnenaufgang am Poon Hill erleben Sie schon früh, und er ist zugleich eine gute Akklimatisierung vor dem Base Camp.", "type": "text"}]}]}, "heading": "Kann ich beide machen?", "tocLabel": "Beide Treks"}'::jsonb where section_id = '4247243f-9f9a-4dc6-89a4-42fd43746dea' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Poon Hill", "type": "text", "marks": [{"type": "bold"}]}, {"text": " eignet sich für Trekking-Neulinge, Familien mit Kindern, alle mit nur einer Woche in Nepal und alle, die Bergblicke ohne Kälte und Höhe möchten. Er ist auch ein guter Wintertrek, wenn die höheren Täler verschneit sind.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Annapurna Base Camp", "type": "text", "marks": [{"type": "bold"}]}, {"text": " eignet sich für Trekker, die eine echte Reise in die Berge suchen und die Zeit dafür haben. Es ist anstrengender, aber Himalaya-Erfahrung brauchen Sie nicht, wenn Sie fit sind und gleichmäßig gehen. Viele meiner Gäste wählen es als ihren ersten großen Trek.", "type": "text"}]}]}, "heading": "Für wen welcher Trek passt", "tocLabel": "Für wen"}'::jsonb where section_id = '80e19e1e-ec71-43b9-90eb-3102c13db8ef' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Auf beiden Treks übernachten Sie in familiengeführten Teehäusern, und das Annapurna-Gebiet hat einige der komfortabelsten Nepals. Auf der Poon-Hill-Runde liegen die Dörfer nah beieinander, Zimmer sind leicht zu finden, und heiße Duschen und WLAN sind üblich.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Auf dem Weg zum Base Camp werden die Lodges oberhalb von Chhomrong einfacher. Die Zimmer sind kleiner, abends ist der Speiseraum der einzige warme Ort, und kleine Extras wie heiße Duschen und Akkuladen kosten umso mehr, je höher Sie kommen. Nehmen Sie für die Nächte im Sanctuary einen warmen Schlafsack mit.", "type": "text"}]}]}, "heading": "Komfort unterwegs", "tocLabel": "Komfort"}'::jsonb where section_id = 'ca60d174-ffe5-4f3f-9505-9c87c7b51153' and locale = 'de';
update public.article_section_translations set content = '{"alt": "Ein Trekker beobachtet vom hohen Aussichtspunkt das erste Licht des Sonnenaufgangs auf den Bergen", "caption": "Sonnenaufgang von einem hohen Aussichtspunkt im Annapurna-Gebiet"}'::jsonb where section_id = '636dff2c-9d89-4750-b4fa-6edc7510a8b5' and locale = 'de';
update public.article_section_translations set content = '{"heading": "Wer diese Treks führt"}'::jsonb where section_id = '1976374f-19a7-4dc5-9975-5e4b920712a9' and locale = 'de';
update public.article_section_translations set content = '{"items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja. Er ist kurz, bleibt unter 3.300 m und hat alle paar Stunden Teehäuser, also ein sanfter Einstieg ins Trekking im Himalaya.", "type": "text"}]}]}, "question": "Ist Poon Hill gut für den ersten Trek in Nepal?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Poon Hill ist bei Familien sehr beliebt, und viele Kinder haben Spaß daran. Das Annapurna Base Camp passt zu älteren, aktiven Kindern, die lange Wanderungen gewohnt sind. Das Tempo passen wir in jedem Fall an.", "type": "text"}]}]}, "question": "Können Kinder diese Treks machen?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Auf der Poon-Hill-Runde dauern die meisten Etappen 4–6 Stunden, mit vielen Teepausen. Auf dem Weg zum Annapurna Base Camp rechnen Sie mit 5–7 Stunden, mit einem langen Tag hinauf ins Sanctuary. Wir richten das Tempo nach dem langsamsten Mitglied der Gruppe, niemand wird gehetzt.", "type": "text"}]}]}, "question": "Wie viele Stunden gehen wir pro Tag?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja, beide liegen in der Annapurna Conservation Area. Sie brauchen also die ACAP-Genehmigung und, wo Kontrollpunkte danach fragen, eine TIMS-Karte. Beides besorgen wir. Außerdem schreibt Nepal ausländischen Trekkern vor, mit einem lizenzierten Guide zu gehen.", "type": "text"}]}]}, "question": "Brauche ich für beide Treks eine Genehmigung?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Poon Hill bietet ein weites Panorama aus der Distanz. Im Base Camp stehen Sie mitten zwischen den Gipfeln. Die meisten, die beide gemacht haben, sagen: Das Base Camp ist eindrucksvoller, Poon Hill entspannter.", "type": "text"}]}]}, "question": "Welcher Trek hat die bessere Aussicht?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja. Jeder Trek ist privat, also können wir einen Tag in Ghandruk, Chhomrong oder an den heißen Quellen von Jhinu Danda einplanen. Das kostet etwas mehr, macht den Trek aber viel entspannter, besonders mit Kindern.", "type": "text"}]}]}, "question": "Kann ich einen Ruhetag einlegen?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Für beide ist die beste Reisezeit Oktober–November und März–April. Poon Hill ist auch im Winter gut, wenn es im Base Camp sehr kalt ist und im oberen Tal Lawinengefahr besteht.", "type": "text"}]}]}, "question": "Wann ist die beste Reisezeit für jeden Trek?"}]}'::jsonb where section_id = 'f836c581-1952-41d3-be77-3bc48de5c8c8' and locale = 'de';
update public.article_section_translations set content = '{"heading": "Noch unsicher, welcher Trek zu Ihrer Reise passt?", "message": "Hallo! Ich schwanke zwischen dem Annapurna Base Camp und Poon Hill. Können Sie mir helfen, passend zu meinen Reisedaten und meiner Fitness zu entscheiden?", "buttonText": "Bikash auf WhatsApp fragen"}'::jsonb where section_id = '77570630-dd20-478e-a4d5-145804842294' and locale = 'de';
update public.articles set slug = 'annapurna-base-camp-oder-poon-hill' where id = '219c8f13-405e-45e5-96f5-4c55b3b9d3dd';
update public.article_translations set title = 'Annapurna Circuit Trek Kosten: Paketpreis und Tagesbudget', intro = 'Der 13-tägige Annapurna Circuit Trek mit Tilicho-See kostet je nach Gruppengröße 480 bis 1.020 USD pro Person. Dieser Ratgeber schlüsselt alle weiteren Kosten auf, von Mahlzeiten und der ACAP-Genehmigung über Träger und Trinkgeld bis zum Bargeld für Verzögerungen.', card_text = 'Paketpreise, Ausgaben unterwegs, ACAP-Gebühren, Träger, Trinkgeld und Beispielbudgets für den Annapurna Circuit.', cover_alt = 'Bergblick auf dem Annapurna Circuit Trek', highlight_tag = 'Ab 480 USD pro Person', updated_line = 'Preise geprüft für 2027', facts = '[{"icon": "hiking", "label": "Reisedauer", "value": "13 Tage, Kathmandu bis Kathmandu"}, {"icon": "payments", "label": "Tägliche Ausgaben unterwegs", "value": "2.500 bis 4.500 NPR pro Tag"}, {"icon": "description", "label": "Genehmigung", "value": "Nur ACAP"}, {"icon": "payments", "label": "Tagesbudget für Essen", "value": "15 bis 25 USD"}]'::jsonb, seo_keyword = 'Annapurna Circuit Kosten', seo_title = 'Annapurna Circuit Kosten: Preise, Genehmigung, Tagesbudget', seo_description = 'Der Annapurna Circuit Trek kostet je nach Gruppengröße 480 bis 1.020 USD pro Person. Tagesbudget, ACAP-Gebühr, Träger, Trinkgeld und Beispielrechnungen.', help_heading = 'Möchten Sie einen genauen Preis für Ihre Gruppe?', help_text = 'Nennen Sie uns Ihre Gruppengröße und Ihre Termine, und wir schicken Ihnen die vollständigen Kosten, auch für alles, was das Paket nicht enthält.', help_message = 'Hallo! Mein Name ist {name}
-> Gruppengröße: 
-> Termine: 
-> Wünsche für den Annapurna Circuit Trek: 

Was würde diese Reise genau kosten?' where article_id = '2adae2de-2deb-46df-adf2-b323e206d769' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der ", "type": "text"}, {"text": "Annapurna Circuit Trek", "type": "text", "marks": [{"type": "link", "attrs": {"href": "https://traveltonepal.com/treks/annapurna-circuit-trek"}}]}, {"text": " kostet bei unserem 13-tägigen Paket mit Tilicho-See 480 bis 1.020 USD pro Person. Der Preis hängt davon ab, wie viele Personen in Ihrer Gruppe sind. Mit Mahlzeiten, Träger und Visum geben die meisten Trekker in einer Vierergruppe etwa 940 bis 1.115 USD pro Person aus und allein ohne Träger 1.285 bis 1.460 USD. Nicht enthalten sind Trinkgeld, privater Jeep, internationale Flüge und Reiseversicherung.", "type": "text"}]}, {"type": "image", "attrs": {"alt": "Annapurna Circuit Kosten", "width": 1080, "height": 800, "photoId": "c9cc0b1b-de5f-44f0-9786-6810df37a9ef", "fileName": "annapurna-circuit-total-cost-per-person", "variantWidths": [400, 800, 1080]}}, {"type": "paragraph"}]}}'::jsonb where section_id = '842fa8c0-42c1-425e-8e2f-a1b99e3a7fe1' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Drei Dinge beeinflussen Ihre Gesamtkosten am stärksten. Erstens die Gruppengröße, denn die Kosten für einen Guide und den Transport teilen sich alle. Zweitens, wie viel Sie unterwegs täglich ausgeben, etwa für heiße Duschen, WLAN und westliches Essen. Drittens, ob Sie einen Träger buchen und privaten Transport wählen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Alle Preise in diesem Ratgeber sind in US-Dollar (USD) und nepalesischen Rupien (NPR) angegeben. Der Einfachheit halber rechnen wir mit ", "type": "text"}, {"text": "150 NPR = 1 USD", "type": "text", "marks": [{"type": "bold"}]}, {"text": " . Der Kurs der Nepal Rastra Bank lag Mitte 2026 bei etwa 152 NPR pro Dollar, prüfen Sie den Kurs also vor Ihrer Reise.", "type": "text"}]}]}}'::jsonb where section_id = 'e2d59afc-03c8-455c-835d-f866cc892aa6' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Gruppengröße", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Preis pro Person (USD)", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "1 Person", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "1,020", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "2 Personen", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "630", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "3 bis 5 Personen", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "550", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "6 bis 8 Personen", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "530", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "9 oder mehr Personen", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "480", "type": "text"}]}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Im Paket enthalten", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Das Paket deckt alles ab, was Sie für die Route brauchen, außer Essen und persönlichen Ausgaben.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Transport auf der Straße (Linienbus) für die gesamte Route", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Ein lizenzierter Trekkingguide", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Teehauszimmer für jede Nacht auf dem Trek", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Genehmigung für das Annapurna Conservation Area (ACAP)", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Flughafentransfers in Kathmandu", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Staatliche Steuern", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Nicht im Paket enthalten", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der größte Kostenpunkt außerhalb des Pakets sind die Mahlzeiten, gefolgt von Träger und Trinkgeld.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Mahlzeiten, Getränke und Snacks (15 bis 25 USD)", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Träger (250 USD)", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Trinkgeld für Guide und Träger", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Privatbus", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Nepal-Visum und Reiseversicherung ", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "WLAN, Laden, heiße Duschen, Getränke und andere private Ausgaben. ", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Flug von Jomsom nach Pokhara (Änderungen vorbehalten: 175 USD)", "type": "text"}]}]}]}, {"type": "paragraph"}]}, "heading": "Paketpreis nach Gruppengröße", "tocLabel": ""}'::jsonb where section_id = '223f14b8-3fbb-4e8f-9e83-a56ad2be9d41' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Budget für eine Vierergruppe", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In einer Vierergruppe zahlt jede Person den günstigsten Paketpreis für kleine Gruppen und teilt sich zwei Träger und das gesamte Trinkgeld.", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Kostenpunkt", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Pro Person (USD)", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Paket (3–5 Personen)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "550", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Ausgaben unterwegs (inkl. Mahlzeiten, heiße Duschen, WLAN, Laden), 13 Tage", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "215 bis 390", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Anteil Träger (2 Träger für 4 Personen)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "125", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Nepal-Visum, 30 Tage", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "50", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Gesamt", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "940 bis 1.115", "type": "text", "marks": [{"type": "bold"}]}]}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Budget für Alleinreisende", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Wer allein trekkt, zahlt den Paketpreis für eine Person und bei Bedarf die vollen Kosten für den Träger.", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Kostenpunkt", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Ohne Träger (USD)", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Mit Träger (USD)", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Paket (1 Person)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "1,020", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "1,020", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Ausgaben unterwegs (inkl. Mahlzeiten, heiße Duschen, WLAN, Laden), 13 Tage", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "215 bis 390", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "215 bis 390", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Träger", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "—", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "250", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Nepal-Visum, 30 Tage", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "50", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "50", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Gesamt", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "1.285 bis 1.460", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "1.535 bis 1.710", "type": "text", "marks": [{"type": "bold"}]}]}]}]}]}, {"type": "paragraph", "content": [{"text": "Der niedrigere Wert jeder Spanne geht von einem einfachen Tagesbudget aus, der höhere von einem Komfortbudget und einem Träger.", "type": "text"}]}]}, "heading": "Beispielbudgets: Gruppe oder allein", "tocLabel": ""}'::jsonb where section_id = '799989c0-84e7-441b-9fc0-be4734f28802' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Das Paket deckt Guide, Zimmer, Genehmigung und Straßentransport ab, Ihre wichtigsten Zusatzkosten sind also Essen, Träger, Trinkgeld und Visum. Die Tabelle unten listet alle Kosten auf, die auf dem Trek anfallen. Jede Zeile wird weiter unten in einem eigenen Abschnitt erklärt.", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Kostenpunkt", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Preis", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Im Paket?", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "13-tägiges Paket", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "480 bis 1.020 USD pro Person", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "—", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Lizenzierter Guide", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Inklusive", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Ja", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Teehauszimmer", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Inklusive", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Ja", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Straßentransport (Linienbus und Jeep)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Inklusive", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Ja", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Privater Straßentransport", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Nicht enthalten", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Nein", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "ACAP-Genehmigung", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "3.000 NPR (etwa 20 USD)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Ja", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Nur Mahlzeiten (Frühstück, Mittag- und Abendessen)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "15 bis 25 USD pro Tag", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Nein", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Mahlzeiten und Ausgaben unterwegs pro Tag insgesamt", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "2.500 bis 4.500 NPR pro Tag (17 bis 30 USD)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Nein", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Träger", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "250 USD pro Träger, geteilt von 2 Trekkern", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Nein", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Trinkgeld", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Üblich, aber nicht verpflichtend", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Nein", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Touristenvisum für Nepal", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "30 / 50 / 125 USD für 15 / 30 / 90 Tage", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Nein", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Reiseversicherung", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Unterschiedlich; muss 5.416 m und Hubschrauberrettung abdecken", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Nein", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Flug von Jomsom nach Pokhara", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Optional (175 USD, Änderungen vorbehalten)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Nein", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Bargeldreserve für Verzögerungen", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "2 bis 3 zusätzliche Tage unterwegs (7.500 bis 13.500 NPR)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Nein", "type": "text"}]}]}]}]}, {"type": "image", "attrs": {"alt": "Pizza, Momos, Gemüse und Nudeln zum Abendessen auf dem Annapurna Circuit", "width": 1120, "height": 630, "photoId": "02361ec5-0ed5-4b57-8a5c-0aa7a80eb4b4", "fileName": "food-annapurna-circuit-momo-pizza-vegetables-noodles", "variantWidths": [400, 800, 1120]}}, {"type": "paragraph", "content": [{"text": "Bild: Abendessen in Manang auf dem Annapurna Circuit. ", "type": "text"}]}]}, "heading": "Kosten für den Annapurna Circuit im Überblick", "tocLabel": ""}'::jsonb where section_id = '19200595-0fc4-44a8-8de9-42793596e915' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "image", "attrs": {"alt": "Tägliche Ausgaben und Budget auf dem Annapurna Circuit", "width": 1080, "height": 680, "photoId": "028e6498-a320-449e-994c-0e460f493f49", "fileName": "annapurna-circuit-daily-trail-budget", "variantWidths": [400, 800, 1080]}}, {"type": "paragraph", "content": [{"text": "Rechnen Sie unterwegs mit ", "type": "text"}, {"text": "2.500 bis 4.500 NPR pro Tag", "type": "text", "marks": [{"type": "bold"}]}, {"text": " , das sind etwa 17 bis 30 USD. In 13 Tagen kommen so 32.500 bis 58.500 NPR zusammen, also etwa 215 bis 390 USD. Den größten Teil davon kosten die Mahlzeiten. Der Rest geht für Tee, Trinkwasser, das Laden des Handys, heiße Duschen und WLAN drauf.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Ihre täglichen Ausgaben steigen mit der Höhe. Lebensmittel und Brennstoff müssen bis ins obere Manang und an den Thorong La einen weiten Weg das Tal hinauf zurücklegen, daher kostet dieselbe Mahlzeit auf 4.000 m mehr als auf 760 m. Am günstigsten sind die Tage um Besisahar und Chame, am teuersten die zwischen Yak Kharka und Thorong Phedi.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Einfach oder komfortabel", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Ein einfaches Budget von 2.500 NPR pro Tag deckt schlichtes einheimisches Essen und das Nötigste. Ein Komfortbudget von 4.500 NPR pro Tag umfasst zusätzlich heiße Duschen, westliches Essen und WLAN.", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph"}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Einfach (2.500 NPR pro Tag)", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Komfort (4.500 NPR pro Tag)", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Mahlzeiten", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Drei einheimische Mahlzeiten: Dal Bhat, Nudeln, Suppe", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Internationales Essen wie Pizza, Pasta und richtiger Kaffee", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Getränke", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Tee und abgekochtes Wasser", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Zusätzliche Getränke und Snacks", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Extras", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Laden von Handy und Akkus", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Täglich heiße Dusche und WLAN", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Summe für 13 Tage", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Etwa 32.500 NPR (215 USD)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Etwa 58.500 NPR (390 USD)", "type": "text"}]}]}]}]}, {"type": "paragraph", "content": [{"text": "Dal Bhat ist für die meisten Trekker die klügste Wahl. Es ist eine vollständige Mahlzeit aus Reis, Linsensuppe und Gemüsecurry, und in den Teehäusern gibt es meist einen Nachschlag. Es liefert gleichmäßige Energie für lange Tage wie die 8 bis 10 Stunden lange Überquerung des Thorong La.", "type": "text"}]}]}, "heading": "Tagesbudget unterwegs", "tocLabel": ""}'::jsonb where section_id = '8c8944d4-4ffd-4f18-9112-68562c4fa520' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Für den Annapurna Circuit brauchen Sie nur eine Genehmigung, die Annapurna Conservation Area Permit (ACAP). Sie kostet für ausländische Trekker 3.000 NPR (etwa 20 USD) und für Bürger der SAARC-Staaten 1.000 NPR, jeweils inklusive Mehrwertsteuer. Bei Online-Zahlung kommt eine Gebühr von 2,9 % für den Zahlungsdienst hinzu. Die ACAP ist in unserem Paket bereits enthalten, Sie zahlen sie also nicht extra.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die TIMS-Karte (Trekkers'' Information Management System) ist auf dem Annapurna Circuit derzeit nicht nötig. Die Vorschriften für Genehmigungen in Nepal können sich von Saison zu Saison ändern, daher prüfen wir sie vor jeder Saison erneut.", "type": "text"}]}, {"type": "image", "attrs": {"alt": "Genehmigung für das Annapurna Conservation Area Project (ACAP)", "width": 800, "height": 450, "photoId": "4b062b68-2d54-41fe-b9ce-797416f115f0", "fileName": "acap-permit-annapurna-conservation-area-entry-permit", "variantWidths": [400, 800]}}, {"type": "paragraph", "content": [{"text": "Bild: Genehmigung für das Annapurna Conservation Area Project", "type": "text"}]}]}, "heading": "Kosten der Genehmigung für den Annapurna Circuit", "tocLabel": ""}'::jsonb where section_id = 'c8e04669-1177-4c14-8027-59b7bccdef6c' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Auf dem Annapurna Circuit ist ein lizenzierter Guide Pflicht, und der Guide ist in unserem Paketpreis bereits enthalten. Ein Träger ist optional und kostet 250 USD für den gesamten Trek. Ein Träger trägt bis zu 20 kg und wird von zwei Trekkern geteilt, jede Person zahlt also 125 USD. Wenn Sie allein trekken und einen Träger möchten, zahlen Sie die vollen 250 USD.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Ein Träger macht die harten Tage viel leichter. Die längsten Tage sind die 7-stündigen Etappen zum Tilicho-Basislager (4.150 m) und zurück sowie die 8 bis 10 Stunden lange Überquerung des Thorong La (5.416 m). Wer an diesen Tagen nur einen kleinen Tagesrucksack trägt, kann gleichmäßig gehen und Kraft für die Höhe sparen. Teilen sich zwei Trekker einen Träger, entfallen auf jede Person etwa 10 kg Gepäck, packen Sie also mit Blick auf diese Grenze.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Trinkgeld für Guide und Träger", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Trinkgeld ist auf Treks in Nepal üblich, und Guides und Träger erwarten es meist, verpflichtend ist es aber nicht. Wie viel Sie geben, liegt ganz bei Ihnen und kann zeigen, wie zufrieden Sie mit ihrer Arbeit sind. Trinkgeld ist weder im Paketpreis noch in den Beispielbudgets auf dieser Seite enthalten.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Spanne unten ist nur ein Vorschlag, und Sie können gern mehr, weniger oder einen anderen Betrag geben.", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Teammitglied", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Pro Tag", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "13 Tage", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Guide", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "10 bis 15 USD", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "130 bis 195 USD", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Träger (pro Person)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "8 bis 12 USD", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "104 bis 156 USD", "type": "text"}]}]}]}]}, {"type": "paragraph", "content": [{"text": "In einer Gruppe legen viele Trekker ihr Trinkgeld zusammen und übergeben es als einen Betrag, das hält es einfach. Wer allein unterwegs ist, wählt einen Betrag, der sich für die erhaltene Unterstützung richtig anfühlt.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Trinkgeld können Sie am Ende des Treks in USD oder NPR geben. Übergeben Sie es nach Möglichkeit jedem Guide und Träger persönlich. ", "type": "text"}]}]}, "heading": "Kosten für Guide und Träger", "tocLabel": ""}'::jsonb where section_id = '3f783e7c-2d90-4737-b3a8-ee4ee5accfc8' and locale = 'de';
update public.article_section_translations set content = '{"heading": "Guides, die diesen Trek führen"}'::jsonb where section_id = 'a234f148-472e-40bd-8c74-b8779e297662' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der gesamte Straßentransport auf dem Trek ist im Paket enthalten, Sie zahlen also nur extra, wenn Sie fliegen möchten. Die Fahrten dauern insgesamt etwa 26 Stunden an vier Tagen: Kathmandu nach Besisahar, Besisahar nach Chame, Muktinath nach Pokhara und Pokhara nach Kathmandu.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Kosten für den Flug von Jomsom nach Pokhara: 175 USD (Änderungen vorbehalten)", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Kosten für den Flug von Pokhara nach Kathmandu: 105 USD (Änderungen vorbehalten)", "type": "text", "marks": [{"type": "bold"}]}]}]}]}, {"type": "paragraph", "content": [{"text": "Zwei Flüge können die Reise verkürzen, doch keiner ist im Paket enthalten. Der Flug von Pokhara nach Kathmandu dauert etwa 25 Minuten statt 7 Stunden Fahrt über 200 km. Der Flug von Jomsom nach Pokhara dauert 20 bis 25 Minuten und ersetzt den größten Teil der langen Fahrt durch das Kali-Gandaki-Tal. Fragen Sie uns nach den aktuellen Preisen, denn sie ändern sich oft.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Flug ab Jomsom ist unzuverlässig. Kleine Maschinen mit 19 Sitzen fliegen nur morgens, weil nachmittags starker Wind das Kali-Gandaki-Tal hinaufweht, und Verspätungen sind häufig. Charterflugzeuge und Hubschrauber fliegen auch dann noch, wenn die Linienflüge eingestellt sind.", "type": "text"}]}]}, "heading": "Transport- und Flugkosten", "tocLabel": ""}'::jsonb where section_id = 'a410e69c-774f-4141-bb72-3e8118eb8850' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Nehmen Sie genug Bargeld für ", "type": "text"}, {"text": "2 bis 3 zusätzliche Tage", "type": "text", "marks": [{"type": "bold"}]}, {"text": " unterwegs mit, also etwa 7.500 bis 13.500 NPR. Verzögerungen gibt es auf diesem Trek selbst in der besten Reisezeit. Jeder zusätzliche Tag bedeutet eine weitere Nacht mit Essen und Getränken.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Herbst 2026 hat gezeigt, warum eine Reserve wichtig ist. Der Thorong La war wetterbedingt vom 30. September bis etwa 6. Oktober 2026 gesperrt. Wenn ein Pass oder eine Straße gesperrt ist, warten Trekker in den Teehäusern, bis wieder geöffnet wird, oder kehren auf demselben Weg zurück. Essen und Getränke müssen Sie für jeden zusätzlichen Tag weiter bezahlen.", "type": "text"}]}]}, "heading": "Bargeldreserve für Verzögerungen", "tocLabel": ""}'::jsonb where section_id = '60130a7b-a691-43b6-a98c-25aa91bbd1ce' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Nehmen Sie das gesamte Bargeld für den Trek ab Kathmandu oder Besisahar mit, denn in Besisahar steht der letzte verlässliche Geldautomat auf der Ostseite der Runde. Manang hat einen Geldautomaten, der aber oft nicht funktioniert. Der nächste steht in Jomsom, das Sie erst nach der Überquerung des Thorong La erreichen. Die Teehäuser unterwegs nehmen meist nur Bargeld in nepalesischen Rupien.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Nehmen Sie für einen 13-tägigen Trek ", "type": "text"}, {"text": "32.500 bis 58.500 NPR ", "type": "text", "marks": [{"type": "bold"}]}, {"text": "für die täglichen Ausgaben mit, dazu ", "type": "text"}, {"text": "5.000 bis 13.500 NPR ", "type": "text", "marks": [{"type": "bold"}]}, {"text": "für 2 bis 3 zusätzliche Tage. Rechnen Sie das Trinkgeld hinzu, wenn Sie es in Rupien geben möchten. Nehmen Sie kleine und große Scheine mit, denn kleine Teehäuser haben auf große Scheine oft kein Wechselgeld.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Verlassen Sie sich beim Bezahlen und bei Überweisungen nicht auf Ihr Handy. Die Mobilfunknetze von NTC und Ncell funktionieren in den unteren Dörfern, doch oberhalb von etwa 3.500 m, also von Manang bis zum Thorong La, ist der Empfang unzuverlässig.", "type": "text"}]}]}, "heading": "Bargeld, Geldautomaten und Bezahlen", "tocLabel": ""}'::jsonb where section_id = 'c9ae9379-a6e3-4190-9d32-7e358ed702eb' and locale = 'de';
update public.article_section_translations set content = '{"items": ["Tägliche Ausgaben unterwegs: 32.500 bis 58.500 NPR", "Reserve für 2 bis 3 zusätzliche Tage: 5.000 bis 13.500 NPR", "Trinkgeld für Guide und Träger (wenn gewünscht in Rupien)", "Kleine Scheine für Tee, Snacks und das Laden"], "heading": "Bargeld, das Sie vor Besisahar abheben sollten"}'::jsonb where section_id = '1d317b84-1743-4e9b-9924-a22d4633fcd9' and locale = 'de';
update public.article_section_translations set content = '{"items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Nein, derzeit brauchen Sie nur die ACAP-Genehmigung. Die TIMS-Karte ist auf dem Annapurna Circuit nicht vorgeschrieben, doch die Regeln können sich von Saison zu Saison ändern, prüfen Sie sie also vor Ihrer Reise erneut.", "type": "text"}]}]}, "question": "Brauche ich eine TIMS-Karte für den Annapurna Circuit?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Planen Sie, bar zu bezahlen. Die Teehäuser nehmen meist nepalesische Rupien, nach Besisahar gibt es kaum Geldautomaten, und oberhalb von etwa 3.500 m ist der Handyempfang schwach.", "type": "text"}]}]}, "question": "Kann ich unterwegs mit Karte bezahlen?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Rechnen Sie in einer Vierergruppe mit etwa 940 bis 1.115 USD pro Person, allein ohne Träger mit 1.285 bis 1.460 USD. Hinzu kommen internationale Flüge, Reiseversicherung und das Trinkgeld, das Sie geben möchten.", "type": "text"}]}]}, "question": "Wie viel sollte ich insgesamt einplanen?"}]}'::jsonb where section_id = 'c34bf2fe-8080-4cff-ae46-f6f6d99e12ef' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die Kosten für den Annapurna Circuit Trek hängen vor allem von Ihrer Gruppengröße ab, mit Paketen von 480 bis 1.020 USD pro Person. Dazu kommen unterwegs 2.500 bis 4.500 NPR pro Tag, ein Träger, wenn Sie einen möchten, ein Visum und eine Versicherung, die 5.416 m abdeckt. Trinkgeld für Guide und Träger ist üblich, die Höhe entscheiden aber immer Sie. Besorgen Sie Ihre ACAP vor dem Start, heben Sie Ihr Bargeld in Kathmandu oder Besisahar ab und halten Sie Geld für ein paar Tage in Reserve, falls Straße oder Thorong La gesperrt sind.", "type": "text"}]}]}, "heading": "Fazit: Kosten für den Annapurna Circuit Trek", "tocLabel": ""}'::jsonb where section_id = '42c2deb0-81ea-4090-b5b3-fee5ebcda48b' and locale = 'de';
update public.article_section_translations set content = '{"heading": "Anfragen", "message": "Hallo! Ich habe Ihren Artikel über die Kosten für den Annapurna Circuit Trek gelesen.", "buttonText": "Preis für meine Gruppengröße und meinen Termin anfragen"}'::jsonb where section_id = '38766eb1-3571-4ff5-a505-1a72bf7499e4' and locale = 'de';
update public.articles set slug = 'annapurna-circuit-kosten' where id = '2adae2de-2deb-46df-adf2-b323e206d769';
update public.article_translations set title = 'Annapurna Circuit Trek: aktuelle Infos (November 2026)', intro = 'Der Annapurna Circuit und der Thorong La Pass sind seit dem 5. November 2026 geöffnet. Hier finden Sie den aktuellen Stand zu Weg, Wetter, Straßen, Flügen nach Jomsom und Genehmigungen.', card_text = 'Ist der Annapurna Circuit offen? Aktuelles zu Thorong La, Wetter, Straßen, Jomsom-Flügen und Genehmigungen (Nov. 2026).', cover_alt = 'Das Dorf Ngawal am Weg des Annapurna Circuit', highlight_tag = 'Geöffnet · geprüft am 5. Nov. 2026', updated_line = 'Stand: 5. Nov. 2026 · in der Saison wöchentlich geprüft', facts = '[{"icon": "wb_sunny", "label": "Thorong La (5.416 m):", "value": "Geöffnet"}, {"icon": "water_drop", "label": "Straßen", "value": "Geöffnet, Jeep bis Khangsar"}, {"icon": "altitude", "label": "Flüge nach Jomsom", "value": "Eingestellt"}, {"icon": "wb_twilight", "label": "Genehmigung", "value": "Nur ACAP (NPR 3.000)"}]'::jsonb, seo_keyword = 'Annapurna Circuit aktuell', seo_title = 'Annapurna Circuit aktuell: Ist der Trek geöffnet?', seo_description = 'Aktuelle Infos zu Weg, Wetter, Straßen, Flügen nach Jomsom und Genehmigungen am Annapurna Circuit.', help_heading = 'Sie möchten bald über den Thorong La?', help_text = 'Wir sagen Ihnen, wie die aktuellen Pass-, Straßen- und Wetterverhältnisse laut unseren Guides am Weg sind.', help_message = 'Hallo! Ich plane den Annapurna Circuit. Können Sie mir sagen, wie die Wegverhältnisse aktuell sind? Meine Trekdaten sind:' where article_id = '883e34b6-5a62-405c-a91b-9964caae3f0f' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der ", "type": "text"}, {"text": "Annapurna Circuit Trek", "type": "text", "marks": [{"type": "link", "attrs": {"href": "https://traveltonepal.com/treks/annapurna-circuit-trek"}}]}, {"text": " ist geöffnet, und der Thorong La Pass (5.416 m) wird täglich überquert. Weg, Straßen und Genehmigungen haben wir zuletzt am 5. November 2026 geprüft. Planen sollten Sie derzeit vor allem für die frostigen Nächte oberhalb von Manang und für die eingestellten Flüge von Pokhara nach Jomsom: Sie verlassen den Trek also mit dem Jeep.", "type": "text"}]}, {"type": "paragraph"}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Was", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Status", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Weg des Annapurna Circuit", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Durchgehend geöffnet", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thorong La Pass (5.416 m)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Geöffnet, täglich überquert", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Tilicho Lake (4.919 m)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Geöffnet, etwas Schnee auf dem oberen Wegabschnitt", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Straße Besisahar – Chame – Manang", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Geöffnet; Jeeps fahren jetzt bis Khangsar", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Straße Pokhara – Jomsom", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Seit 9. Okt. geöffnet, langsam an reparierten Stellen", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Flüge Pokhara – Jomsom", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Linienflüge eingestellt; nur Charterflüge", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Genehmigungen", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Nur ACAP; keine TIMS-Karte und kein lizenzierter Guide nötig", "type": "text"}]}]}]}]}, {"type": "paragraph"}]}}'::jsonb where section_id = 'b866d373-13de-4929-8eea-3b6e6baf497a' and locale = 'de';
update public.article_section_translations set content = '{"heading": "Fragen Sie uns", "message": "Hallo! Ich möchte den aktuellen Stand zum Annapurna Circuit wissen.", "buttonText": "Aktuelle Infos zum Annapurna Circuit Trek"}'::jsonb where section_id = '06bd16e9-6bc9-4b3d-9dd2-f180d872cb76' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja, der Annapurna Circuit Trek ist seit dem 5. November 2026 vollständig geöffnet. Sie können die gesamte Route gehen: von Besisahar (760 m) über Chame (2.670 m) und Manang (3.540 m), über den Thorong La (5.416 m) und hinunter nach Muktinath (3.800 m).", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Nach einem schweren Sturm Ende September 2026 war der Circuit kurzzeitig gesperrt. Schnee blockierte den Thorong La, und Erdrutsche unterbrachen die Straßen auf beiden Seiten des Annapurna-Massivs. Das Annapurna Conservation Area Project (ACAP) stellte Anfang Oktober wieder Genehmigungen aus, und die Trekker kamen schnell zurück. In den zwei Wochen bis zum 22. Oktober zählte das ACAP in Jomsom 772 ausländische Trekker, die über den Thorong La nach Mustang kamen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Wir aktualisieren diese Seite, sobald sich die Verhältnisse ändern, und in der Trekkingsaison mindestens einmal pro Woche. Unsere Informationen stammen aus Mitteilungen des ACAP, lokalen Nachrichten aus Manang und Mustang und von unseren eigenen Guides am Weg.", "type": "text"}]}]}, "heading": "Ist der Annapurna Circuit Trek derzeit geöffnet?", "tocLabel": ""}'::jsonb where section_id = '98de13f5-7e60-4ac8-85c9-b078a46395f8' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja, der Annapurna Circuit ist derzeit sicher für Trekker, die sich gut vorbereiten und in gleichmäßigem Tempo gehen. Im November erwarten Sie trockene Wege und stabiles Wetter, und genau deshalb ist er einer der besten Monate am Circuit.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Höhe bleibt das größte Risiko, steigen Sie deshalb langsam auf. Schlafen Sie oberhalb von Manang jede Nacht höchstens 300 bis 500 m höher, nehmen Sie den Akklimatisierungstag in Manang und trinken Sie viel Wasser. Bei starken Kopfschmerzen, Übelkeit oder Schwindel steigen Sie nicht weiter auf und sagen Ihrem Guide oder dem Lodgebesitzer Bescheid. Werden die Beschwerden schlimmer, steigen Sie ab.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Planen Sie jeden Tag so, dass Sie Ihr Teehaus früh erreichen, am besten bis zum Nachmittag. Ab Mittag frischt der Wind auf, die Temperaturen fallen schnell, sobald die Sonne hinter den Bergen verschwindet, und im November geht die Sonne gegen 17:00 Uhr unter. Gehen Sie nicht im Dunkeln, besonders nicht zwischen Yak Kharka, Thorong Phedi und dem Pass: Auf gefrorenem Boden biegt man dort leicht falsch ab, und es gibt kein Handynetz.", "type": "text"}]}]}, "heading": "Ist der Annapurna Circuit derzeit sicher?", "tocLabel": ""}'::jsonb where section_id = '621b9919-6878-4538-b170-ad99b8aaa39c' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja, der Thorong La Pass ist geöffnet und wird täglich überquert. Die letzte Sperrung dauerte vom 30. September bis etwa 6. Oktober 2026, als starker Schnee den Weg zwischen Thorong Phedi und Muktinath verschüttete. Ein Team von rund 20 Personen, organisiert vom Hotelverband Muktinath, räumte den Schnee und öffnete den Pass wieder für Trekker. Der Weg über den Thorong La ist frei und gut begangen; frühmorgens gibt es nahe dem Gipfel gefrorenen Boden und vereiste Stellen. ", "type": "text"}]}]}, "heading": "Ist der Thorong La Pass geöffnet?", "tocLabel": ""}'::jsonb where section_id = 'c2f45e5d-3165-436d-9a3c-634456a10ba0' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Das Wetter am Annapurna Circuit ist im November klar und trocken, mit sonnigen Tagen und kalten Nächten. Morgens haben Sie meist die klarste Sicht auf Annapurna II, Annapurna III, Gangapurna und Dhaulagiri. Nach Mittag ziehen Wolken und Wind auf, und am Thorong La kann der Wind schon am späten Vormittag stark und eisig sein. Im Laufe des Monats werden die Tage kürzer, sodass Trekker Ende November weniger Zeit haben, die Tagesetappe zu beenden.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Temperaturen im November nach Höhe", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Pro 1.000 Höhenmeter sinkt die Temperatur um rund 6 bis 7 °C, deshalb fühlt sich dieselbe Woche in Chame ganz anders an als in Thorong Phedi.", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Ort", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Höhe", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Tageshöchstwert", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Nächtlicher Tiefstwert", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Chame", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "2.670 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "15 °C", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "2 °C", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Jomsom", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "2.720 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "15 °C", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "2 °C", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Manang", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "3.540 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "10 °C", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "−4 °C", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thorong Phedi", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "4.450 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "4 °C", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "−10 °C", "type": "text"}]}]}]}]}, {"type": "paragraph", "content": [{"text": "Die Werte für Jomsom stammen aus den langjährigen Mittelwerten der Wetterstation Jomsom; dort fallen im November nur etwa 5 mm Regen. Die anderen Dörfer haben keine Wetterstation, ihre Werte sind daher anhand der Höhe aus den Daten von Jomsom geschätzt. Durch den Wind können sich die Nächte in Thorong Phedi und im Hochlager noch kälter anfühlen.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Wetteraussichten für Dezember", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Im Dezember ist es am Annapurna Circuit kälter, ruhiger und weniger vorhersehbar. Rechnen Sie mit Tageshöchst- und Nachttiefstwerten von etwa 13 °C und −1 °C in Chame, 7 °C und −6 °C in Manang sowie 1 °C und −12 °C in Thorong Phedi.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Himmel ist oft noch klar, aber ein einziger Schneefall kann den Thorong La tief verschneien und den Pass tagelang sperren. Deshalb bewerten wir den Dezember als „okay“, nicht als einen der besten Monate. Er eignet sich für erfahrene Trekker mit flexiblen Daten, einem warmen Schlafsack bis etwa −15 °C und der Geduld, in Manang zu warten, falls der Pass gesperrt ist. Der größte Lohn: weniger Trekker am Weg.", "type": "text"}]}]}, "heading": "Wetter am Annapurna Circuit aktuell", "tocLabel": ""}'::jsonb where section_id = 'ae2abf1e-b445-4706-9dc7-971c2c16eca3' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Beide Straßen zum und vom Annapurna Circuit sind geöffnet, nach den Sturmschäden im Herbst aber langsam. Die Linienflüge zwischen Pokhara und Jomsom sind eingestellt, daher ist die Straße derzeit der wichtigste Weg zurück.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Straße Besisahar – Chame – Manang", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Straße von Besisahar nach Chame und Manang ist geöffnet, und Jeeps fahren inzwischen über Manang hinaus bis Khangsar. Die meisten Trekker nehmen einen Touristenbus von Kathmandu nach Besisahar (176 km, rund 7 Stunden) und dann einen Jeep durch das Marsyangdi-Tal hinauf nach Chame (rund 65 km, 5–6 Stunden) über Ngadi, Jagat, Tal, Dharapani und Koto.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Diese Jeepstraße war sechs Tage lang durch Erdrutsche bei Khotro nahe Koto blockiert und wurde am 3. Oktober 2026 wieder geöffnet. Auch der Abschnitt zwischen Chame und Bhratang wurde beschädigt und ist noch holprig, rechnen Sie also mit Schlaglöchern und kurzen Stopps. Oberhalb von Manang reicht die Straße jetzt bis Khangsar (3.734 m), dem letzten Dorf vor dem Tilicho Lake. Die Fahrt von Manang nach Khangsar dauert etwa 30–60 Minuten, zu Fuß sind es rund 2 Stunden.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Straße Muktinath – Jomsom – Pokhara", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Straße von Muktinath nach Pokhara ist wieder geöffnet, aber die Fahrt ist ein langer, holpriger Tag. Die Jeeps legen rund 183 km über Jharkot, Kagbeni, Jomsom, Marpha, Ghasa, Tatopani und Beni zurück.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Überschwemmungen und Erdrutsche Ende September beschädigten die Straße von Beni nach Jomsom an 46 Stellen. Straßenbautrupps legten provisorische Abschnitte an, und am Abend des 9. Oktober 2026 wurde die Straße wieder geöffnet. An den reparierten Stellen stockt der Verkehr noch, planen Sie daher von Muktinath bis Pokhara 7–9 Stunden statt der üblichen 7 ein.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Flüge Jomsom – Pokhara", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Linienflüge zwischen Jomsom und Pokhara sind eingestellt. Tara Air und Summit Air haben ihre planmäßigen Flüge ab dem 19. bzw. 21. Oktober 2026 eingestellt, Berichten zufolge für etwa fünf Monate. Charterflüge gibt es weiterhin, sie sind aber deutlich teurer.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Normalerweise dauert der Flug nur 20 bis 25 Minuten und findet morgens statt, weil starke Nachmittagswinde im Kali-Gandaki-Tal Flüge verhindern. Der Flug war nie in unserem Paketpreis enthalten. Derzeit ist der Jeep ab Muktinath oder Jomsom der übliche Weg zurück nach Pokhara.", "type": "text"}]}]}, "heading": "Straßen und Flüge am Annapurna Circuit", "tocLabel": ""}'::jsonb where section_id = '1b92ef98-c0d6-473e-941f-3d43d17739e0' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Weg zum Tilicho Lake (4.919 m) ist geöffnet, auf dem oberen Abschnitt liegt aber etwas Schnee. Anfang Oktober 2026 hatte ihn starker Schnee blockiert; seit dem 27. Oktober gilt er wieder als begehbar. Fragen Sie vor dem Aufbruch in den Lodges in Khangsar oder Shree Kharka nach dem Schnee. Für unsere Gäste stimmen wir uns immer mit den Teehäusern vor Ort ab und prüfen die Wettervorhersage, bevor wir die Etappe des nächsten Tages planen.", "type": "text"}]}]}, "heading": "Zustand des Wegs zum Tilicho Lake", "tocLabel": ""}'::jsonb where section_id = 'a7f48d42-7011-4e6b-9a81-c79cd1422ce8' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Für den Annapurna Circuit brauchen Sie nur eine Genehmigung: das Annapurna Conservation Area Permit (ACAP). Es kostet NPR 3.000 für ausländische Trekker und NPR 1.000 für Staatsangehörige der SAARC-Länder und gilt auch für den Abstecher zum Tilicho Lake.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Für den Annapurna Circuit brauchen Sie weder eine TIMS-Karte noch einen lizenzierten Guide. Das Nepal Tourism Board hat 2023 eine Pflicht für lizenzierte Guides angekündigt, auf den Annapurna-Routen wird sie aber nicht umgesetzt. Ein guter Guide macht den Trek trotzdem leichter und sicherer, besonders am Tag über den Thorong La, und in unseren Paketen ist einer enthalten.", "type": "text"}]}]}, "heading": "Neues zu Genehmigungen und Trekkingregeln", "tocLabel": ""}'::jsonb where section_id = 'd4977834-28bb-428f-9d98-c3c30a17c933' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die Teehäuser am Annapurna Circuit sind in diesem Herbst geöffnet und gut besucht. Nach Everest ist dies im Oktober und November der meistbegangene Teehaus-Trek Nepals, und die wenigen Lodges in Thorong Phedi und im Hochlager sind zuerst belegt. Kommen Sie an diesen beiden Etappenorten früh am Nachmittag an oder bitten Sie Ihren Guide, von Manang aus vorab anzurufen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Planen Sie Ihr Bargeld, bevor Sie Kathmandu oder Besisahar verlassen. In Besisahar steht der letzte zuverlässige Geldautomat auf der Ostseite. Manang hat zwar einen Geldautomaten, der aber wegen Strom- oder Netzausfällen oft nicht funktioniert, und der nächste steht erst in Jomsom auf dem Rückweg.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Rechnen Sie am Weg mit NPR 2.500 bis 4.500 pro Person und Tag. Der niedrigere Betrag deckt drei einfache Mahlzeiten wie Dal Bhat, Tee, abgekochtes Wasser und das Laden des Handys. Beim höheren Betrag kommen heiße Duschen, westliches Essen, WLAN und Snacks hinzu. Die Preise steigen mit der Höhe, nehmen Sie daher genug Bargeld für 2 bis 3 zusätzliche Tage mit, falls eine Straßensperre oder Schneefall Sie länger am Weg festhält.", "type": "text"}]}]}, "heading": "Teehäuser, Andrang und Bargeld aktuell", "tocLabel": ""}'::jsonb where section_id = '8a6f7cfe-fa02-41fa-9db8-2823db81dc89' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Annapurna Circuit ist derzeit eine gute Wahl, wenn Sie Kälte und die geänderten Verkehrsverbindungen einplanen. Nehmen Sie einen Reservetag in Ihren Reiseverlauf auf, damit Sie bei einer kurzen Schneesperre am Thorong La den Pass nicht verpassen. Kaufen Sie Ihr ACAP in Kathmandu oder Pokhara, damit Sie in Besisahar nicht den doppelten Preis zahlen. Heben Sie Ihr gesamtes Bargeld für den Trek in Kathmandu oder Besisahar ab, denn der Geldautomat in Manang ist unzuverlässig. Planen Sie die Rückfahrt mit dem Jeep von Muktinath nach Pokhara ein, da die Linienflüge nach Jomsom eingestellt sind. Packen Sie Schlafsack und Daunenjacke für Nächte um −10 °C in Thorong Phedi ein.", "type": "text"}]}]}, "heading": "Was diese Neuigkeiten für Ihre Trekplanung bedeuten", "tocLabel": ""}'::jsonb where section_id = 'bf40f387-109d-434b-9d84-e721e7534649' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Dieses Protokoll listet alle Änderungen am Annapurna Circuit in dieser Saison auf, die neuesten zuerst.", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Datum", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Was sich geändert hat", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Was das für Sie bedeutet", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "5. Nov. 2026", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Nur die ACAP-Genehmigung ist nötig; keine TIMS-Karte und kein lizenzierter Guide.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Kaufen Sie das ACAP vor dem Start in Kathmandu oder Pokhara.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "27. Okt. 2026", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Der Weg zum Tilicho Lake ist nach dem Schnee von Anfang Oktober wieder begehbar.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Tilicho ist geöffnet; fragen Sie in Khangsar nach Schnee auf dem oberen Wegabschnitt.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "23. Okt. 2026", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "772 ausländische Trekker überquerten in den zwei Wochen bis zum 22. Okt. den Thorong La.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Auf dem Circuit ist wieder viel los; halten Sie einen Reservetag für Neuschnee frei.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "19. bis 21. Okt. 2026", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Linienflüge Pokhara – Jomsom für etwa fünf Monate eingestellt.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Planen Sie die Rückfahrt mit dem Jeep von Muktinath nach Pokhara.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "9. Okt. 2026", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Straße Beni – Jomsom nach Schäden an 46 Stellen wieder geöffnet.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Die Rückfahrtstraße ist wieder befahrbar; rechnen Sie mit 7–9 Stunden bis Pokhara.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Etwa 6. Okt. 2026", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thorong La vom Schnee geräumt und wieder geöffnet.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Trekker können wieder von Manang nach Muktinath gehen.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "3. Okt. 2026", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Straße Besisahar – Chame nach sechstägiger Blockade bei Khotro/Koto wieder geöffnet.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Jeeps fahren wieder nach Chame und Manang; Chame – Bhratang ist noch holprig.", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "30. Sep. 2026", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Starker Schnee und Überschwemmungen sperrten Thorong La, Tilicho und beide Straßen.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Trekking vorübergehend unterbrochen.", "type": "text"}]}]}]}]}, {"type": "paragraph"}]}, "heading": "Protokoll der Neuigkeiten zum Annapurna Circuit", "tocLabel": ""}'::jsonb where section_id = 'af48c02f-246b-497b-b083-ef7ff512a443' and locale = 'de';
update public.articles set slug = 'annapurna-circuit-aktuelle-infos' where id = '883e34b6-5a62-405c-a91b-9964caae3f0f';
update public.article_translations set title = 'Annapurna Circuit Trek: Karte und Route', intro = 'Auf der Route des Annapurna Circuit wandern Sie rund 100 km von Chame nach Muktinath und überqueren dabei den Thorong La Pass auf 5.416 m. Mit unseren Karten, der Tagesübersicht und dem Höhenprofil planen Sie jede Etappe.', card_text = 'Routenkarte, Tagesdistanzen und Höhen für den Annapurna Circuit, von Chame über den Thorong La nach Muktinath.', cover_alt = 'Blick auf das Annapurna-Massiv vom Weg des Annapurna Circuit', highlight_tag = 'Interaktive Karte & kostenlose PDF-Karte', updated_line = 'Wegverhältnisse für die Saison 2027 geprüft', facts = '[{"icon": "wb_sunny", "label": "Trekdistanz", "value": "Rund 100 km zu Fuß"}, {"icon": "water_drop", "label": "Höchster Punkt zu Fuß", "value": "Thorong La, 5.416 m"}, {"icon": "altitude", "label": "Kartenart", "value": "Interaktive Karte, PDF, Bild"}, {"icon": "wb_twilight", "label": "Start/Ende", "value": "Fahrt: Kathmandu, Trek: Chame/Muktinath"}]'::jsonb, seo_keyword = 'Annapurna Circuit Karte', seo_title = 'Annapurna Circuit Trek: Karte und Route', seo_description = 'Auf der Route des Annapurna Circuit wandern Sie rund 100 km von Chame nach Muktinath und überqueren dabei den Thorong La Pass auf 5.416 m. Mit unseren Karten, der Tagesübersicht und dem Höhenprofil planen Sie jede Etappe.', help_heading = 'Fragen zur Route des Annapurna Circuit?', help_text = 'Fragen Sie uns zu jeder Etappe auf der Karte, von der Jeepstraße nach Chame über die Überquerung des Thorong La bis zum Abstecher zum Tilicho Lake.', help_message = 'Hallo, ich sehe mir gerade die Karte des Annapurna Circuit an und habe eine Frage zur Route:' where article_id = '7b91d8d8-0fe4-4c9e-b1c7-7c0c62790658' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die Karte des Annapurna Circuit Trek zeigt eine Route, die im Bogen um die Nordseite des Annapurna-Massivs führt. Sie steigt von Besisahar durch das Marsyangdi-Tal hinauf, überquert den Thorong La Pass auf 5.416 m und führt durch das Kali-Gandaki-Tal hinunter nach Muktinath und Jomsom.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Laut Karte fahren Sie von Kathmandu nach Besisahar und Chame und wandern dann in 8 Tagen rund 100 km. Die Wanderroute führt vor dem Pass durch Upper Pisang, Ngawal, Manang, zum Tilicho Lake, nach Yak Kharka und Thorong Phedi. Der höchste Übernachtungsort ist Thorong Phedi auf 4.450 m, und von Muktinath bringt Sie die Straße zurück nach Pokhara und Kathmandu.", "type": "text"}]}]}, "heading": "Was zeigt die Karte des Annapurna Circuit?", "tocLabel": ""}'::jsonb where section_id = '1ee2879e-ed7c-4791-b2ca-12f6736b17f3' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Auf dieser Seite finden Sie die Karte zum ", "type": "text"}, {"text": "Annapurna Circuit Trek", "type": "text", "marks": [{"type": "link", "attrs": {"href": "https://traveltonepal.com/treks/annapurna-circuit-trek"}}]}, {"text": " in drei Formaten: als Kartenbild, als interaktive Google-Karte und als PDF zum Herunterladen. Unter den Karten folgen eine Tagesübersicht mit Distanzen und Höhen, das Höhenprofil, Abstecher, alternative Routen und die aktuellen Wegverhältnisse.", "type": "text"}]}]}}'::jsonb where section_id = '2317c9ab-810f-4815-b05a-af603f9480ad' and locale = 'de';
update public.article_section_translations set content = '{"heading": "Interaktive Google-Karte des Annapurna Circuit", "tocLabel": "Interaktive Karte"}'::jsonb where section_id = '79cb5cb5-727d-4d35-abe4-ba0798cd8542' and locale = 'de';
update public.article_section_translations set content = '{"title": "Karte des Annapurna Circuit", "caption": "Interaktive Google-Karte des Annapurna Circuit Trek"}'::jsonb where section_id = 'b4768f87-3dff-4a2a-8f80-cf3e478896f8' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "In der interaktiven Google-Karte können Sie jedes Dorf, jeden Aussichtspunkt und jeden Straßenabschnitt der Route heranzoomen. Sie hat einzelne Ebenen, die Sie ein- und ausblenden können:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Wanderroute:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Chame bis Muktinath, einschließlich des Abstechers zum Tilicho Lake", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Jeepstraßen:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Besisahar bis Chame sowie Muktinath bis Beni", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Übernachtungsorte:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " alle 13 Etappenorte mit ihren Höhen", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Wegpunkte:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Thorong La, Ice Lake, Tilicho Lake, Jomsom.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Hinweis: Die Karte dient nur der Planung. ", "type": "text", "marks": [{"type": "italic"}]}]}]}}'::jsonb where section_id = '02fbe3e3-baac-4bad-8bbe-1f2ebf46d12f' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph"}, {"type": "image", "attrs": {"alt": "Routenkarte des Annapurna Circuit Trek mit der 13-tägigen Route von Besisahar über Manang, den Tilicho Lake und den Thorong La Pass (5.416 m) nach Muktinath und Pokhara.", "width": 2482, "height": 1755, "photoId": "a78a9eae-38bc-4ea6-b685-ef6ebda805fc", "fileName": "annapurna-circuit-trek-with-tilicho-lake-map", "variantWidths": [400, 800, 1200, 1600, 2400]}}, {"type": "paragraph", "content": [{"text": "Bild: Vollständige Karte des Annapurna Circuit Trek ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Das Kartenbild zeigt die gesamte 13-tägige Route mit einem nummerierten Kreis an jedem Übernachtungsort. Nummer 1 ist Besisahar (760 m), Nummer 2 ist Chame (2.670 m), und die Nummern gehen weiter über Upper Pisang, Ngawal, Manang, Tilicho Base Camp, Shree Kharka, Yak Kharka und Thorong Phedi. Der Thorong La Pass ist mit 5.416 m als höchster Punkt des Treks markiert. Nach dem Pass führt die Route hinunter nach Muktinath (3.800 m) und auf der Straße zurück nach Pokhara und Kathmandu.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Karte ist schematisch, also nicht maßstabsgetreu. Zwei Dörfer, die auf der Karte nah beieinander liegen, können trotzdem einen ganzen Wandertag voneinander entfernt sein. Die tatsächlichen Distanzen und Gehzeiten finden Sie in der Tabelle zum Reiseverlauf weiter unten auf dieser Seite.", "type": "text"}]}]}, "heading": "Kartenbild des Annapurna Circuit", "tocLabel": "Kartenbild"}'::jsonb where section_id = 'cd1183ff-57a8-4c5d-be0c-b044a5694312' and locale = 'de';
update public.article_section_translations set content = '{"title": "Karte des Annapurna Circuit Trek mit dem Tilicho Lake", "description": "Karte des Annapurna Circuit mit dem Tilicho Lake"}'::jsonb where section_id = '8db20ed7-8f78-4ad6-912d-024b3f478695' and locale = 'de';
update public.article_section_translations set content = '{"heading": "Höhenprofil des Annapurna Circuit", "tocLabel": "Höhenprofil"}'::jsonb where section_id = '47278398-faa9-4bb0-85a7-849753fc86b6' and locale = 'de';
update public.article_section_translations set content = '{"heading": "Höhenprofil des Annapurna Circuit"}'::jsonb where section_id = 'f0a9fc41-d7da-43c9-b8c2-a5dbe3f0331f' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die Legende erklärt, was jede Linie, jede Zahl und jedes Symbol auf der Karte bedeutet. Die Linien zeigen, wie Sie unterwegs sind:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Haupt-Trekroute:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " der Weg, den Sie jeden Tag gehen", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Fahrt / Jeepstraße:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Abschnitte, die Sie mit Bus oder Jeep zurücklegen", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Abstecher:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Tageswanderungen, etwa zum Ice Lake ab Manang", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Andere Wege:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Treks in der Nähe, die an den Circuit anschließen", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Die nummerierten Kreise entsprechen den Tagen im Reiseverlauf. Bei Manang stehen zwei Nummern (5 und 6), weil Sie dort zur Akklimatisierung zwei Nächte bleiben. Weitere Symbole kennzeichnen Dörfer, Orte, Berggipfel, Pässe, Seen, Flüsse, Klöster, Tempel und Aussichtspunkte.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Service-Symbole helfen Ihnen, praktische Stopps zu planen. Sie zeigen die heißen Quellen in Tatopani, den Flughafen in Jomsom, Gesundheitsposten, Kontrollpunkte für Genehmigungen sowie Bus- und Jeephaltestellen. Alle Höhen auf der Karte sind in Metern angegeben, der Nordpfeil steht in der Ecke.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Berge, Täler und Distrikte auf der Karte", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Annapurna Circuit führt rund um das Annapurna-Massiv, deshalb zeigt die Karte viele der bekanntesten Gipfel Nepals:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Annapurna-Kette:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Annapurna I (8.091 m), Annapurna II (7.937 m), Annapurna III (7.555 m), Annapurna IV (7.525 m) und Gangapurna (7.455 m)", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Rund um Manang:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Tilicho Peak (7.134 m), Pisang Peak (6.091 m) und Chulu West (6.419 m)", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Über dem Kali Gandaki:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Dhaulagiri I (8.167 m), Tukuche Peak (6.920 m) und Nilgiri Nord (7.061 m)", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Weiter entfernt:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Manaslu (8.163 m) im Osten sowie Machhapuchhre (6.993 m), Annapurna South (7.219 m), Hiunchuli (6.441 m) und Lamjung Himal (6.983 m) im Süden", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Die Route verbindet zwei große Flusstäler. Das Marsyangdi-Tal führt Sie von Besisahar hinauf nach Manang. Der Thorong La verbindet es mit dem Kali-Gandaki-Tal, durch das Sie über Mustang hinunter nach Beni gelangen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Trek führt durch fünf Distrikte. Sie starten in Lamjung (Besisahar), wandern durch Manang (Chame bis Thorong La), wechseln nach Mustang (Muktinath, Jomsom und Marpha) und fahren durch Myagdi (Tatopani und Beni) nach Kaski (Pokhara). Mit der Landschaft wechseln auch die Menschen: Gurung-Dörfer im unteren Marsyangdi-Tal, Manangi und tibetisch-buddhistische Kultur im oberen Manang und Thakali-Dörfer im Kali-Gandaki-Tal.", "type": "text"}]}]}, "heading": "So lesen Sie die Kartenlegende", "tocLabel": ""}'::jsonb where section_id = '99c96e0e-f648-4a43-94a6-6b6964e8e9d7' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Annapurna Circuit Trek ist ein 13-tägiger Teehaus-Trek mit Start und Ende in Kathmandu und rund 100 km zu Fuß zwischen Chame und Muktinath. Hier die wichtigsten Fakten zur Route auf einen Blick:", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Fakt zur Route", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Details", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Start und Ende", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Kathmandu (1.400 m)", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Trek beginnt", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Chame (2.670 m), erreichbar mit Bus und Jeep", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Trek endet", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Muktinath (3.800 m), dann auf der Straße nach Pokhara", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Tage insgesamt", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "13 Tage, davon 1 Akklimatisierungstag in Manang", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Gehstrecke", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Rund 100 km an 8 Wandertagen", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Gehzeit", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Rund 47–49 Stunden, dazu 6 bis 8 Stunden für die Wanderung zum Ice Lake", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Höchster Punkt", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thorong La Pass, 5.416 m", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Höchster Übernachtungsort", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thorong Phedi, 4.450 m", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Unterkunft", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Jede Nacht in Teehäusern (einfachen Lodges)", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Genehmigung", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Annapurna Conservation Area Permit (ACAP)", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Beste Monate", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "März, April, Oktober und November", "type": "text"}]}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "In welcher Richtung Sie den Circuit gehen", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die meisten Trekker gehen den Annapurna Circuit gegen den Uhrzeigersinn, vom Marsyangdi-Tal im Osten ins Kali-Gandaki-Tal im Westen. In dieser Richtung gewöhnt sich Ihr Körper langsam an die Höhe. Sie übernachten in Chame (2.670 m), Upper Pisang (3.300 m), Ngawal (3.650 m) und Manang (3.540 m), bevor es höher hinaufgeht.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Auch der Aufstieg zum Thorong La ist von dieser Seite deutlich kürzer. Von Thorong Phedi (4.450 m) steigen Sie rund 966 m bis zum Pass auf. In der Gegenrichtung beginnen Sie den Passtag in Muktinath (3.800 m) und müssen rund 1.616 m am Stück aufsteigen, mit weniger Zeit zur Akklimatisierung.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Deshalb folgen unser Reiseverlauf und die meisten Teehäuser und Angebote am Weg der Richtung gegen den Uhrzeigersinn.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Straßenabschnitte und Wanderabschnitte", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Annapurna Circuit besteht teils aus Straße, teils aus Wanderweg: Am Anfang und am Ende fahren Sie, im hoch gelegenen Mittelteil wandern Sie. Straßen reichen inzwischen auf beiden Seiten in den Circuit hinein:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Ostseite (Fahrt):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Kathmandu bis Besisahar mit dem Touristenbus (176 km, rund 7 Stunden), dann mit dem Jeep durch das Marsyangdi-Tal hinauf nach Chame (rund 65 km, 5–6 Stunden)", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Mitte (zu Fuß):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Chame bis Muktinath zu Fuß, einschließlich des Abstechers zum Tilicho Lake und des Thorong La Pass", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Westseite (Fahrt):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Muktinath bis Pokhara mit Jeep und Bus über Jomsom und Beni (rund 183 km, 7 Stunden), dann Pokhara bis Kathmandu (200 km, rund 7 Stunden)", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "An manchen Stellen verläuft der Wanderweg nah an der Straße. Zwischen Chame und Bhratang teilen Sie sich einen Teil der Route mit der Straße, die im Oktober 2026 beschädigt wurde, für Wanderer aber offen bleibt. Oberhalb von Upper Pisang gibt es auf der oberen Route über Ghyaru und Ngawal überhaupt keine Straße.", "type": "text"}]}, {"type": "paragraph"}]}, "heading": "Die Route des Annapurna Circuit im Überblick", "tocLabel": ""}'::jsonb where section_id = '1b47718b-9158-4577-99a3-a3e5bd894faa' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der 13-tägige Reiseverlauf des Annapurna Circuit umfasst 2 Fahrtage zu Beginn, 8 Wandertage, 1 Akklimatisierungstag und 2 Fahrtage am Ende. Die Tabelle zeigt, wo Sie übernachten, wie hoch Sie kommen und wie weit Sie jeden Tag unterwegs sind:", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Tag", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Route", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Höchster Punkt", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Unterwegs", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Distanz", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "1", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Kathmandu → Besisahar", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "1.400 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Fahrt 7 Std.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "176 km", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "2", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Besisahar → Chame", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "2.670 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Jeep 5 bis 6 Std.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "65 km", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "3", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Chame → Upper Pisang", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "3.300 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Zu Fuß 5 bis 6 Std.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "14 km", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "4", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Upper Pisang → Ngawal", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "3.730 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Zu Fuß 4 bis 5 Std.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "10 km", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "5", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Ngawal → Manang", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "3.650 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Zu Fuß 4 Std.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "10 km", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "6", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Wanderung zum Ice Lake ab Manang", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "4.600 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Zu Fuß 6 bis 8 Std.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Tageswanderung", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "7", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Manang → Tilicho Base Camp", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "4.150 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Zu Fuß 7 Std.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "15 km", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "8", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Tilicho Base Camp → Tilicho Lake → Shree Kharka", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "4.919 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Zu Fuß 7 Std.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "15 km", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "9", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Shree Kharka → Yak Kharka", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "4.060 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Zu Fuß 7 Std.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "13 km", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "10", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Yak Kharka → Thorong Phedi", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "4.450 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Zu Fuß 4 Std.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "7 km", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "11", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thorong Phedi → Thorong La → Muktinath", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "5.416 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Zu Fuß 9 Std.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "16,2 km", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "12", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Muktinath → Pokhara", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "3.800 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Fahrt 7 Std.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "183 km", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "13", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Pokhara → Kathmandu", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "1.400 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Fahrt 7 Std.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "200 km", "type": "text"}]}]}]}]}, {"type": "paragraph", "content": [{"text": "Die Gehzeiten enthalten kurze Pausen, aber keine langen Mittagspausen. Ihr eigenes Tempo, das Wetter und die Wegverhältnisse können diese Zeiten um eine Stunde oder mehr verändern.", "type": "text"}]}, {"type": "paragraph"}]}, "heading": "Reiseverlauf des Annapurna Circuit: Distanz, Zeit und Höhe", "tocLabel": "Distanz, Zeit und Höhe"}'::jsonb where section_id = '1479c7aa-e6cd-4cdb-a734-eb50b4c49026' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die besten Abstecher am Annapurna Circuit beginnen in Manang und Braga. Sie helfen Ihrem Körper, sich vor dem Tilicho Lake und dem Thorong La an die Höhe zu gewöhnen. Die Regel ist einfach: tagsüber hoch wandern, tiefer schlafen. In unserem Reiseverlauf ist Tag 6 in Manang für eine dieser Wanderungen reserviert, meist zum Ice Lake.", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Abstecher", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Höchster Punkt", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Zeit", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Schwierigkeit", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Ice Lake (Kicho Tal) ab Manang", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "4.600 m (+1.060 m)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "6 bis 8 Std. hin und zurück", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Schwer: durchgehend steil", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Praken Gompa ab Manang", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "3.945 m (+405 m)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Rund 2 Std. Aufstieg", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Mittelschwer", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Chongkor-Aussichtspunkt ab Manang", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "3.900 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "1 bis 2 Std. hin und zurück", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Leicht bis mittelschwer", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Gangapurna Lake ab Manang", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Direkt oberhalb von Manang", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Rund 30 Min.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Leicht", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Milarepa-Höhle ab Braga", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "4.100 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Rund 2 Std. pro Richtung (rund 5 km)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Mittelschwer, steil", "type": "text"}]}]}]}]}, {"type": "paragraph", "content": [{"text": "Der Ice Lake ist die beste Wahl, wenn Sie sich gut fühlen und die stärkste Akklimatisierung möchten. Er bringt mehr als 1.000 Höhenmeter und bietet die weitesten Ausblicke auf die Annapurna-Kette. Praken Gompa und der Chongkor-Aussichtspunkt sind gute Optionen für einen kürzeren, leichteren Tag. Der Gangapurna Lake liegt so nah an Manang, dass Sie ihn noch am Nachmittag Ihrer Ankunft besuchen können.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Milarepa-Höhle ist mit dem tibetischen Dichter und Yogi Milarepa verbunden, der hier meditiert haben soll. Der Tilicho Lake gehört an Tag 8 zu unserem Hauptreiseverlauf und ist deshalb oben im Abschnitt zur Route beschrieben.", "type": "text"}]}]}, "heading": "Abstecher und Akklimatisierungswanderungen rund um Manang", "tocLabel": "Abstecher und Akklimatisierung"}'::jsonb where section_id = 'f7737dee-9efc-4a1b-a44b-b35de8f1e109' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die Karte des Annapurna Circuit zeigt eine einfache Form: hinauf durch das Marsyangdi-Tal, über den Thorong La auf 5.416 m und hinunter durch das Kali-Gandaki-Tal. Der anstrengende Teil liegt in der Mitte, zwischen Manang und Muktinath, wo Sie mehrere Tage auf rund 4.000 m unterwegs sind und den Pass am längsten Tag des Treks überqueren.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Nutzen Sie das Kartenbild, um die Route zu verstehen, die interaktive Google-Karte, um Dörfer und Abstecher zu prüfen, und die PDF-Karte als Reserve unterwegs. Entscheiden Sie vor der Reise, ob Sie den Abstecher zum Tilicho Lake machen möchten, planen Sie 2–3 Reservetage für Schnee oder Erdrutsche ein und informieren Sie sich über den aktuellen Zustand von Straßen und Pass.", "type": "text"}]}]}, "heading": "Planen Sie Ihre Route mit der Karte", "tocLabel": "Planung"}'::jsonb where section_id = '5909e0ac-4655-4c9b-8416-73a7579fc8e1' and locale = 'de';
update public.articles set slug = 'annapurna-circuit-karte-und-route' where id = '7b91d8d8-0fe4-4c9e-b1c7-7c0c62790658';
update public.article_translations set title = 'Annapurna Circuit Trek Packliste', intro = 'Drei Packlisten für den 13-tägigen Annapurna Circuit: für leichtes Gepäck, ohne Träger und mit Träger. Wählen Sie Ihre Liste und laden Sie die kostenlose Excel-Checkliste herunter.', card_text = 'Drei Packlisten für den Annapurna Circuit: leicht, ohne Träger und mit Träger, dazu eine kostenlose Excel-Checkliste.', cover_alt = 'Trekker mit Trekkingstöcken und Tagesrucksack auf dem verschneiten Weg zum Thorong La (5.416 m) am Annapurna Circuit', highlight_tag = 'Kostenlose Excel-Checkliste', updated_line = 'Aktualisiert für die Saison 2027/28', facts = '[{"icon": "landscape", "label": "Höchster Punkt", "value": "Thorong La, 5.416 m"}, {"icon": "water_drop", "label": "Kälteste Nacht", "value": "Etwa -10 °C in Thorong Phedi (Nov.)"}, {"icon": "altitude", "label": "Trägergepäck", "value": "Etwa 10 kg pro Trekker"}, {"icon": "wb_twilight", "label": "Schlafsack", "value": "Komforttemperatur -15 °C"}]'::jsonb where article_id = 'be026ee3-29eb-43e8-80b9-d2ada88fc675' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Auf dieser Seite finden Sie drei Packlisten für den ", "type": "text"}, {"text": "Annapurna Circuit Trek", "type": "text", "marks": [{"type": "link", "attrs": {"href": "https://traveltonepal.com/treks/annapurna-circuit-trek"}}]}, {"text": ". Wählen Sie die, die zu Ihrer Art zu trekken passt:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Leichtes Gepäck:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " erfahrene Wanderer, die ihren eigenen 35–40-Liter-Rucksack mit etwa 7–8 kg tragen.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Ohne Träger:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " die komplette Ausrüstung im eigenen 45–55-Liter-Rucksack, etwa 12–13 kg.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Mit Träger:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " ein Tagesrucksack mit etwa 5 kg für Sie und eine 10-kg-Reisetasche für Ihren Träger.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Alle drei Listen gelten für die 13-tägige Route von Besisahar (760 m) über den Thorong La (5.416 m), wo die Nächte in Thorong Phedi (4.450 m) im November auf etwa -10 °C abkühlen.", "type": "text"}]}]}}'::jsonb where section_id = '6cc99b9c-7508-404c-9d6d-397933ff0a03' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Für erfahrene Wanderer, die ihren eigenen 35- bis 40-Liter-Rucksack tragen und nur das Nötigste einpacken. Sie tragen etwa 7 bis 8 kg, den Rest haben Sie am Körper.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Kleidung und Schuhe", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Artikel", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Anzahl", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Gewicht (g)", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Saison", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Leihen oder kaufen", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Merino-T-Shirts", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "2", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "300", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Alle", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Kaufen", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thermo-Ober- und -Unterteil (auch zum Schlafen)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "1 Set", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"tex