update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die Gewichte in den Tabellen sind typische Werte, prüfen Sie also Ihre eigene Ausrüstung. Mit leichtem Gepäck tragen Sie etwa 7 bis 8 kg, ohne Träger etwa 10 kg (12 kg mit dem, was Sie am Körper tragen) und mit Träger etwa 5 kg im Tagesrucksack. Die Checkliste in Google Sheets hat für jede Liste einen eigenen Reiter.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Holen Sie sich die kostenlose Checkliste in Google Sheets:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Haken Sie beim Packen ab, filtern Sie nach Saison und sehen Sie, wie sich das Gewicht Ihres Gepäcks aktualisiert. Sie hat für jede Liste einen eigenen Reiter und lässt sich als Excel-Datei (.xlsx) herunterladen.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Packliste in Google Sheets ansehen", "type": "text", "marks": [{"type": "link", "attrs": {"href": "https://docs.google.com/spreadsheets/d/1xyDjpBfNjUjkMkYr-hxFtSUfs07UklFo/edit?usp=sharing&ouid=115561373469921138390&rtpof=true&sd=true"}}]}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Packliste als Excel-Datei (.xlsx) herunterladen", "type": "text", "marks": [{"type": "link", "attrs": {"href": "https://docs.google.com/spreadsheets/d/e/2PACX-1vQ4v6ZkLdHVXXiLxS30-E26EVuR7iDUi6G41JborVCWbdj5gXMZbBl1ZykQL2elDQ/pub?output=xlsx"}}]}]}]}]}, {"type": "paragraph"}]}, "heading": "Kostenlose Packliste (Google Sheets und Excel)", "tocLabel": ""}'::jsonb where section_id = '4eb963b1-0537-41bf-b741-9b294670e121' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Genug Bargeld.", "type": "text", "marks": [{"type": "bold"}]}, {"text": " In Besisahar steht der letzte verlässliche Geldautomat; der in Manang fällt oft aus.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Stirnlampe.", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Die Tage am Tilicho und am Thorong La beginnen um 4:00 Uhr im Dunkeln.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Isolierhülle für die Flasche.", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Am Morgen der Passüberquerung gefriert das Wasser.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Grödel (Microspikes).", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Schnee kann den Thorong La zu jeder Jahreszeit bedecken.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Powerbank.", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Ab Chame kostet das Laden Geld, und in Thorong Phedi ist es nur eingeschränkt möglich.", "type": "text"}]}]}]}, {"type": "paragraph"}]}, "heading": "5 Dinge, die Trekker am häufigsten vergessen", "tocLabel": ""}'::jsonb where section_id = '2dce254a-4cd1-4d4d-b34e-c57c5d8afe07' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Je höher Sie kommen, desto kälter werden die Nächte, warme Ausrüstung zählt also vor allem ab Manang.", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Ort (Höhe)", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "März Tag / Nacht", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "April Tag / Nacht", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Okt. Tag / Nacht", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Nov. Tag / Nacht", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Chame (2.670 m)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "16 °C / 2 °C", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "19 °C / 5 °C", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "18 °C / 6 °C", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "15 °C / 2 °C", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Manang (3.540 m)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "10 °C / -3 °C", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "13 °C / -1 °C", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "13 °C / 0 °C", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "10 °C / -4 °C", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thorong Phedi (4.450 m)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "4 °C / -9 °C", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "7 °C / -7 °C", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "7 °C / -6 °C", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "4 °C / -10 °C", "type": "text"}]}]}]}]}, {"type": "paragraph", "content": [{"text": "Im unteren Marsyangdi-Tal fällt von Juni bis September starker Monsunregen. Ab Manang liegt die Route im Regenschatten und bleibt deutlich trockener.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Packen für den Frühling (März bis April)", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Nehmen Sie vollständige Winterschichten mit, denn in Thorong Phedi sinken die Temperaturen im März nachts auf -9 °C. Früh in der Saison, wenn am Pass tiefer Schnee liegen kann, gehören auch Grödel und Gamaschen ins Gepäck.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Packen für den Herbst (Oktober bis November)", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Im Herbst ist der Himmel am klarsten, doch die Nächte werden jede Woche kälter, im November bis -10 °C in Thorong Phedi. Behalten Sie die Grödel im Gepäck: 2026 sperrte Schnee den Thorong La vom 30. September bis etwa 6. Oktober.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Packen für Dezember, Mai und September", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Dezember:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " der wärmste Schlafsack, Grödel und Gamaschen; in Thorong Phedi sinken die Nachttemperaturen auf etwa -12 °C.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Mai:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " eine gute Regenjacke für die Wolken vor dem Monsun.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "September:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Regenkleidung, eine Rucksackhülle und Blutegelsocken für den nassen unteren Wegabschnitt.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Januar–Februar (Schnee sperrt oft den Pass) und Juni–August (Erdrutsche blockieren die Straßen) empfehlen wir nicht.", "type": "text"}]}]}, "heading": "Wetter und Höhe am Annapurna Circuit", "tocLabel": ""}'::jsonb where section_id = '82d7e45e-537c-4f9d-81fa-8c4be300eb31' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Tragen Sie dünne Schichten, die Sie im Laufe des Tages an- und ausziehen. Oberhalb von Manang trocknet Kleidung langsam, wählen Sie also schnell trocknende Stoffe.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Basisschichten", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Nehmen Sie 2 bis 3 schnell trocknende Oberteile und 1 bis 2 Thermo-Sets mit. Behalten Sie oberhalb von Manang ein sauberes Thermo-Set nur zum Schlafen.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Fleece und Daunenjacke", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Tragen Sie das Fleece an kalten Morgen beim Gehen. Die Daunenjacke mit Kapuze (etwa -15 °C) ist für die Abende und den Start zum Thorong La um 4:00 Uhr; Sie können eine in Thamel oder Lakeside leihen.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Wasserdichte Jacke und Trekkinghose", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Eine wasserdichte Jacke und Hose schützen Sie vor Regen auf dem unteren Abschnitt und vor Wind am Pass. Nehmen Sie 2 Trekkinghosen mit.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Mütze, Handschuhe und Sonnenschutz", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Packen Sie eine Mütze, einen Sonnenhut mit breiter Krempe, einen Schlauchschal sowie dünne und gefütterte Handschuhe ein. Eine Sonnenbrille der Kategorie 3–4 schützt Ihre Augen am Tilicho-See und am Thorong La vor dem grellen Schnee.", "type": "text"}]}]}, "heading": "Kleidungsschichten für den Annapurna Circuit", "tocLabel": ""}'::jsonb where section_id = '58647919-bdd6-4c97-a069-bd68fee851e0' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Tragen Sie wasserdichte, halbhohe oder hohe Trekkingschuhe, die Sie zu Hause auf langen Wanderungen eingelaufen haben. Nehmen Sie 4 bis 5 Paar Trekkingsocken mit, 1 dickes Paar zum Schlafen und leichte Sandalen für die Abende im Teehaus.", "type": "text"}]}]}, "heading": "Trekkingschuhe und Schuhwerk", "tocLabel": ""}'::jsonb where section_id = '36314ba7-58ef-4071-a0c7-04bb553440f5' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Nehmen Sie einen Schlafsack mit einer Komforttemperatur von etwa -15 °C mit, denn die Zimmer im Tilicho-Basislager, in Thorong Phedi und im Thorong-Hochlager sind nicht beheizt. Ein Inlett spendet zusätzliche Wärme, und Ohrstöpsel helfen in den vollen Lodges im Oktober. Bewahren Sie Handy, Powerbank und Trinkflasche nachts im Schlafsack auf.", "type": "text"}]}]}, "heading": "Schlafsack und Ausrüstung für die Nacht im Teehaus", "tocLabel": ""}'::jsonb where section_id = '5c8d5c41-9cf0-46d8-b066-03a2edf9a314' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Das sind die zwei härtesten Tage des Treks, und beide beginnen vor Sonnenaufgang.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Der Tag am Thorong La (5.416 m)", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "An Tag 11 gehen Sie von Thorong Phedi (4.450 m) über den Pass nach Muktinath (3.800 m): etwa 15 bis 16 km in 8 bis 10 Stunden, Start um 4:00 Uhr. Nehmen Sie Stirnlampe, Daunenjacke, warme Handschuhe, eine isolierte Flasche, Snacks, Sonnenbrille, Trekkingstöcke und bei Schnee Grödel mit. Erst beim Abstieg in der Nähe von Muktinath gibt es wieder Handyempfang.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Abstecher zum Tilicho-See (4.919 m)", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "An Tag 7 gehen Sie von Manang zum Tilicho-Basislager (4.150 m), etwa 15 km in 7 Stunden, und queren nach Shree Kharka eine aktive Erdrutschzone. An Tag 8 steigen Sie etwa 770 m zum See auf und gehen zurück nach Shree Kharka. Nehmen Sie Daunenjacke, 1 bis 1,5 l Wasser, Snacks und Stöcke mit.", "type": "text"}]}]}, "heading": "Ausrüstung für den Thorong La und den Tilicho-See", "tocLabel": ""}'::jsonb where section_id = '361bc346-b0d4-481e-bb27-51ed7ff03715' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Tagesrucksack und Reisetasche für den Träger", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Ihr Tagesrucksack mit 25 bis 35 l fasst 4 bis 5 kg für alles, was Sie tagsüber brauchen. Wenn Sie einen Träger buchen, bekommen Sie von uns kostenlos eine Reisetasche; halten Sie sie bei etwa 10 kg und packen Sie Kleidung in Packsäcke.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Trekkingstöcke und Stirnlampe", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Stöcke schonen Ihre Knie auf den 1.600 m Abstieg vom Thorong La nach Muktinath. Eine Stirnlampe brauchen Sie für die Starts vor der Morgendämmerung und bei Stromausfällen im Teehaus.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Trinkflaschen und Wasseraufbereitung", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Nehmen Sie insgesamt 2 l mit und verwenden Sie 3–4 Entkeimungstabletten pro Tag. Abgekochtes Wasser wird mit der Höhe teurer, und eine isolierte Flasche verhindert, dass das Wasser am Pass gefriert.", "type": "text"}]}]}, "heading": "Trekkingausrüstung und Zubehör", "tocLabel": ""}'::jsonb where section_id = '77d91910-1d65-4706-a8bd-e3e0ca6adffe' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Halten Sie die Kulturtasche klein und verwenden Sie täglich Sonnencreme mit LSF 50+. Fragen Sie vor der Reise Ihren Arzt nach Medikamenten gegen Höhenkrankheit. Am Ruhetag in Manang (Tag 6) hält die Himalayan Rescue Association im Frühling und Herbst um 15:00 Uhr einen kostenlosen Vortrag über die Höhe.", "type": "text"}]}]}, "heading": "Hygiene, Erste Hilfe und Medikamente gegen Höhenkrankheit", "tocLabel": ""}'::jsonb where section_id = '8dab44ac-27ea-46f9-b4db-548a454dba9c' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Nehmen Sie eine Powerbank mit 10.000 bis 20.000 mAh mit, denn ab Chame kostet das Laden Geld, und in Thorong Phedi und im Hochlager ist es nur eingeschränkt möglich. Nepal Telecom hat 4G in Chame und Manang, doch von Thorong Phedi bis zum Thorong La gibt es keinen Empfang.", "type": "text"}]}]}, "heading": "Elektronik, Laden und Handyempfang", "tocLabel": ""}'::jsonb where section_id = '26b30628-de7f-405d-abc8-560fc82b23ea' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Nehmen Sie Ihren Reisepass (noch mindestens 6 Monate gültig), 2 bis 4 Passfotos und eine Versicherung mit, die Trekking bis 5.500 m und Hubschrauberrettung abdeckt (eine Rettung kostet etwa 2.500 bis 5.000 USD). Ihre ACAP-Genehmigung organisieren wir. Rechnen Sie mit 2.500 bis 4.500 NPR pro Tag plus 2 bis 3 Extratage und heben Sie das Geld in Kathmandu oder Besisahar ab, wo der letzte verlässliche Geldautomat steht.", "type": "text"}]}]}, "heading": "Dokumente, Genehmigungen und Bargeld", "tocLabel": ""}'::jsonb where section_id = '8935e6c4-4d9f-4a29-b61b-b45b22fb5600' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "An vier Tagen geht es über holprige, erdrutschgefährdete Straßen: Kathmandu nach Besisahar (176 km, 7 Std.), mit dem Jeep nach Chame (65 km, 5 bis 6 Std.), Muktinath nach Pokhara (183 km, 7 Std.) und Pokhara nach Kathmandu (7 Std.). Halten Sie im Tagesrucksack einen Schlauchschal gegen Staub, Tabletten gegen Reiseübelkeit, Snacks, Wasser und eine warme Schicht bereit.", "type": "text"}]}]}, "heading": "Packen für die Jeep- und Bustage", "tocLabel": ""}'::jsonb where section_id = 'fe0e26ff-171c-4c1c-b14d-1092f4e11c42' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Daunenjacke, Schlafsack, Stöcke und Grödel können Sie in Thamel (Kathmandu) oder Lakeside (Pokhara) leihen. Prüfen Sie vor dem Bezahlen Reißverschlüsse, das Temperaturetikett des Schlafsacks und die Verschlüsse der Stöcke. Schuhe, Basisschichten und Medikamente bringen Sie am besten von zu Hause mit, denn die Läden unterwegs haben wenig Auswahl.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Mit dieser Liste sind Sie für jede Etappe gerüstet, von Besisahar auf 760 m bis zum Thorong La auf 5.416 m. Laden Sie die Checkliste in Google Sheets herunter, haken Sie beim Packen ab und halten Sie das Trägergepäck bei etwa 10 kg.", "type": "text"}]}]}, "heading": "Trekkingausrüstung in Kathmandu und Pokhara leihen oder kaufen", "tocLabel": ""}'::jsonb where section_id = 'ab709369-6646-4d22-8858-30965f25b416' and locale = 'de';
update public.articles set slug = 'annapurna-circuit-packliste' where id = 'be026ee3-29eb-43e8-80b9-d2ada88fc675';
update public.article_translations set title = 'Beste Reisezeit für den Annapurna Circuit: Der Ratgeber Monat für Monat', intro = 'Klarer Herbsthimmel oder warme Frühlingstage? So ist jeder Monat auf dem Annapurna Circuit wirklich, von Chame über den Thorong La bis hinunter nach Muktinath.', card_text = 'Der Annapurna Circuit Monat für Monat: Wetter, Temperaturen, Andrang und wann der Thorong La offen ist.', cover_alt = 'Eine Familie beim Trekking auf dem Annapurna Circuit im November', highlight_tag = 'Am besten: Herbst & Frühling', updated_line = 'Aktualisiert für die Saison 2027/2028', facts = '[{"icon": "wb_sunny", "label": "Beste Monate", "value": "März bis April, Oktober bis November"}, {"icon": "water_drop", "label": "Nasseste Monate", "value": "Juni bis August (Monsun)"}, {"icon": "altitude", "label": "Höchster Punkt", "value": "Thorong La, 5.416 m"}, {"icon": "calendar_month", "label": "Ruhigste Monate", "value": "Dezember bis Februar"}]'::jsonb, seo_keyword = 'beste Reisezeit Annapurna Circuit', seo_title = 'Beste Reisezeit Annapurna Circuit: Wetter Monat für Monat', seo_description = 'Die beste Reisezeit für den Annapurna Circuit ist März bis April und Oktober bis November. Wetter, Temperaturen und Bedingungen am Thorong La pro Monat.', month_notes = '[{"crowds": "low", "onTheTrail": "Kältester Monat; tiefer Schnee kann den Thorong La und den Weg zum Tilicho sperren"}, {"crowds": "low", "onTheTrail": "Noch sehr kalt; Schnee am Pass, gegen Monatsende längere Tage"}, {"crowds": "busy", "onTheTrail": "Klare Morgen, windige Nachmittage; später Schnee am Pass möglich"}, {"crowds": "busy", "onTheTrail": "Wärmster stabiler Monat; klare Morgen, Wolken ab Mittag"}, {"crowds": "medium", "onTheTrail": "Warm und diesig; Wolken ziehen bis zum Mittag auf"}, {"crowds": "low", "onTheTrail": "Monsun beginnt; Regen, Blutegel und Erdrutsche unterhalb von Manang"}, {"crowds": "very-low", "onTheTrail": "Stärkster Regen auf dem unteren Teil; leichter Regen oberhalb von Manang"}, {"crowds": "very-low", "onTheTrail": "Nasse Straßen und seltene Aussicht; trockener Regenschatten oberhalb von Manang"}, {"crowds": "medium", "onTheTrail": "Monsun endet; anfangs Schauer, gegen Monatsende klarer"}, {"crowds": "busiest", "onTheTrail": "Klar, trocken und stabil; volle Lodges in Thorong Phedi"}, {"crowds": "busy", "onTheTrail": "Trockenster Monat; klarste Sicht und kalte Nächte"}, {"crowds": "low", "onTheTrail": "Trocken und ruhig; sehr kalt am Basislager, der Pass kann gesperrt sein"}]'::jsonb where article_id = 'cc95d11e-0204-4717-b35b-5f6bf8723c73' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die beste Reisezeit für den ", "type": "text"}, {"text": "Annapurna Circuit Trek", "type": "text", "marks": [{"type": "link", "attrs": {"href": "https://traveltonepal.com/treks/annapurna-circuit-trek"}}]}, {"text": " ist März bis April und Oktober bis November. In diesen vier Monaten sind die Wege trocken, die Berge klar zu sehen und die Chancen am größten, den Thorong La (5.416 m) wie geplant zu überqueren.", "type": "text"}]}]}}'::jsonb where section_id = 'f6e36f6e-933d-40a0-bd13-e703e3e49215' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Mai, September und Dezember sind gute Alternativen, jeweils mit einem Haken. Im Mai sind die Tage warm und die Teehäuser ruhiger, doch bis zum Mittag ziehen Wolken auf und die Sicht wird diesig. Im September endet der Monsun, daher können Schauer und Erdrutsche auf der Straße von Besisahar nach Chame Ihren Start verzögern. Der Dezember bietet klare Sicht und deutlich weniger Trekker, doch nachts sinken die Temperaturen in Thorong Phedi auf etwa −12 °C, und Schnee gegen Monatsende kann den Pass sperren.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Januar und Februar sind riskant, weil tiefer Schnee den Thorong La tagelang sperren kann. Von Juni bis August ist Monsun, mit starkem Regen, Blutegeln und Erdrutschen auf der unteren Hälfte der Route.", "type": "text"}]}]}}'::jsonb where section_id = '6da6e45e-3291-4094-8bb5-127a30c6ab97' and locale = 'de';
update public.article_section_translations set content = '{"heading": "Wetter am Annapurna Circuit nach Monaten", "tocLabel": ""}'::jsonb where section_id = 'e2cf79b0-8dd4-4cbb-b016-9752e7572376' and locale = 'de';
update public.article_section_translations set content = '{"heading": "Das Wetter im Überblick"}'::jsonb where section_id = '39b34ec5-ce34-40cd-aad0-c1a66d4d20f9' and locale = 'de';
update public.article_section_translations set content = '{"heading": "Wetter am Annapurna Circuit als Tabelle"}'::jsonb where section_id = '8c265c38-55ae-42e1-9c1e-e096451fda8d' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Auch in der Hauptsaison kann das Wetter umschlagen. 2026 sperrten Stürme den Thorong La ab dem 26. September, bis er im Oktober wieder geräumt war.", "type": "text"}]}]}}'::jsonb where section_id = '5c6fab56-7013-42dd-acc3-7dc5bd6adbdd' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Auf dem Annapurna Circuit sinkt die Temperatur um etwa 6,5 °C je 1.000 Höhenmeter. So kann sich derselbe Tag in Chame nach Frühling und am Thorong La nach tiefem Winter anfühlen. Über die Reiter sehen Sie die Tageshöchst- und Nachttiefstwerte an sieben Punkten entlang der Route, von Chame (2.670 m) bis Muktinath (3.800 m).", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Monat", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Manang (3.540 m)", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Thorong La (5.416 m)", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Januar", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "5 °C / −7 °C", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "−7 °C / −19 °C", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Februar", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "7 °C / −6 °C", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "−5 °C / −18 °C", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "März", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "10 °C / −3 °C", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "−2 °C / −15 °C", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "April", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "13 °C / −1 °C", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "2 °C / −13 °C", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Mai", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "15 °C / 3 °C", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "4 °C / −9 °C", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Juni", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "17 °C / 7 °C", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "6 °C / −5 °C", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Juli", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "18 °C / 9 °C", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "6 °C / −3 °C", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "August", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "17 °C / 9 °C", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "6 °C / −3 °C", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "September", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "16 °C / 6 °C", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "4 °C / −5 °C", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Oktober", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "13 °C / 0 °C", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "1 °C / −11 °C", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "November", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "10 °C / −4 °C", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "−2 °C / −15 °C", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dezember", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "7 °C / −6 °C", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "−5 °C / −18 °C", "type": "text"}]}]}]}]}, {"type": "paragraph", "content": [{"text": "Der Regenschatten hinter Manang hält den oberen Teil der Route fast das ganze Jahr über trocken. In Jomsom fallen selbst im Monsun nur 32–47 mm Regen pro Monat, während das bewaldete Tal unterhalb von Chame durchnässt ist. Weiter oben ist die Kälte die größere Herausforderung: In Thorong Phedi liegen die Nachttemperaturen von Oktober bis Mai unter dem Gefrierpunkt, und am Pass selbst in jedem Monat des Jahres.", "type": "text"}]}]}, "heading": "Temperaturen am Annapurna Circuit nach Monaten", "tocLabel": "Temperaturen nach Monaten"}'::jsonb where section_id = '35cdd8bb-53e8-4290-b56b-9cfab2a866ce' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Herbst ist die beste und zugleich belebteste Reisezeit auf dem Annapurna Circuit. Der Monsun hat den Staub aus der Luft gewaschen, die Wege sind trocken, und die Bergsicht ist so klar wie sonst nie im Jahr. Nach Everest ist es auch die geschäftigste Zeit auf allen Teehaus-Treks in Nepal, daher sind die Lodges in Thorong Phedi und im Hochlager schon am frühen Nachmittag voll. Buchen Sie Ihren Trek rechtzeitig und planen Sie, die hoch gelegenen Lodges bis zur Mittagszeit zu erreichen.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Annapurna Circuit im Oktober", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Oktober ist der beliebteste Monat auf dem Circuit, weil das Wetter meist klar, trocken und stabil ist. Weiter unten sind die Tage angenehm, in Chame werden etwa 18 °C erreicht, und in Manang sind es tagsüber rund 13 °C und nachts 0 °C. In Thorong Phedi (4.450 m) sinken die Temperaturen nachts auf etwa −6 °C, ein warmer Schlafsack ist also schon ab der ersten Woche wichtig.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Anfang Oktober kann es noch einen späten Sturm geben. 2026 sperrten starker Regen und Schnee den Thorong La ab dem 26. September und blockierten die Straße von Besisahar nach Chame sechs Tage lang, bis beide wieder frei waren. Planen Sie einen Reservetag ein, selbst im besten Monat des Jahres.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Dashain und Tihar, die größten Feste Nepals, fallen meist in den Oktober oder Anfang November. Busse und Hotels rund um Kathmandu sind in diesen Wochen stark ausgelastet, bestätigen Sie Ihren Transport daher frühzeitig.", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Fest", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "2027", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "2028", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dashain (Vijaya Dashami / Tika)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "10. Oktober", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "28. September", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Tihar (Bhai Tika)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "31. Oktober", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "19. Oktober", "type": "text"}]}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Annapurna Circuit im November", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der November ist der trockenste Monat auf dem Circuit und bietet die klarste Bergsicht. In Jomsom fallen im November im Schnitt nur 4,6 mm Regen, und die Tage sind meist klar und trocken.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Preis dafür sind kältere Nächte. In Manang sinkt die Temperatur nach Einbruch der Dunkelheit auf etwa −4 °C, in Thorong Phedi auf etwa −10 °C, während die Tageshöchstwerte in Manang bei rund 10 °C bleiben. Packen Sie für den Morgen am Pass eine Daunenjacke und Handschuhe ein.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In der zweiten Monatshälfte wird es leerer, daher ist Ende November eine gute Wahl, wenn Sie klaren Himmel und ruhigere Lodges möchten. Leichter Schneefall kann den Thorong La trotzdem für ein, zwei Tage sperren, behalten Sie also den Reservetag bei.", "type": "text"}]}]}, "heading": "Herbst (Oktober–November): Hauptsaison", "tocLabel": "Herbst: Hauptsaison"}'::jsonb where section_id = 'b84e2934-2993-4260-854e-23b4c7d27799' and locale = 'de';
update public.article_section_translations set content = '{"text": "Ich empfehle vor allem Mitte November. Die Wege sind weniger voll, Sie bekommen bessere Zimmer und auch die Bergsicht ist besser. Planen Sie vor Ihrem Rückflug ab Kathmandu immer einen Reservetag ein, denn manchmal reicht ein einziger Sturm, um den Pass zu sperren. Brechen Sie am Tag der Überquerung bis 4:00 Uhr in Thorong Phedi oder im Hochlager auf."}'::jsonb where section_id = 'ff3eb751-8919-4466-a1c9-bb674225bf8f' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Frühling ist die zweitbeste Reisezeit auf dem Annapurna Circuit, mit warmen Tagen, langen Tageslichtstunden und einem ab April verlässlich begehbaren Pass. Die Morgen sind meist klar, doch am Nachmittag ziehen Wolken und Wind auf, starten Sie also jeden Tag früh. März und April sind so belebt wie der Herbst, der Mai ist ruhiger.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Annapurna Circuit im März", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der März ist ein guter Monat zum Trekken, doch im hohen Abschnitt kann noch Winterschnee liegen. Gerade Anfang März kann später Schnee auf dem Aufstieg von Thorong Phedi zum Hochlager und zum Pass liegen. Erkundigen Sie sich in Manang nach den Bedingungen, bevor Sie weiter aufsteigen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Nächte sind noch kalt. In Manang sinkt die Temperatur auf etwa −3 °C, in Thorong Phedi auf etwa −9 °C, tagsüber erreicht Manang rund 10 °C. Oberhalb von Manang ist es nachmittags oft windig, planen Sie also, bis zum frühen Nachmittag am Ziel zu sein.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die zweite Märzhälfte ist die sicherere Wahl. Die Tage sind länger, der Schnee hat sich gesetzt, und auf dem Weg sind mehr Frühlingstrekker unterwegs.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Annapurna Circuit im April", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der April ist der beste Frühlingsmonat auf dem Circuit und der wärmste stabile Monat des Jahres. Manang erreicht tagsüber etwa 13 °C und nachts −1 °C, in Thorong Phedi sinkt die Temperatur auf etwa −7 °C. In Chame ist es mit rund 19 °C tagsüber mild.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Morgen sind klar, Wolken ziehen meist erst nach dem Mittagessen auf. In den Wäldern des unteren Marsyangdi-Tals blüht der Rhododendron und bringt Farbe in die Etappen unterhalb von Chame.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der April ist auch ein guter Monat für den Abstecher zum Tilicho-See. Der See liegt auf 4.919 m, ein steiler Aufstieg von 800 m und etwa 3,5 Stunden vom Tilicho-Basislager (4.150 m). Der Weg zum Basislager quert eine schmale Erdrutschzone, die am sichersten ist, wenn sie trocken und eisfrei ist.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Annapurna Circuit im Mai", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Mai ist einer der besten Monate auf dem Annapurna Circuit, vor allem wenn Sie ruhigere Wege als im März und April suchen. Die Tage sind die wärmsten des Frühlings, mit etwa 15 °C tagsüber und 3 °C nachts in Manang, und Chame erreicht rund 21 °C.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Kälte ist so gut zu ertragen wie zu keiner anderen Zeit der Trekkingsaisons. In Thorong Phedi sinkt die Temperatur nachts nur auf etwa −3 °C, der frühe Start zum Thorong La ist also angenehmer als im März oder November.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Haken ist die Sicht. Vor dem Monsun ziehen bis zum Mittag Wolken auf, und die Luft ist diesiger als im Herbst, daher ist die Bergsicht am frühen Morgen am besten. Gehen Sie kurz nach Sonnenaufgang los und planen Sie, bis zum frühen Nachmittag am Ziel zu sein.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Mai eignet sich auch für den Abstecher zum Tilicho-See (4.919 m), weil der Schnee auf dem hohen Weg größtenteils geschmolzen ist. Wählen Sie am besten die erste Monatshälfte, bevor der Monsun Ende Mai oder Anfang Juni einsetzt.", "type": "text"}]}]}, "heading": "Frühling (März–Mai): Zweitbeste Reisezeit", "tocLabel": "Frühling: Zweitbeste Zeit"}'::jsonb where section_id = '8bd4f787-0609-43d6-ac21-584c563b22be' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Winter auf dem Annapurna Circuit ist klar, trocken und ruhig, doch tiefer Schnee kann den Thorong La sperren. Der Himmel ist oft strahlend blau und die Wege sind fast leer. Die Herausforderung ist die Kälte: Nachts sinkt die Temperatur in Thorong Phedi auf −12 °C bis −13 °C, und starker Schneefall kann Überquerungen tagelang verhindern.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Annapurna Circuit im Dezember", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Dezember ist der beste Wintermonat für den Annapurna Circuit. Der Himmel ist klar und trocken, mit nur etwa 5 mm Regen in Jomsom im ganzen Monat, sodass die Bergsicht von Chame bis Muktinath klar bleibt.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Hauptgrund für den Dezember ist die Ruhe. Der Herbstandrang ist vorbei, Sie können sich Ihr Teehaus meist aussuchen und bekommen ein besseres Zimmer, selbst in Thorong Phedi und im Hochlager.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Preis dafür ist die Kälte, die mit jedem Höhenmeter spürbarer wird. Manang erreicht tagsüber etwa 7 °C und nachts −6 °C, in Thorong Phedi sinkt die Temperatur nachts auf etwa −12 °C, und am Pass selbst bleibt es auch mittags unter dem Gefrierpunkt. Nehmen Sie einen Schlafsack mit, der deutlich unter den Gefrierpunkt ausgelegt ist, und eine richtige Daunenjacke.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Auch der Zeitpunkt im Monat zählt. In der zweiten Dezemberhälfte steigt das Schneerisiko am Thorong La, starten Sie also nach Möglichkeit in der ersten Woche und planen Sie mindestens einen Reservetag für den Pass ein.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Annapurna Circuit im Januar", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Januar ist der kälteste Monat auf dem Circuit, und für die Überquerung des Thorong La empfehlen wir ihn nicht. Manang erreicht tagsüber nur etwa 5 °C, nachts sinkt die Temperatur auf −7 °C. In Thorong Phedi bleibt es den ganzen Tag unter dem Gefrierpunkt, mit Höchstwerten um −1 °C und Tiefstwerten um −13 °C.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Tiefer Schnee kann den Pass sperren und macht den Weg zum Tilicho unsicher. Einige Lodges in Thorong Phedi und im Hochlager schließen eventuell für die Saison, erkundigen Sie sich also vor dem Aufbruch in Manang, welche geöffnet sind.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Wenn Sie im Januar trekken, betrachten Sie den Pass als Zugabe, nicht als sicheres Ziel. Planen Sie zwei oder drei Reservetage ein und seien Sie bereit, in Manang umzukehren, falls der Pass gesperrt ist.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Annapurna Circuit im Februar", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Februar ähnelt dem Januar, mit sehr kalten Nächten und möglichem Schnee am Pass. Manang erreicht tagsüber etwa 7 °C und nachts −6 °C, in Thorong Phedi sinkt die Temperatur auf etwa −12 °C. Gegen Monatsende werden die Tage länger und etwas wärmer.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In den Dörfern des oberen Manang-Tals wird tibetischer Buddhismus gelebt, und Losar, das tibetische Neujahr, fällt oft in den Februar. Wer dann trekkt, erlebt in den Dörfern Gebetsfahnen, Klosterrituale und Familienfeste.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Februar eignet sich für erfahrene Wintertrekker mit flexiblen Terminen. Wenn Ihre Termine feststehen, warten Sie lieber auf Ende März oder April.", "type": "text"}]}]}, "heading": "Winter (Dezember–Februar): Kalt und ruhig", "tocLabel": "Winter"}'::jsonb where section_id = '698a55c6-f9bf-4562-9a58-cd5df1090e3e' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Monsun teilt den Annapurna Circuit in zwei Hälften. Unterhalb von Manang bekommt das Marsyangdi-Tal starken Regen, dichte Wolken, Blutegel und Erdrutsche. Oberhalb von Manang und auf der Seite von Jomsom hält das Annapurna-Massiv den meisten Regen ab, sodass die hohe Route mit nur 32–47 mm pro Monat in Jomsom recht trocken bleibt.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Annapurna Circuit im Juni", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Im Juni beginnt der Monsun, und wir raten von diesem Monat ab. Im unteren Marsyangdi-Tal nimmt der Regen im Laufe des Monats zu und bringt Wolken, Blutegel und die ersten Erdrutsche auf der Straße von Besisahar nach Chame.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Temperaturen sind warm. Chame erreicht tagsüber etwa 23 °C, Manang etwa 17 °C tagsüber und 7 °C nachts, und in Thorong Phedi bleibt es mit etwa 1 °C knapp über dem Gefrierpunkt.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Oberhalb von Manang hält der Regenschatten den Weg recht trocken, mit nur etwa 32 mm Regen in Jomsom im Juni. Wenn Sie unbedingt im Juni trekken möchten, starten Sie in der ersten Woche, bevor sich der Monsun voll entfaltet, und planen Sie zwei Reservetage für Verzögerungen auf der Straße ein.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Annapurna Circuit im Juli", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Juli ist der Höhepunkt des Monsuns auf dem Annapurna Circuit und einer der schwierigsten Monate zum Trekken. Unterhalb von Manang regnet es an den meisten Tagen stark, und Erdrutsche können die Jeepstraße nach Chame tagelang blockieren.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Er ist auch der wärmste Monat des Jahres. Manang erreicht tagsüber etwa 18 °C und nachts 9 °C, in Thorong Phedi sinkt die Temperatur nur auf etwa 3 °C. Selbst Jomsom im Regenschatten erlebt seinen nassesten Monat, mit etwa 47 mm Regen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Wege sind fast leer und die Täler grün, doch an den meisten Tagen verdecken Wolken die Berge. Wir empfehlen den Juli nur erfahrenen Trekkern mit flexiblen Terminen, die auf die Aussicht verzichten können.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Annapurna Circuit im August", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der August ist einer der unsicheren Monate für den Annapurna Circuit, und wir raten von ihm ab. Das Problem ist nicht der Weg oberhalb von Manang, sondern die Straßen hinein und hinaus. Die 65 km lange Jeepstraße von Besisahar nach Chame dauert unter normalen Bedingungen 5 bis 6 Stunden, und Erdrutsche im Monsun können sie tagelang blockieren.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Straße am Ende ist genauso anfällig. Die holprige Straße von Beni nach Jomsom entlang des Kali Gandaki wurde durch die Stürme 2026 an 46 Stellen beschädigt, und bei starkem Regen ist die ganze Strecke anfällig für Erdrutsche.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Temperaturen sind die wärmsten des Jahres. Chame erreicht etwa 23 °C, Manang etwa 17 °C tagsüber und 9 °C nachts, und selbst in Thorong Phedi bleibt es mit etwa 3 °C über dem Gefrierpunkt. Bergsicht ist allerdings selten, weil an den meisten Tagen Wolken über den Gipfeln hängen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Wenn der August Ihre einzige Möglichkeit ist, rechnen Sie mit Verzögerungen und packen Sie für Regen auf dem unteren Teil der Route. Planen Sie mindestens zwei Reservetage für Straßensperrungen auf dem Hin- und Rückweg ein.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Annapurna Circuit im September", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Im September endet der Monsun, daher ist er eine brauchbare Wahl, wenn Sie in der zweiten Monatshälfte starten. Anfang September gibt es noch Schauer, Wolken und Erdrutschgefahr auf den Straßen, während die letzten Wochen oft klar und grün sind.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Temperaturen sind noch mild. Chame erreicht tagsüber etwa 22 °C, Manang etwa 16 °C tagsüber und 6 °C nachts, und in Thorong Phedi sinkt die Temperatur auf etwa 0 °C. In Jomsom fallen im Monat nur noch etwa 36 mm Regen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Späte Stürme sind trotzdem möglich. 2026 sperrten Stürme Ende September den Thorong La vom 30. September bis etwa 6. Oktober, ebenso den Weg zum Tilicho und Teile der Straßen. Wenn Sie im September starten, planen Sie mindestens zwei Reservetage ein und bleiben Sie bei Ihren Terminen flexibel.", "type": "text"}]}]}, "heading": "Monsun (Juni–September): Unten Regen, oben trocken", "tocLabel": "Monsun"}'::jsonb where section_id = '1e39dc37-6bd0-4e95-8a9d-e7d47e064fcd' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Thorong La (5.416 m) ist der höchste Punkt am Annapurna Circuit, und seine Bedingungen bestimmen die beste Reisezeit. Die Überquerung von Thorong Phedi nach Muktinath ist etwa 15 km lang und dauert rund 8 bis 10 Stunden, mit etwa 1.000 m Aufstieg und 1.600 m Abstieg.", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Abschnitt", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Strecke", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Zeit", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Weg", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thorong Phedi (4.450 m) → Hochlager (4.880 m)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "1 km", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "1 Std.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Sehr steiler Aufstieg", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Hochlager → Thorong La (5.416 m)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "3,5 km", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "3,5 Std.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Gleichmäßiger Aufstieg mit mehreren falschen Gipfeln", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Thorong La → Chabarbu (4.190 m)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "7 km", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "3,5 Std.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Sehr steiler Abstieg", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Chabarbu → Muktinath (3.800 m)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "3,5 km", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "1 Std.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Sanfter Abstieg", "type": "text"}]}]}]}]}, {"type": "paragraph", "content": [{"text": "Von März bis November ist der Pass meist offen, doch ein Sturm kann ihn in jedem Monat für einige Tage sperren. Von Dezember bis Februar kann tiefer Schnee ihn länger sperren, und einige Lodges unterhalb des Passes schließen eventuell. Am Pass selbst liegen die Nachttemperaturen in jedem Monat des Jahres unter dem Gefrierpunkt.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Egal zu welcher Jahreszeit: Brechen Sie vor der Morgendämmerung in Thorong Phedi oder im Hochlager auf. Ab dem späten Vormittag frischt der Wind auf, und wer früh startet, ist oben, solange der Schnee noch fest ist. Planen Sie einen Reservetag ein, im Winter zwei oder mehr.", "type": "text"}]}]}, "heading": "Bedingungen am Thorong La nach Jahreszeit", "tocLabel": "Bedingungen am Thorong La"}'::jsonb where section_id = '0eea5c30-5a81-4386-a36f-e3686fab7527' and locale = 'de';
update public.article_section_translations set content = '{"items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Beide sind hervorragend, doch der November ist etwas besser, wenn Sie klare Sicht und weniger Menschen möchten. Im Oktober kann es Anfang des Monats noch einen Sturm geben. Der November ist trockener und ruhiger, vor allem ab Monatsmitte, die Nächte sind aber kälter, bis etwa −10 °C in Thorong Phedi.", "type": "text"}]}]}, "question": "Ist der Oktober oder der November besser für den Annapurna Circuit?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja, aber nur mit flexiblen Terminen und richtiger Kälteausrüstung. Der Dezember ist der beste Wintermonat, mit klarem Himmel und ruhigen Teehäusern. Im Januar und Februar kann tiefer Schnee den Thorong La tagelang sperren, und einige Lodges in Thorong Phedi und im Hochlager schließen eventuell.", "type": "text"}]}]}, "question": "Kann man den Annapurna Circuit im Winter gehen?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Nein, nach starkem Schneefall kann der Thorong La in jedem Monat gesperrt sein. Am häufigsten ist das von Dezember bis März, doch auch im Frühling und Herbst können Stürme ihn sperren. Planen Sie vor der Überquerung immer mindestens einen Reservetag ein.", "type": "text"}]}]}, "question": "Ist der Thorong La das ganze Jahr offen?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "In Thorong Phedi (4.450 m) sinkt die Temperatur nachts im Januar auf etwa −13 °C und im Oktober auf etwa −6 °C. Am Thorong La (5.416 m) liegt sie nachts in jedem Monat des Jahres unter dem Gefrierpunkt. In Manang (3.540 m) ist es milder, mit Nachttiefstwerten zwischen −7 °C im Januar und 9 °C im Juli.", "type": "text"}]}]}, "question": "Wie kalt wird es auf dem Annapurna Circuit?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Das ist möglich, aber nicht zu empfehlen. Von Juni bis August treffen starker Regen, Blutegel und Erdrutsche das untere Marsyangdi-Tal sowie die Straßen hinein und hinaus. Oberhalb von Manang hält der Regenschatten den Weg recht trocken, das Hauptrisiko sind also Verzögerungen auf der Straße, weniger das Wandern selbst.", "type": "text"}]}]}, "question": "Kann man den Annapurna Circuit während des Monsuns gehen?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "April, Mai, Oktober und November sind die besten Monate für den Abstecher zum Tilicho-See (4.919 m). Der Weg zum Tilicho-Basislager quert eine schmale Erdrutschzone, die am sichersten ist, wenn sie trocken und eisfrei ist. Im Winter und im Monsun können Schnee, Eis oder Steinschlag den Abstecher gefährlich machen.", "type": "text"}]}]}, "question": "Wann ist die beste Reisezeit für den Tilicho-See?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Planen Sie im Frühling und Herbst mindestens einen Reservetag ein, im Winter zwei oder drei. Nutzen Sie sie bei schlechtem Wetter am Thorong La oder bei Verzögerungen auf den Straßen Besisahar–Chame und Beni–Jomsom. Im Monsun sollten Sie zwei Reservetage für Erdrutsche auf den Straßen einplanen.", "type": "text"}]}]}, "question": "Wie viele Reservetage sollte ich einplanen?"}]}'::jsonb where section_id = 'fdd6cf94-abc5-4019-b63b-993e6b92012b' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Unser Annapurna Circuit Trek dauert 13 Tage ab Kathmandu und zurück, inklusive des Abstechers zum Tilicho-See und rund 100 km zu Fuß. Er kostet ab 550 USD pro Person für Gruppen von 3 bis 5 Personen und umfasst Transport, einen lizenzierten Guide, Teehauszimmer und Ihre ACAP-Genehmigung. ", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Für März bis April und Oktober bis November sollten Sie früh buchen, denn die Lodges in Thorong Phedi und im Hochlager sind zuerst ausgebucht. Nennen Sie uns Ihre Termine, und wir prüfen vor Ihrem Aufbruch die Bedingungen am Pass und auf den Straßen.", "type": "text"}]}]}, "heading": "Planen Sie Ihren Annapurna Circuit Trek", "tocLabel": "Planung"}'::jsonb where section_id = 'f7bd8535-85e3-4959-8aad-bde0ae8f812a' and locale = 'de';
update public.article_section_translations set content = '{"heading": "Wählen Sie Ihre Annapurna-Termine mit uns", "message": "Hallo! Ich möchte in der Annapurna-Region trekken. Welchen Monat würden Sie mir für meine Termine empfehlen?", "buttonText": "Termine per WhatsApp anfragen"}'::jsonb where section_id = '629ef680-de34-405b-8ac8-9f5ce4b21b2e' and locale = 'de';
update public.articles set slug = 'beste-reisezeit-annapurna-circuit' where id = 'cc95d11e-0204-4717-b35b-5f6bf8723c73';
update public.article_translations set title = 'Thorong La sicher überqueren: Tipps eines Guides für den Passtag', intro = 'Der Thorong La (5.416 m) ist der höchste Punkt des Annapurna Circuit und sein längster Tag. Ein Guide, der Gruppen über den Pass führt, erklärt, wie Sie sich vorbereiten, wie der Tag abläuft und wann Sie umkehren sollten.', card_text = 'Akklimatisierung, Start vor der Morgendämmerung, Kleidung und wann man am hohen Pass des Circuit umkehrt.', cover_alt = 'Kahle Hänge mit Schneestreifen rund um den Thorong-La-Pass am Annapurna Circuit', highlight_tag = '5.416 m · der höchste Punkt des Circuit', updated_line = 'Aktualisiert für die Saison 2026/2027', facts = '[{"icon": "altitude", "label": "Passhöhe", "value": "5.416 m"}, {"icon": "schedule", "label": "Passtag", "value": "8–10 Std. Gehzeit"}, {"icon": "route", "label": "Von / nach", "value": "Thorong Phedi–Muktinath"}, {"icon": "wb_twilight", "label": "Startzeit", "value": "Gegen 4–5 Uhr"}]'::jsonb, seo_keyword = 'Thorong La überqueren', seo_title = 'Thorong La sicher überqueren: Tipps eines Guides', seo_description = 'Thorong La (5.416 m) am Annapurna Circuit überqueren: Akklimatisierung, Startzeit, Kleidung und wann Sie umkehren, erklärt von einem Guide vor Ort.' where article_id = 'ed902421-007c-4e31-b3b5-e281366964cb' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Thorong La ist nicht technisch, aber hoch und lang. Akklimatisieren Sie sich in Manang, übernachten Sie in Thorong Phedi oder im High Camp, starten Sie vor der Morgendämmerung, gehen Sie langsam und gleichmäßig, und seien Sie bereit umzukehren, wenn jemand ernste Anzeichen der Höhenkrankheit zeigt oder das Wetter umschlägt.", "type": "text"}]}]}}'::jsonb where section_id = 'd2584893-c45d-4166-b0b5-77231e664a1a' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ich komme aus Samagaon unterhalb des Manaslu und führe seit vielen Jahren Gruppen über die hohen Pässe von Manaslu und Annapurna. Der Thorong La ist der Pass, vor dem die meisten Trekker Respekt haben, und das zu Recht: Für die meisten ist er der höchste Punkt, den sie je zu Fuß erreichen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Mit der richtigen Vorbereitung wird er zu einem Tag, an den Sie sich aus den richtigen Gründen erinnern. So planen wir ihn.", "type": "text"}]}]}}'::jsonb where section_id = 'bc48e849-5747-4df4-8c6d-9f73c27bd670' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Unser Reiseverlauf für den Circuit sieht einen ganzen Tag in Manang (3.540 m) vor, mit einer Wanderung hinauf zur Praken Gompa (3.945 m) und zurück. Hoch steigen und tiefer schlafen hilft Ihrem Körper, sich anzupassen. Ab Manang steigen wir langsam auf: nach Yak Kharka (4.050 m), dann nach Thorong Phedi (4.450 m).", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Trinken Sie 3–4 Liter Wasser, Tee oder Suppe am Tag", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Gehen Sie langsam, auch wenn Sie sich stark fühlen", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Sagen Sie Ihrem Guide sofort Bescheid bei Kopfschmerzen, Übelkeit oder ungewöhnlicher Müdigkeit", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Sprechen Sie vor der Reise mit Ihrem Arzt über Medikamente gegen Höhenkrankheit", "type": "text"}]}]}]}]}, "heading": "Akklimatisieren, bevor es hoch hinausgeht", "tocLabel": "Akklimatisierung"}'::jsonb where section_id = '27c05b9a-0279-47f6-8eb8-6ce84266734a' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Leichte Beschwerden sind über 3.500 m häufig: leichte Kopfschmerzen, schlechter Schlaf, weniger Appetit, mehr Müdigkeit als sonst. Meist bessern sie sich mit Ruhe, Flüssigkeit und langsamerem Tempo. Sagen Sie Ihrem Guide trotzdem Bescheid, denn er überprüft jeden Abend alle und braucht das vollständige Bild.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Beschwerden, die schlimmer statt besser werden, sind etwas anderes. Kopfschmerzen, die auf Ruhe nicht ansprechen, Erbrechen, Verwirrtheit, Ungeschicklichkeit oder Atemnot in Ruhe sind Warnzeichen. Dann heißt es: nicht weiter aufsteigen und, wenn die Beschwerden anhalten, absteigen.", "type": "text"}]}]}, "heading": "Die Anzeichen der Höhenkrankheit", "tocLabel": "Warnzeichen"}'::jsonb where section_id = '2ce833bf-f97d-44cc-8b6b-17955a1d405b' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Meist brechen wir gegen 4–5 Uhr mit Stirnlampe in Thorong Phedi auf. Der erste steile Anstieg zum High Camp (etwa 4.880 m) dauert ungefähr eine Stunde. Danach steigt der Weg stetig über Moränen und oft Schnee bis zu den Gebetsfahnen am Pass, für die meisten Gruppen weitere 3–4 Stunden.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Nach Fotos und einem heißen Getränk oben beginnt der lange Abstieg nach Muktinath (3.800 m): rund 1.600 Höhenmeter hinunter auf steilem, losem Untergrund. Viele Trekker finden den Abstieg schwerer als den Aufstieg. Lassen Sie sich Zeit und nutzen Sie Ihre Stöcke. Die meisten Gruppen erreichen Muktinath am frühen Nachmittag.", "type": "text"}]}]}, "heading": "Der Passtag Schritt für Schritt", "tocLabel": "Der Passtag"}'::jsonb where section_id = 'bdb96300-b2ba-4e6f-b625-6824354a0b62' and locale = 'de';
update public.article_section_translations set content = '{"items": ["Daunenjacke und warme Mütze", "Isolierte Handschuhe und dazu ein dünnes Paar", "Stirnlampe mit Ersatzbatterien", "2 Liter Wasser in isolierten Flaschen", "Snacks, die Sie auch erschöpft gern essen", "Sonnenbrille und Sonnencreme", "Trekkingstöcke für den Abstieg", "Grödel, wenn Ihr Guide sagt, dass der Schnee sie erfordert"], "heading": "Packliste für den Passtag"}'::jsonb where section_id = 'c6d831f3-f268-4086-bb83-52c7714f2df6' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Kehren Sie um, wenn", "type": "text", "marks": [{"type": "bold"}]}, {"text": " jemand in der Gruppe starke Kopfschmerzen hat, die nicht besser werden, verwirrt ist, unsicher auf den Beinen steht oder in Ruhe sehr außer Atem ist. Das können Anzeichen einer ernsten Höhenkrankheit sein, und die Behandlung heißt Abstieg. Diese Entscheidung trifft Ihr Guide, und sie steht nicht zur Diskussion.", "type": "text"}]}]}}'::jsonb where section_id = '25367287-4f4c-4c41-bb6f-df810aa92310' and locale = 'de';
update public.article_section_translations set content = '{"text": "Am Thorong La ist der Gipfel erst die halbe Strecke. Ich spare die Kräfte aller für den Abstieg nach Muktinath, und Umkehren macht mir nie etwas aus. Der Pass ist auch nächste Saison noch da."}'::jsonb where section_id = '69631c26-0651-470a-ae68-2d4167d4143e' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Überquert wird der Pass meist von Ende September bis November und von März bis Mai. Schnee kann ihn jederzeit für einen Tag oder länger sperren, und im Winter ist er oft für längere Zeit geschlossen. Am späten Vormittag weht oben oft ein starker, kalter Wind, ein weiterer Grund, warum wir so früh aufbrechen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Wenn Sie ", "type": "text"}, {"text": "Nar Phu", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/nar-phu-valley-trek"}}]}, {"text": " mit dem Circuit kombinieren, haben Sie bereits den Kang La (5.320 m) überquert, eine ausgezeichnete Vorbereitung auf den Thorong La wenige Tage später.", "type": "text"}]}]}, "heading": "Wetter und Jahreszeit", "tocLabel": "Wetter"}'::jsonb where section_id = '8e93f9ea-45a9-4e19-be15-3590b29485f2' and locale = 'de';
update public.article_section_translations set content = '{"alt": "Ein türkisfarbener Gletschersee unterhalb des Gangapurna-Gletschers bei Manang", "caption": "Gangapurna-Gletscher und -See bei Manang, eine schöne Wanderung am Akklimatisierungstag"}'::jsonb where section_id = '9a830f26-795c-4d7a-b8f7-f239b51d1e9a' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Das Thorong High Camp liegt höher und verkürzt den Passtag um etwa eine Stunde. Thorong Phedi liegt tiefer, was meist besser für Schlaf und Körper ist. Wir entscheiden für jede Gruppe neu: Sind alle gut akklimatisiert und ist das Wetter stabil, kann das High Camp passen; tut sich jemand schwer, bleiben wir in Phedi.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "So oder so: Gehen Sie früh ins Bett. Der Wecker klingelt lange vor Sonnenaufgang.", "type": "text"}]}]}, "heading": "High Camp oder Thorong Phedi?", "tocLabel": "Übernachtung"}'::jsonb where section_id = 'f23ac923-ea3d-4f77-b4c6-a4602cfaaf6c' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Für die Höhe können Sie zu Hause nicht trainieren, aber Sie können sich den Rest des Treks leichter machen. Gehen Sie in den 6–8 Wochen vor dem Abflug mit leichtem Rucksack bergauf oder Treppen, und machen Sie mindestens ein paar lange Tage mit 5–6 Stunden auf den Beinen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Kräftige Beine machen den steilen Abstieg nach Muktinath viel angenehmer, und eine gute Grundfitness lässt Ihnen mehr Energie für die dünne Luft am Pass.", "type": "text"}]}]}, "heading": "Training vor dem Circuit", "tocLabel": "Training"}'::jsonb where section_id = 'b3e4db9d-cec1-4319-831c-a0bac1e426b7' and locale = 'de';
update public.article_section_translations set content = '{"items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "5.416 m (17.769 ft). Er ist der höchste Punkt des Annapurna Circuit und einer der höchsten Trekkingpässe der Welt.", "type": "text"}]}]}, "question": "Wie hoch ist der Thorong La?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Nein. Es ist ein Wanderpass ohne Seile und ohne Klettern. Sie brauchen eine gute Fitness, warme Kleidung und eine gründliche Akklimatisierung. An vereisten Morgen können Grödel helfen.", "type": "text"}]}]}, "question": "Brauche ich Klettererfahrung, um den Thorong La zu überqueren?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Wir warten in Thorong Phedi oder Manang, bis das Wetter aufklart. Deshalb haben unsere Reiseverläufe einen Puffertag. Bleibt der Pass gesperrt, kehren wir um und planen mit Ihnen eine andere Route.", "type": "text"}]}]}, "question": "Was passiert, wenn der Pass gesperrt ist?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Er ist lang und steil, stellenweise mit losem Geröll. Gehen Sie langsam, nutzen Sie Trekkingstöcke und trinken Sie weiter. Die meisten sind müde, aber glücklich, wenn sie Muktinath erreichen.", "type": "text"}]}]}, "question": "Ist der Abstieg nach Muktinath schwierig?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Fast alle überqueren den Pass von Manang nach Muktinath, also gegen den Uhrzeigersinn. Der Aufstieg von dieser Seite ist sanfter und gibt Ihnen auf dem Weg nach oben mehr Zeit zur Akklimatisierung.", "type": "text"}]}]}, "question": "In welcher Richtung überquert man den Thorong La am besten?"}]}'::jsonb where section_id = 'f72b915a-378c-4344-ac00-262edfeac411' and locale = 'de';
update public.article_section_translations set content = '{"heading": "Planen Sie Ihren Circuit mit einem Guide, der den Pass kennt", "message": "Hallo! Ich plane den Annapurna Circuit und hätte gern Tipps für die Überquerung des Thorong La.", "buttonText": "Tsering auf WhatsApp fragen"}'::jsonb where section_id = '1e0faebc-adb7-46c7-b257-5520eb2a639f' and locale = 'de';
update public.articles set slug = 'thorong-la-sicher-ueberqueren' where id = 'ed902421-007c-4e31-b3b5-e281366964cb';
update public.article_translations set title = 'Ihr erster Trek im Himalaya: welche Region in Nepal?', intro = 'Poon Hill, Langtang, Mardi Himal oder Tamang Heritage Trail? So wählen Sie einen ersten Trek in Nepal mit großen Bergen, der Einsteigern entgegenkommt – von jemandem, der selbst dort angefangen hat.', card_text = 'Vier großartige erste Treks im Vergleich: Tage, Höhe, Anreise und für wen sich welcher eignet.', cover_alt = 'Steinhäuser eines Dorfes an einem grünen Hang unter Schneegipfeln in der Annapurna-Region', highlight_tag = 'Beste Zeit: März–Mai & Okt.–Nov.', updated_line = 'Aktualisiert für die Saison 2026/2027', facts = '[{"icon": "schedule", "label": "Am kürzesten", "value": "Poon Hill, 5 Tage"}, {"icon": "route", "label": "Ohne Flug", "value": "Langtang, Tamang Heritage"}, {"icon": "altitude", "label": "Höchster Punkt", "value": "3.165–4.773 m"}, {"icon": "calendar_month", "label": "Beste Monate", "value": "März–Mai, Okt.–Nov."}]'::jsonb, seo_keyword = 'erster Trek Himalaya', seo_title = 'Erster Trek im Himalaya: welche Region in Nepal?', seo_description = 'Ihr erster Trek im Himalaya? Poon Hill, Langtang, Mardi Himal und Tamang Heritage Trail im Vergleich: Tage, Höhe, Anreise und für wen welcher passt.' where article_id = 'ac62b559-7614-4b51-8f07-1e82816caf61' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Für die meisten Menschen ist der beste erste Trek im Himalaya ", "type": "text"}, {"text": "Poon Hill", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (5 Tage, 3.210 m), wenn die Zeit knapp ist, oder das ", "type": "text"}, {"text": "Langtang Valley", "type": "text", "marks": [{"type": "bold"}]}, {"text": " (10 Tage, ohne Flüge), wenn Sie zwischen Gletschern wandern möchten. ", "type": "text"}, {"text": "Mardi Himal", "type": "text", "marks": [{"type": "bold"}]}, {"text": " passt zu fitten Wanderern, die einen ruhigen Grat suchen, und der ", "type": "text"}, {"text": "Tamang Heritage Trail", "type": "text", "marks": [{"type": "bold"}]}, {"text": " ist der sanfteste, mit Übernachtungen bei Gastfamilien.", "type": "text"}]}]}}'::jsonb where section_id = 'a6b69248-e5a0-489f-b10d-7a42ba721bcd' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Mein erster Trek in Nepal war eine kurze Runde bei Pokhara. Ich hatte jahrelang über das Everest Base Camp gelesen, aber noch nie über 2.000 m geschlafen und keine Ahnung, wie mein Körper damit zurechtkommen würde. Klein anzufangen war die beste Entscheidung, die ich getroffen habe: Ich kam begeistert nach Hause und selbstbewusst genug, beim nächsten Mal höher hinaufzugehen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Dieser Ratgeber vergleicht vier Treks, die sich gut als erster Trek im Himalaya eignen. Alle nutzen Teehäuser oder Gastfamilien, erfordern keine Kletterkenntnisse und passen in ein oder zwei Wochen Urlaub. Geprüft hat ihn unser Guide Bikash Gurung, der jede Saison Einsteiger in der Annapurna-Region führt.", "type": "text"}]}]}}'::jsonb where section_id = 'c87b3cf6-bd68-427b-ab79-3216d7a0382d' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ein erster Trek sollte Ihnen große Bergblicke ohne große Risiken bieten. Vier Dinge zählen am meisten:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Moderate Höhe.", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Wer unter etwa 3.900 m schläft, hält das Risiko der Höhenkrankheit gering.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Einfache Anreise.", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Wenn Sie zum Ausgangspunkt fahren, müssen Sie bei schlechtem Wetter nicht auf Bergflüge warten.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Gute Teehäuser.", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Warme Speiseräume und einfache, saubere Zimmer machen die Abende angenehm.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Kurze Etappen.", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Fünf bis sechs Stunden Gehzeit lassen Zeit zum Ausruhen, Umschauen und Genießen.", "type": "text"}]}]}]}]}, "heading": "Was einen guten ersten Trek ausmacht", "tocLabel": "Worauf es ankommt"}'::jsonb where section_id = 'fb335bc7-ede3-49da-b7d5-148d6741360a' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Poon Hill ist aus gutem Grund der beliebteste erste Trek in Nepal. Ab Pokhara dauert er fünf Tage und führt durch Gurung-Dörfer und Rhododendronwälder, mit einem Aufstieg zum Sonnenaufgang auf den Poon Hill (3.210 m) und Blick auf Dhaulagiri und Annapurna South. Die höchste Übernachtung ist in Ghorepani (2.860 m), daher ist die Höhe selten ein Problem.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Herausforderung sind die Steinstufen: Tausende davon, vor allem zwischen Tikhedhunga und Ulleri. Gehen Sie langsam, dann klappt das gut. Der Trek ist eine gute Wahl für Familien und für alle, die nur eine Woche in Nepal haben.", "type": "text"}]}]}, "heading": "Poon Hill: der klassische kurze Trek", "tocLabel": "Poon Hill"}'::jsonb where section_id = '5097bc67-083e-4bf9-9a76-b12170d2f8d0' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Wenn Sie sich wirklich mitten zwischen hohen Bergen fühlen möchten, ist das Langtang Valley kaum zu schlagen. Sie fahren von Kathmandu nach Syabrubesi und wandern dann durch das Tal hinauf nach Kyanjin Gompa (3.870 m), mit dem Langtang Lirung (7.227 m) und seinen Gletschern über Ihnen. Höhepunkt ist eine Wanderung zum Sonnenaufgang auf den Kyanjin Ri (4.773 m).", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Aufstieg ist gleichmäßig, und der Trek dauert etwa zehn Tage. Da kein Flug nötig ist, gehört er außerdem zu den preiswertesten Treks in Nepal. Mehr dazu auf der ", "type": "text"}, {"text": "Seite zur Region Langtang", "type": "text", "marks": [{"type": "link", "attrs": {"href": "https://traveltonepal.com/regions/langtang"}}]}, {"text": ".", "type": "text"}]}]}, "heading": "Langtang Valley: Gletscher ohne Flug", "tocLabel": "Langtang"}'::jsonb where section_id = '03116a27-b0e7-40e9-8705-6ffbca8f1097' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Mardi Himal ist ein schmaler Grat, der aus dem Wald oberhalb von Pokhara in Richtung Machapuchare ansteigt, dem heiligen Fishtail. In etwa einer Woche erreichen Sie den Aussichtspunkt am Basislager auf rund 4.500 m. Der Trek ist ruhiger als Poon Hill, und die Berge sind näher.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Preis dafür ist die Steilheit: Die Etappen sind kurz, aber der Weg steigt kräftig an, und oben ist es hoch genug, dass Sie langsam gehen sollten. Wählen Sie ihn, wenn Sie zu Hause bereits in den Bergen wandern. Mehr dazu auf der ", "type": "text"}, {"text": "Seite zur Region Mardi Himal", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/mardi-himal"}}]}, {"text": ".", "type": "text"}]}]}, "heading": "Mardi Himal: ein ruhiger Grat für fitte Wanderer", "tocLabel": "Mardi Himal"}'::jsonb where section_id = '49bf8f1f-6f58-4569-859e-4b53c5e83a6b' and locale = 'de';
update public.article_section_translations set content = '{"alt": "Abendlicht auf einem grasbewachsenen Grat mit Schneegipfeln dahinter, in Badal Danda am Mardi Himal Trek", "caption": "Goldene Stunde in Badal Danda am Mardi Himal Trek."}'::jsonb where section_id = 'a2643c96-3820-4962-abd8-f205cab5efbb' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Tamang Heritage Trail ist der sanfteste der vier. Die Runde führt durch Tamang-Dörfer nahe der tibetischen Grenze, mit natürlichen heißen Quellen in Tatopani und einem höchsten Punkt von etwa 3.165 m in Nagthali. Sie wohnen bei Gastfamilien und essen, was sie essen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Hier geht es weniger um den einen großen Gipfelblick als um die Menschen: Weben, Landwirtschaft und Dorfleben. Der Trek passt zu Familien, zu langsameren Wanderern und zu allen, denen Kultur am wichtigsten ist. Er beginnt in Syabrubesi, sodass Sie das Langtang Valley anhängen können, wenn Sie mehr Zeit haben. Mehr dazu auf der ", "type": "text"}, {"text": "Seite zum Tamang Heritage Trail", "type": "text", "marks": [{"type": "link", "attrs": {"href": "https://traveltonepal.com/regions/tamang-heritage-trail"}}]}, {"text": ".", "type": "text"}]}]}, "heading": "Tamang Heritage Trail: Kultur und Gastfamilien", "tocLabel": "Tamang Heritage"}'::jsonb where section_id = '63d52f47-2991-4d35-81a2-b194eccc72f0' and locale = 'de';
update public.article_section_translations set content = '{"text": "Bei einem ersten Trek sind die Berge nur die halbe Sache. In Erinnerung bleiben der Abend im Speiseraum und der Tee mit einer Familie in Ghandruk. Wählen Sie einen Trek, bei dem Sie Zeit haben, das zu genießen, und nicht einen, bei dem Sie gegen die Uhr laufen."}'::jsonb where section_id = '0394f87d-3ab2-447e-a8fd-d721bfe285ae' and locale = 'de';
update public.article_section_translations set content = '{"items": ["Wie viele Tage habe ich wirklich, einschließlich An- und Abreise nach Nepal?", "Bin ich schon mehrere Tage hintereinander 5–6 Stunden am Tag gewandert?", "Möchte ich große Gletscher, Dorfleben oder ein bisschen von beidem?", "Fliege ich gern zu einer Landepiste in den Bergen, oder fahre ich lieber?", "In welchen Monaten kann ich reisen? (Am besten sind März–Mai und Oktober–November.)"], "heading": "Fragen, die Sie sich vor der Wahl stellen sollten"}'::jsonb where section_id = '0034def6-eaae-4f52-bc0a-679d0a481254' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "In Nepal müssen ausländische Trekker mit einem lizenzierten Guide gehen, der über eine registrierte Agentur gebucht wird. Bei allen unseren Treks ist einer dabei, ebenso wie die Genehmigungen für Ihre Route.", "type": "text"}]}]}}'::jsonb where section_id = '5b7f4fce-0404-42aa-a7f6-5ab2f555d8e2' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Wenn Sie eine Woche haben, gehen Sie zum Poon Hill. Wenn Sie zehn Tage haben und das Gefühl eines großen Himalaya-Tals erleben möchten, gehen Sie ins Langtang. Wenn Sie gut zu Fuß sind und ruhige Wege mögen, wählen Sie Mardi Himal. Und wenn Sie die Menschen ebenso interessieren wie die Gipfel, gehen Sie den Tamang Heritage Trail.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Wofür Sie sich auch entscheiden: Beginnen Sie in gemächlichem Tempo und mit einem guten Guide. Die meisten von uns, die klein anfangen, kommen für einen längeren Trek wieder.", "type": "text"}]}]}, "heading": "Welchen ich wählen würde", "tocLabel": "Meine Wahl"}'::jsonb where section_id = '2327dd70-d5c6-436c-98d4-6319f23fcf82' and locale = 'de';
update public.article_section_translations set content = '{"items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Poon Hill und der Tamang Heritage Trail sind die leichtesten der klassischen Treks: kurz, mit dem höchsten Punkt um 3.200 m. Für beide brauchen Sie trotzdem eine gute Grundfitness für 5–6 Stunden Gehzeit am Tag.", "type": "text"}]}]}, "question": "Welcher ist der leichteste Trek im Himalaya in Nepal?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Manche schaffen es, aber es ist ein langer, hoher Trek bis auf 5.545 m mit Flügen, die sich oft verspäten. Wir empfehlen meist zuerst einen kürzeren Trek oder einen langsamen Everest-Reiseverlauf mit zusätzlichen Ruhetagen.", "type": "text"}]}]}, "question": "Können Anfänger zum Everest Base Camp?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Wenn Sie an einem hügeligen Tag 5–6 Stunden gehen und das am nächsten Tag wiederholen können, sind Sie fit genug für jeden dieser vier Treks. Treppensteigen und Wanderungen am Wochenende in den 6–8 Wochen vor der Reise helfen sehr.", "type": "text"}]}]}, "question": "Wie fit muss ich für einen ersten Trek sein?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Nein. Langtang und der Tamang Heritage Trail beginnen mit einer Fahrt ab Kathmandu. Poon Hill und Mardi Himal starten bei Pokhara, das Sie auf der Straße oder mit einem kurzen Flug erreichen.", "type": "text"}]}]}, "question": "Brauche ich einen Flug zu diesen Treks?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "März bis Mai und Oktober bis November bieten das beste Wetter. Poon Hill und der Tamang Heritage Trail sind auch im Dezember gut, wenn die tiefer gelegenen Wege klar und ruhig sind.", "type": "text"}]}]}, "question": "Wann sollte ich reisen?"}]}'::jsonb where section_id = '16fa7b89-cb45-42d6-a5f0-70a40d1a830b' and locale = 'de';
update public.article_section_translations set content = '{"heading": "Hilfe bei der Wahl Ihres ersten Treks", "message": "Hallo! Das ist mein erster Trek im Himalaya. Können Sie mir helfen, mich zwischen Poon Hill, Langtang, Mardi Himal und dem Tamang Heritage Trail zu entscheiden?", "buttonText": "Fragen auf WhatsApp"}'::jsonb where section_id = 'fdb9736c-5a98-4409-a1c7-5f4df876dd20' and locale = 'de';
update public.articles set slug = 'erster-trek-im-himalaya' where id = 'ac62b559-7614-4b51-8f07-1e82816caf61';
update public.article_translations set title = 'Mardi Himal Packliste: was Sie für eine Woche auf dem Grat brauchen', intro = 'Vom warmen Wald oberhalb von Pokhara bis zu frostigen Morgen im Hochlager: Am Mardi Himal erleben Sie in einer Woche viel Wetter. Hier lesen Sie, was ich einpacke, was ich zu Hause lasse und was Sie in Pokhara leihen können.', card_text = 'Schichten, Schuhe, Schlafsack und kleine Extras für eine Woche auf dem Grat des Mardi Himal.', cover_alt = 'Der grasbewachsene Grat des Mardi Himal, der zu schneebedeckten Gipfeln hinaufführt', highlight_tag = 'Von einem einheimischen Guide geprüft', updated_line = 'Aktualisiert für die Saison 2026/2027', facts = '[{"icon": "altitude", "label": "Höchster Punkt", "value": "Rund 4.500 m"}, {"icon": "wb_twilight", "label": "Nächte im Hochlager", "value": "Oft um oder unter 0 °C"}, {"icon": "route", "label": "Dauer des Treks", "value": "5–8 Tage ab Pokhara"}, {"icon": "payments", "label": "Ausrüstung leihen", "value": "Pokhara oder Kathmandu"}]'::jsonb, seo_keyword = 'Mardi Himal Packliste', seo_title = 'Mardi Himal Packliste: was Sie für den Grat brauchen', seo_description = 'Eine erprobte Packliste für den Mardi Himal: Schichten für kalte Morgen im Hochlager, Schuhe für steile Waldwege und was Sie in Pokhara leihen können.' where article_id = '6af53628-0972-4dc0-9df0-ada4404cf7a0' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Packen Sie für große Temperaturschwankungen: leichte Schichten für den Wald, eine warme Daunenjacke und Mütze für das Hochlager (3.580 m) und die Wanderung im Morgengrauen auf rund 4.500 m, gute Schuhe für steile und manchmal schlammige Wege und einen Schlafsack für die kalten Zimmer in den Teehäusern. Die meiste sperrige Ausrüstung können Sie in Pokhara leihen.", "type": "text"}]}]}}'::jsonb where section_id = 'dcf7d73b-072a-49d8-b433-61e0ee79ed66' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ich war viermal in Nepal trekken, und am Mardi Himal sehe ich am häufigsten Menschen, die das Falsche dabeihaben: zu viel für den Wald, zu wenig für den Grat. Der Trek ist kurz, die Etappen sind steil, und jedes Kilo zählt.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Das ist die Liste, die ich verwende, geprüft von unserem Guide Bikash Gurung, der ein paar Täler weiter aufgewachsen ist und diesen Weg jede Saison geht.", "type": "text"}]}]}}'::jsonb where section_id = '2c5d21dd-0d11-41f9-8f8d-c8febfdfb1a1' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die ersten beiden Tage steigen durch warmen, feuchten Wald an. Im Hochlager sind Sie oberhalb der Baumgrenze, der Wind frischt auf, und die Wanderung zum Aussichtspunkt beginnt im Dunkeln. Mit Schichten sind Sie für beides gerüstet.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Funktionsunterwäsche:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " 2 Oberteile aus Merino oder Kunstfaser und 1 lange Unterhose für kalte Nächte", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Trekkinghemd und -hose:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " schnell trocknend, für die Tage im Wald", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Fleece oder leichte Kunstfaserjacke:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Ihre wichtigste warme Schicht beim Gehen", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Daunenjacke:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " warm genug für den Morgen am Aussichtspunkt und die Abende im Hochlager", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Regenjacke:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " für Regen weiter unten und Wind auf dem Grat", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Warme Mütze, Schlauchtuch und Handschuhe:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " ein dünnes Paar zum Gehen, ein warmes Paar für die Wanderung im Morgengrauen", "type": "text"}]}]}]}]}, "heading": "Schichten: von der Hitze im Wald bis zu frostigen Morgen", "tocLabel": "Kleidung"}'::jsonb where section_id = '4c2a2080-03cd-4aed-ae0a-95736908120b' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Weg ist in beide Richtungen steil, mit Wurzeln und Steinstufen im Wald und losem Untergrund oberhalb des Low Camp. Tragen Sie Schuhe, in denen Sie schon gelaufen sind, mit gutem Profil und Knöchelhalt.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Wasserdichte, gut eingelaufene Trekkingschuhe", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "3–4 Paar gepolsterte Trekkingsocken", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Leichte Schuhe oder Sandalen für die Abende", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Blasenpflaster, beim ersten Scheuern aufkleben", "type": "text"}]}]}]}]}, "heading": "Schuhe und Füße", "tocLabel": "Schuhe"}'::jsonb where section_id = 'bc3582f2-2e6d-453c-9f54-c59aa7607ab8' and locale = 'de';
update public.article_section_translations set content = '{"text": "Oberhalb des Low Camp ist der Weg schmal und kann frühmorgens vereist sein. Benutzen Sie Ihre Stöcke, halten Sie die Hände frei und lassen Sie die große Kamera bis zum Aussichtspunkt im Rucksack."}'::jsonb where section_id = 'c266eb16-4189-4212-9303-278dc3fc72da' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die Teehäuser am Mardi Himal sind klein und einfach. Die Zimmer sind unbeheizt, und abends ist der Speiseraum der einzige warme Ort. Decken gibt es meist, aber im Hochlager werden Sie über Ihren eigenen Schlafsack froh sein.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Ein Schlafsack mit einem Komfortbereich bis etwa −10 °C ist für Herbst und Frühling eine gute Wahl. Im Winter nehmen Sie den wärmsten Schlafsack mit, den Sie haben, oder ergänzen ein Inlett.", "type": "text"}]}]}, "heading": "Schlafsack und Nächte im Teehaus", "tocLabel": "Schlafen"}'::jsonb where section_id = 'c942dc63-22da-4b52-92db-c4c0a2ff5759' and locale = 'de';
update public.article_section_translations set content = '{"alt": "Panorama schneebedeckter Gipfel vom Mardi Himal Base Camp aus", "caption": "Mardi Himal Base Camp: der kälteste und windigste Punkt des Treks"}'::jsonb where section_id = 'c1e2a8bd-0afa-4820-84ff-f9ed2276bca3' and locale = 'de';
update public.article_section_translations set content = '{"items": ["Tagesrucksack (25–35 l) mit Regenhülle", "Seesack für Ihren Träger", "Schlafsack, Komfortbereich bis etwa −10 °C", "Daunenjacke, Fleece und Regenjacke", "Funktionsunterwäsche und schnell trocknende Trekkingkleidung", "Warme Mütze, Schlauchtuch, dünne und warme Handschuhe", "Eingelaufene Trekkingschuhe und Hüttenschuhe", "Trekkingstöcke", "Stirnlampe mit Ersatzbatterien", "Zwei 1-l-Trinkflaschen und Entkeimungstabletten oder ein Filter", "Sonnenbrille, Sonnencreme und Lippenbalsam", "Kleine Erste-Hilfe-Ausrüstung und Blasenpflaster", "Snacks für die langen Anstiege", "Genug Bargeld in nepalesischen Rupien für den ganzen Trek", "Kopie des Reisepasses und Angaben zur Reiseversicherung"], "heading": "Die vollständige Checkliste für den Mardi Himal"}'::jsonb where section_id = '10ce2e85-81a0-41fd-9dc7-06370c598282' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Sie müssen nicht alles mitbringen. In Lakeside in Pokhara gibt es viele Läden, die Schlafsäcke, Daunenjacken und Trekkingstöcke gegen eine kleine Tagesgebühr verleihen und Socken, Mützen und Handschuhe verkaufen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Prüfen Sie geliehene Ausrüstung, bevor Sie bezahlen: Reißverschlüsse, die schließen, ein Schlafsack, der sich noch voll und warm anfühlt, und Stöcke, die richtig arretieren. Schuhe sind das Einzige, was ich nie leihe.", "type": "text"}]}]}, "heading": "In Pokhara leihen oder kaufen", "tocLabel": "Ausrüstung leihen"}'::jsonb where section_id = 'dda5ae84-7d17-4047-9db6-4da64012ed93' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Wer leicht packt, hat an den steilen Tagen viel mehr Freude. Diese Dinge nehme ich auf einen kurzen Teehaus-Trek wie den Mardi Himal nicht mehr mit:", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Jeans und Baumwollkleidung: schwer, trocknet langsam und ist feucht kalt", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Ein zweites Paar schwere Schuhe: ein gutes Paar plus leichte Hüttenschuhe genügt", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Große Kosmetikflaschen: kleine nachfüllbare reichen für eine Woche", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Zu viele Bücher und Geräte: Die Abende sind kurz, und Laden kostet weiter oben extra", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Viel abgepacktes Essen: Die Teehäuser kochen gut, ein paar Snacks genügen", "type": "text"}]}]}]}]}, "heading": "Was ich zu Hause lasse", "tocLabel": "Zu Hause lassen"}'::jsonb where section_id = '35b1636c-55e1-4f24-9309-1cf0653ac64c' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Am Weg gibt es keine Geldautomaten, nehmen Sie also Bargeld aus Pokhara für Mahlzeiten, heiße Getränke und kleine Extras wie das Laden mit. Bereiten Sie Ihr Wasser auf, statt Plastikflaschen zu kaufen: Die Teehäuser füllen Ihre Flaschen mit abgekochtem oder gefiltertem Wasser auf.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Sonne in der Höhe ist auch an kalten Tagen stark. Sonnenbrille, Sonnencreme und Lippenbalsam sind hier so wichtig wie Ihre Daunenjacke.", "type": "text"}]}]}, "heading": "Wasser, Gesundheit und Kleinigkeiten", "tocLabel": "Gesundheit und Wasser"}'::jsonb where section_id = '402cfae1-4f6f-49c7-aa0b-45de578b2db9' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Gewicht für den Träger:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Wenn Sie sich einen Träger teilen, sollte Ihr Seesack höchstens etwa 15 kg wiegen. Lassen Sie alles, was Sie am Weg nicht brauchen, in Ihrem Hotel in Pokhara.", "type": "text"}]}]}}'::jsonb where section_id = '8b313aee-de30-4154-bfee-601f637e7652' and locale = 'de';
update public.article_section_translations set content = '{"items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die Tage im Wald sind mild, aber die Nächte im Hochlager liegen im Herbst und Frühling oft um oder unter dem Gefrierpunkt, im Winter ist es noch kälter. Die Wanderung im Morgengrauen zum Aussichtspunkt ist der kälteste Teil des Treks.", "type": "text"}]}]}, "question": "Wie kalt wird es auf dem Mardi Himal Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Im Herbst und Frühling meist nicht. Im Winter oder nach Neuschnee können leichte Grödel oberhalb des Hochlagers helfen. Ihr Guide sagt Ihnen vor dem Aufbruch Bescheid.", "type": "text"}]}]}, "question": "Brauche ich Steigeisen für den Mardi Himal?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja. Viele Läden in Lakeside verleihen beides gegen eine kleine Tagesgebühr. Prüfen Sie den Zustand vor dem Bezahlen und leihen Sie einen Tag vor dem Trek, damit Sie etwas, das nicht passt, noch tauschen können.", "type": "text"}]}]}, "question": "Kann ich in Pokhara einen Schlafsack und eine Daunenjacke leihen?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Rechnen Sie mit etwa 4–6 kg: Wasser, warme Schichten, Regenjacke, Snacks, Sonnenschutz und Ihre Kamera. Den Rest trägt der Träger.", "type": "text"}]}]}, "question": "Wie schwer sollte mein Tagesrucksack sein?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Sie sind sehr zu empfehlen. Der Abstieg vom Hochlager und durch den Wald ist steil, und Stöcke schonen Ihre Knie und helfen an vereisten Morgen.", "type": "text"}]}]}, "question": "Brauche ich Trekkingstöcke?"}]}'::jsonb where section_id = 'dd3c541f-b996-4d8c-bec9-ead0a5faec0e' and locale = 'de';
update public.article_section_translations set content = '{"heading": "Fragen zur Ausrüstung für den Mardi Himal?", "message": "Hallo! Ich bereite mich auf den Mardi Himal Trek vor und habe eine Frage zum Packen.", "buttonText": "Fragen Sie uns auf WhatsApp"}'::jsonb where section_id = '556f3e35-2dc1-4cb7-8693-f3cecaf745c6' and locale = 'de';
update public.articles set slug = 'mardi-himal-packliste' where id = '6af53628-0972-4dc0-9df0-ada4404cf7a0';
update public.article_translations set title = 'Nar Phu Valley Trek: Planungsratgeber für Nepals verborgenes Tal', intro = 'Steindörfer über 4.000 m, tibetische Klöster und ein Pass auf 5.320 m, nur eine Tagesfahrt von Kathmandu entfernt. So funktioniert der Nar Phu Trek: Genehmigungen, Route, Jahreszeiten und was Sie in den Dörfern erwartet.', card_text = 'Genehmigungen, Route, Jahreszeiten und Dorfleben: alles für die Planung des Nar Phu Valley Trek.', cover_alt = 'Steinhäuser und Felder eines Dorfes im Nar-Phu-Tal unter kahlen Berghängen', highlight_tag = 'Sperrgebiet · 13 Tage', updated_line = 'Aktualisiert für die Saison 2026/2027', facts = '[{"icon": "altitude", "label": "Höchster Punkt", "value": "Kang La, 5.320 m"}, {"icon": "description", "label": "Genehmigungen", "value": "Sperrgebiet + ACAP"}, {"icon": "calendar_month", "label": "Beste Monate", "value": "Sep.–Nov., Apr.–Mai"}, {"icon": "route", "label": "Start", "value": "Koto, mit dem Jeep über Besisahar"}]'::jsonb, seo_keyword = 'Nar Phu Valley Trek', seo_title = 'Nar Phu Valley Trek: Planung und Genehmigungen', seo_description = 'Planen Sie den Nar Phu Valley Trek: Sperrgebietsgenehmigung, Route über den Kang La, beste Monate und das Leben in Nar und Phu.' where article_id = '79819de8-a85b-46ab-ac1b-3f7e68aa69b0' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Nar Phu Valley Trek dauert ", "type": "text"}, {"text": "13 Tage", "type": "text", "marks": [{"type": "bold"}]}, {"text": " ab Kathmandu. Sie fahren nach Koto und wandern durch eine enge Schlucht hinauf zu den Dörfern ", "type": "text"}, {"text": "Phu (4.080 m)", "type": "text", "marks": [{"type": "bold"}]}, {"text": " und ", "type": "text"}, {"text": "Nar (4.110 m)", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Danach überqueren Sie den ", "type": "text"}, {"text": "Kang La (5.320 m)", "type": "text", "marks": [{"type": "bold"}]}, {"text": " und steigen nach Ngawal am Annapurna Circuit ab. Sie benötigen eine Sperrgebietsgenehmigung und ein ACAP, die über eine Agentur beantragt werden, und gehen mit einem lizenzierten Guide.", "type": "text"}]}]}}'::jsonb where section_id = 'b9dc2640-e254-4d41-81c3-481087fc0d24' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Wenn Trekker uns nach einem Ort fragen, der sich noch wie das alte Tibet anfühlt, ohne Flüge und ohne Expeditionscamping, empfehlen wir Nar Phu. Das Tal ist erst seit 2003 für ausländische Trekker geöffnet, und die Regeln für Sperrgebiete halten die Besucherzahlen niedrig. So planen wir den Trek, von den Genehmigungen bis zur letzten Nacht in Manang. Wie sich der Trek in die Region einfügt, lesen Sie auf der ", "type": "text"}, {"text": "Seite zur Region Nar Phu", "type": "text", "marks": [{"type": "link", "attrs": {"href": "/nar-phu-valley-trek"}}]}, {"text": " nach.", "type": "text"}]}]}}'::jsonb where section_id = '6a52d9be-dc3d-44e3-aa5a-2b98daad9927' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Weg verlässt den Annapurna Circuit in Koto (2.600 m) und folgt dem Phu Khola durch eine tiefe, enge Schlucht. Oberhalb der Schlucht öffnet sich das Tal zu sommerlichen Hirtenlagern, Chörten und der alten Siedlung Kyang, bevor Sie Phu erreichen, eine Ansammlung von Steinhäusern, die wie eine Festung auf einem Grat stehen.", "type": "text"}]}, {"type": "orderedList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Auf der Straße von Kathmandu nach Besisahar, dann mit dem Jeep nach Koto.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Von Koto durch die Schlucht nach Meta (3.560 m).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Von Meta über Kyang nach Phu (4.080 m), dann ein Ruhetag in Phu.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Von Phu hinunter nach Nar Phedi, dann hinauf nach Nar (4.110 m).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Von Nar über den Kang La (5.320 m) nach Ngawal und weiter nach Manang.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Von Manang mit dem Jeep nach Besisahar und zurück nach Kathmandu.", "type": "text"}]}]}]}]}, "heading": "Die Route auf einen Blick", "tocLabel": "Die Route"}'::jsonb where section_id = '73994f5e-7928-4468-bb0e-6ff20faa6fbc' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Nar Phu ist ein Sperrgebiet, wie Manaslu und Upper Mustang. Sie benötigen eine ", "type": "text"}, {"text": "Sperrgebietsgenehmigung für Nar Phu", "type": "text", "marks": [{"type": "bold"}]}, {"text": " und das ", "type": "text"}, {"text": "Annapurna Conservation Area Permit (ACAP)", "type": "text", "marks": [{"type": "bold"}]}, {"text": ". Die Sperrgebietsgenehmigung wird nur über eine registrierte Agentur ausgestellt, und Sie müssen mit einem lizenzierten Guide gehen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Wir besorgen beide Genehmigungen vor Ihrem Trek in Kathmandu. Die Gruppenregeln für Sperrgebiete haben sich in der Vergangenheit geändert, deshalb bestätigen wir Ihnen bei der Buchung die aktuellen Regeln. Wenn Sie allein reisen, sagen Sie uns bitte frühzeitig Bescheid.", "type": "text"}]}]}, "heading": "Genehmigungen und Guide-Pflicht", "tocLabel": "Genehmigungen"}'::jsonb where section_id = '58fcd0b5-813b-464e-9e09-a9d0ee5bec13' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die Gebühren für Genehmigungen nennen wir hier nicht, weil die Regierung sie immer wieder anpasst. ", "type": "text"}, {"text": "Wir bestätigen Ihnen die aktuellen Gebühren und Regeln bei der Buchung", "type": "text", "marks": [{"type": "bold"}]}, {"text": ", bevor Sie bezahlen.", "type": "text"}]}]}}'::jsonb where section_id = '02e4d6cc-ff1a-4c85-84eb-f1d5802e8b59' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Nar Phu liegt im Regenschatten hinter den Annapurnas und bleibt daher trockener als der größte Teil Nepals. ", "type": "text"}, {"text": "September bis November", "type": "text", "marks": [{"type": "bold"}]}, {"text": " ist die beste Reisezeit: klarer Himmel, Erntezeit in den Dörfern und stabiles Wetter für den Kang La. ", "type": "text"}, {"text": "April und Mai", "type": "text", "marks": [{"type": "bold"}]}, {"text": " sind gut, sobald der Schnee am Pass nachgelassen hat.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Auch die Sommermonate sind möglich, was in Nepal selten ist, allerdings können Erdrutsche die Jeepstraße nach Koto treffen. Der Winter ist sehr kalt, der Pass ist verschneit, und viele Familien ziehen in tiefere Täler.", "type": "text"}]}]}, "heading": "Beste Reisezeit", "tocLabel": "Beste Reisezeit"}'::jsonb where section_id = '71f7c75d-50ef-4b47-9501-f59e005ebcd7' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "In Meta, Phu und Nar übernachten Sie in einfachen Lodges und bei Gastfamilien, die von Dorffamilien geführt werden. Die Zimmer sind einfach und kalt, mit dünnen Matratzen und Decken, bringen Sie also einen warmen Schlafsack mit. Auch das Essen ist einfach: Dal Bhat, Kartoffeln, Nudeln, tibetisches Brot und viel Tee.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Besuchen Sie das Kloster Tashi Lhakhang oberhalb von Phu und fragen Sie Ihren Guide, bevor Sie Menschen oder das Innere von Häusern und Tempeln fotografieren. Ein Ruhetag in Phu hilft Ihnen bei der Anpassung an die Höhe und lässt Ihnen Zeit, das Dorfleben ohne Eile kennenzulernen.", "type": "text"}]}]}, "heading": "Dorfleben und Unterkünfte", "tocLabel": "Unterkünfte"}'::jsonb where section_id = '2a888bdb-93b1-4292-8fc1-62a1c28e1dce' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Nach dem Kang La steigen Sie nach Ngawal ab, einem Dorf an der oberen Route des Annapurna Circuit. Die meisten Trekker, die den Kang La überqueren, sind bereits gut akklimatisiert, daher liegt es nahe, weiter über den ", "type": "text"}, {"text": "Thorong La (5.416 m)", "type": "text", "marks": [{"type": "bold"}]}, {"text": " nach Muktinath zu gehen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Von Manang führt die Route hinauf nach Yak Kharka und Thorong Phedi, überquert den Pass früh am Morgen und führt hinunter nach Muktinath, einem Tempel, der Hindus und Buddhisten heilig ist. Planen Sie für beide Treks etwa 16–18 Tage ein. Dieser Teil ist durch das ACAP abgedeckt, für den Thorong La ist also keine weitere Sperrgebietsgenehmigung nötig.", "type": "text"}]}]}, "heading": "Nar Phu mit dem Thorong La verbinden", "tocLabel": "Thorong La anhängen"}'::jsonb where section_id = 'eccc4d62-880f-460a-882a-eb3c9bb1a570' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Phu und Nar sind lebendige Dörfer, keine Museen. Gehen Sie im Uhrzeigersinn um Chörten und Manimauern, fragen Sie, bevor Sie Menschen fotografieren, und kleiden Sie sich beim Klosterbesuch zurückhaltend. Ihr Guide sagt Ihnen, wann ein guter Zeitpunkt für einen Besuch ist und wie Sie eine kleine Spende hinterlassen können, wenn Sie möchten.", "type": "text"}]}]}, "heading": "Respekt vor den Dörfern", "tocLabel": "Respekt"}'::jsonb where section_id = 'c6c5901f-a26a-42db-b68f-9d265a1d982a' and locale = 'de';
update public.article_section_translations set content = '{"text": "Nehmen Sie kleine Rupienscheine aus Kathmandu mit. Im Tal gibt es keine Geldautomaten, und wenn Sie Tee und Snacks in Phu mit kleinen Scheinen bezahlen, erleichtert das den Familien, die die Lodges führen, das Leben."}'::jsonb where section_id = '7e39c98a-7247-4043-90eb-6ea7e09160b3' and locale = 'de';
update public.article_section_translations set content = '{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Es ist ein anspruchsvoller Trek. Sie verbringen mehrere Nächte über 4.000 m, und der Tag am Kang La ist lang: früher Aufbruch in Nar, steiler Aufstieg auf 5.320 m und ein langer Abstieg nach Ngawal. Kletterkenntnisse brauchen Sie nicht, aber Sie sollten fit sein und problemlos 6–7 Stunden am Tag gehen können.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Unser Reiseverlauf steigt langsam an und enthält einen Ruhetag in Phu, und Ihr Guide prüft jeden Abend, wie es allen geht.", "type": "text"}]}]}, "heading": "Wie schwer ist der Trek?", "tocLabel": "Schwierigkeit"}'::jsonb where section_id = 'd6ee1bf4-e352-48ca-85d0-c1b435e1f974' and locale = 'de';
update public.article_section_translations set content = '{"items": ["Einen Reisepass, der noch mindestens 6 Monate gültig ist, und ein Visum für Nepal", "Eine Reiseversicherung, die Trekking bis 5.500 m und Hubschrauberrettung abdeckt", "Warme Schichten und einen Schlafsack für Nächte weit unter dem Gefrierpunkt", "Genug nepalesische Rupien in kleinen Scheinen für den ganzen Trek", "Ein paar Reservetage für Verzögerungen durch Straße oder Wetter"], "heading": "Vor der Buchung"}'::jsonb where section_id = '07a27d2a-c0f1-4e3b-8344-51957f490211' and locale = 'de';
update public.article_section_translations set content = '{"items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Unser Reiseverlauf umfasst 13 Tage ab Kathmandu und zurück. Viele Trekker hängen danach den Thorong La und Muktinath an, insgesamt sind es dann etwa 16–18 Tage.", "type": "text"}]}]}, "question": "Wie viele Tage dauert der Nar Phu Valley Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Nein. Nar Phu ist ein Sperrgebiet: Die Genehmigung wird über eine registrierte Agentur ausgestellt, und Sie müssen mit einem lizenzierten Guide gehen.", "type": "text"}]}]}, "question": "Kann ich den Nar Phu Trek ohne Guide gehen?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Etwas. Die Lodges sind einfacher, Sie schlafen mehrere Nächte in großer Höhe, und der Kang La ist ein richtiger Pass. Der Trek passt zu Trekkern, die fit sind und mit einfachen Zimmern gut zurechtkommen.", "type": "text"}]}]}, "question": "Ist der Nar Phu Trek schwerer als der Annapurna Circuit?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja. Nach dem Kang La erreichen Sie Ngawal bei Manang, das am Annapurna Circuit liegt. Von dort können Sie über den Thorong La nach Muktinath weitergehen.", "type": "text"}]}]}, "question": "Kann ich den Nar Phu Trek mit dem Thorong La verbinden?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Im oberen Tal kaum. Rechnen Sie damit, zwischen Meta und Ngawal einige Tage offline zu sein, und sagen Sie Ihrer Familie vor dem Aufbruch Bescheid.", "type": "text"}]}]}, "question": "Gibt es Handyempfang oder WLAN?"}]}'::jsonb where section_id = '2d6e32e3-52c5-456e-be94-7240efa486c7' and locale = 'de';
update public.article_section_translations set content = '{"heading": "Planen Sie Nar Phu mit unserem Team", "message": "Hallo! Ich interessiere mich für den Nar Phu Valley Trek. Können Sie mir etwas zu Terminen, Genehmigungen und den aktuellen Gruppenregeln sagen?", "buttonText": "Fragen zu Nar Phu"}'::jsonb where section_id = '510b05cb-905e-4e7c-a940-2bafdfeab273' and locale = 'de';
update public.articles set slug = 'nar-phu-valley-trek-planung' where id = '79819de8-a85b-46ab-ac1b-3f7e68aa69b0';
update public.author_translations set job_title = 'Leiterin Reiseplanung', bio = 'Anita plant unsere Treks im Büro in Kathmandu und ist die meisten Routen, über die sie schreibt, selbst gegangen. Sie hat in Kathmandu und in Deutschland Tourismus studiert und beantwortet Fragen von Trekkern auf Englisch und Deutsch.' where author_id = '57458162-d32c-476b-be91-af39e0319946' and locale = 'de';
update public.author_translations set job_title = 'Trekleiter für Familientreks' where author_id = '3d0d234e-7064-4ed9-89f6-352dc44d81e4' and locale = 'de';
update public.author_translations set job_title = 'Trekleiter für Sperrgebiete' where author_id = '3424249d-fd83-4e01-930b-0740a1f6637b' and locale = 'de';
update public.author_translations set job_title = 'Reisejournalistin', bio = 'Lena ist Reisejournalistin aus München und war schon viermal zum Trekking in Nepal. Sie schreibt für deutschsprachige Leser über den ersten Trek im Himalaya.' where author_id = '1d69b837-e86f-437b-a7a2-2a2716872266' and locale = 'de';
update public.author_translations set job_title = 'Gründer und leitender Trek-Direktor', bio = 'Ich bin Sandip Kshetri, lizenzierter Guide, und habe über 200 Reisende durch Nepal geführt. Ich berate Sie ehrlich, damit Sie Ihre Reise selbst gestalten können. Wir bleiben flexibel, behandeln unser Team fair und stellen Ihre Sicherheit an erste Stelle.' where author_id = 'f8ce3cc4-f592-4fd8-9b92-aa6d30fbbab5' and locale = 'de';
update public.trekking_guide_translations set role = 'Trekleiter für Familientreks', bio = 'Bikash stammt aus Ghandruk, einem Gurung-Dorf am Weg zum Annapurna Base Camp. Er hat 13 Jahre Erfahrung als Guide und ist unser Lieblingsguide für Familien: geduldig, witzig und voller Geschichten über das Dorfleben.', quote = 'Mit Kindern ist der Trek nicht das Ziel. Ein guter Tag ist, wenn alle morgen wieder laufen wollen.' where guide_id = 'fce4cb8f-718a-40d2-81aa-175c62c73c5e' and locale = 'de';
update public.trekking_guide_translations set role = 'Leitende Guide für Alleinreisende', bio = 'Sushila wurde in Pokhara zur Trekkingguide ausgebildet und führt seit 9 Jahren Treks im Annapurna-Gebiet. Viele Alleinreisende, besonders Frauen, fragen für Mardi Himal, Poon Hill und das Annapurna Base Camp gezielt nach ihr.', quote = 'Allein zu wandern ist in Ordnung. Mit jemandem zu wandern, der den Weg und die Menschen kennt, ist besser.' where guide_id = '54329a2f-ce24-4d39-85eb-2f7ac4ae50e6' and locale = 'de';
update public.trekking_guide_translations set role = 'Trekleiter für Sperrgebiete', bio = 'Tsering kommt aus Samagaon unterhalb des Manaslu und hat den Larkya La öfter überquert, als er zählen kann. Er leitet unsere Treks in Manaslu, im Tsum Valley und im Nar Phu Valley und kümmert sich unterwegs um die Genehmigungen für die Sperrgebiete.', quote = 'Am Larkya La starten wir vor der Morgendämmerung und kehren um, wenn das Wetter es verlangt. So kommen wir sicher nach Hause.' where guide_id = 'e6b9bfbf-ec52-477f-a473-c0b7585381dd' and locale = 'de';
update public.trekking_guide_translations set role = 'Senior-Trekleiter' where guide_id = '498f4e62-d8b4-40be-a1ed-065bcb3b65f6' and locale = 'de';
update public.trekking_guide_translations set role = 'Senior-Trekleiter', bio = 'Nabaraj Nepal hat in 12 Jahren mehr als 250 Treks in ganz Nepal geführt und gehört zu unseren am besten bewerteten Guides. Er ist auf das Annapurna-Gebiet spezialisiert, besonders Mardi Himal und Annapurna Base Camp, sowie auf das Langtang-Tal. Den Weg zum Mardi Himal kennt er in- und auswendig.', quote = 'Das Annapurna-Gebiet hat etwas Besonderes, das mich jedes Mal glücklich macht, wenn ich diese Wege gehe.' where guide_id = 'c939b323-ca4a-4e30-93f7-a5ae107f2c06' and locale = 'de';
update public.adventures set title = 'Wilde Honigjagd', tag = 'Lamjung · Frühling und Herbst', summary = 'Erleben Sie, wie Honigjäger der Gurung mit Strickleitern und Bambusstangen Felsenhonig ernten, eine Tradition, die seit Generationen weitergegeben wird.', photo_alt = 'Ein Honigjäger erntet auf einer Strickleiter Felsenhonig' where id = 'f8a97602-2e04-470c-b8c3-2fd0ca3f14a2';
update public.adventures set title = 'Auf den Spuren des Roten Pandas', tag = 'Ostnepal und Langtang · Frühling', summary = 'Wandern Sie mit einem einheimischen Fährtenleser durch stille Wälder und halten Sie im Bambus Ausschau nach Roten Pandas, weit abseits der großen Trekkingrouten.', photo_alt = 'Ein Roter Panda klettert einen Ast entlang' where id = 'b9502f70-75c1-4fb9-ac44-9d2b83a0fc32';
update public.adventures set title = 'Vogelbeobachtung im Himalaya', tag = 'Ganz Nepal · Ganzjährig', summary = 'In Nepal leben über 850 Vogelarten. Wir stellen Ihnen einen vogelkundigen Guide zur Seite und planen Ihre Route um die Vögel, die Sie sehen möchten.', photo_alt = 'Ein Glanzfasan (Himalaya-Monal), Nepals Nationalvogel' where id = '89bf34bd-6362-4d7d-9122-5a4cb27bd410';
update public.adventures set title = 'Klettern', tag = 'Nahe Kathmandu · Okt.–Mai', summary = 'Klettern Sie an Kalksteinfelsen, nur eine kurze Fahrt von Kathmandu entfernt, mit Routen für Einsteiger und erfahrene Kletterer.', photo_alt = 'Ein Kletterer an einer Kalksteinwand' where id = '77b59939-cb00-4540-b07d-60dbee71f188';
update public.adventures set title = 'Wildwasser-Rafting', tag = 'Trishuli River · Sep.–Mai', summary = 'Fahren Sie Stromschnellen auf dem Trishuli oder dem Bhote Koshi, vom Halbtagesausflug nahe Kathmandu bis zur mehrtägigen Tour mit Zeltübernachtung am Fluss.', photo_alt = 'Eine Raftingcrew paddelt durch Wildwasser' where id = '02bd4243-0e24-4286-bb44-d6164df9529b';
update public.adventure_section set eyebrow = 'Abseits der Trekkingwege', heading = 'Erzählen Sie uns von Ihrem Nepal-Traumabenteuer. Wir machen es möglich.', intro = 'Einige der schönsten Erlebnisse in Nepal kann man nicht online buchen. Erzählen Sie uns, welches Abenteuer oder welchen Trek Sie sich vorstellen, und wir planen ihn für Sie.', ask_title = 'Etwas anderes im Sinn?', ask_text = 'Feste, Paragliding, Aufenthalte im Kloster oder eine Route, von der Sie vor Jahren gelesen haben. Erzählen Sie es uns, und wir sagen Ihnen ehrlich, ob es möglich ist.', steps_title = 'So funktioniert es', steps = '[{"text": "Schicken Sie uns per WhatsApp oder E-Mail eine Nachricht, was Sie wann unternehmen möchten.", "title": "Erzählen Sie uns Ihre Idee"}, {"text": "Wir sprechen mit Guides und Gemeinden vor Ort und schicken Ihnen dann einen ehrlichen Plan mit Preis.", "title": "Wir prüfen, was möglich ist"}, {"text": "Daten oder Tempo ändern oder einen Trek dazunehmen: Wir passen alles an, bis es passt.", "title": "Wir planen alles nach Ihren Wünschen"}]'::jsonb, note = 'Manche Erlebnisse hängen von Jahreszeit, Wetter und örtlichen Genehmigungen ab. Ist etwas nicht möglich oder passt es nicht zum Ort, sagen wir es Ihnen vor der Buchung.' where site_id = 'annapurna';
update public.site_pages set eyebrow = 'Über uns', heading = 'Privattreks in Nepal, so wie Sie sie sich erträumen.', intro = 'Annapurna Trekking ist ein lizenzierter Trekkingveranstalter in Kathmandu. Wir planen Privattreks in ganz Nepal, von Everest und Annapurna bis zu stillen Tälern wie Nar Phu und Manaslu. Vier Überzeugungen prägen jede Reise, die wir planen, und alles beginnt damit, dass wir Ihnen zuhören.', seo_title = 'Über uns: lizenzierter nepalesischer Trekkingveranstalter', seo_description = 'Das Team in Kathmandu und die Guides von Annapurna Trekking: unsere Geschichte, unsere Versprechen, Lizenzen und wie wir für Träger und Dörfer sorgen.', seo_keyword = 'Trekking Agentur Nepal', content = '{"goals": [{"text": "Guides, Träger und Trekking-Mitarbeiter bekommen oft nicht den Respekt und die Bezahlung, die sie verdienen. Das wollen wir ändern, und es beginnt damit, wie wir unser eigenes Team behandeln.", "title": "Respekt und faire Bezahlung für das Team am Weg"}, {"text": "Viele wunderschöne Gegenden Nepals sehen bis heute nur sehr wenige Besucher. Wir möchten sie zeigen und Reisenden einen Grund geben, über die berühmten Wege hinauszugehen.", "title": "Orte, die die Aufmerksamkeit der Welt verdienen"}, {"text": "Wir möchten, dass der Tourismus Familien in ganz Nepal ein echtes Einkommen bringt. Wir sind überzeugt, dass das in vielen Regionen noch gut möglich ist, und jeder Trek, den wir planen, ist ein Schritt dorthin.", "title": "Tourismus, der die Menschen vor Ort stärkt"}], "quote": "Es ist Zeit, dass Nepal seine eigene Stimme bekommt.", "honest": {"body": "Ehrlich heißt: Wir nennen die echten Kosten, den echten Andrang, die echte Schwierigkeit und die echten Risiken. Vorausschauend heißt: Wir sprechen Probleme als Erste an, ob ein besserer Monat, eine gesperrte Straße oder ein Trek, der für Ihre erste Reise zu hoch ist. Wir sagen es Ihnen, auch wenn Sie den Trek deshalb absagen. Die Entscheidung treffen Sie.", "quote": "Wir sagen Ihnen, was wir wissen. Sie entscheiden.", "advice": [{"who": "An jemanden, der zum ersten Mal trekkt", "quote": "Für Ihren ersten Trek passt Langtang vielleicht besser als das Everest Base Camp."}, {"who": "An einen Gast, der ruhige Wege sucht", "quote": "Wenn Sie volle Lodges nicht mögen, lassen Sie Poon Hill im Oktober aus. Mardi Himal oder Pikey Peak sind ruhiger."}, {"who": "An einen Gast, der für Juli bucht", "quote": "Ihre Reisedaten fallen in den Monsun. Warten Sie, oder wählen Sie eine Route im Regenschatten."}, {"who": "An einen Gast mit wenig Zeit", "quote": "Die längere Variante brauchen Sie nicht. Sieben Tage reichen für das, was Sie sehen möchten."}], "points": [{"text": "Wir sagen es, wenn ein kürzerer, günstigerer oder leichterer Trek besser zu Ihnen passt oder wenn Sie eine zusätzliche Leistung nicht brauchen.", "title": "Vor der Buchung"}, {"text": "Vollständige Preise, was nicht enthalten ist, ehrliche Hinweise und für wen der Trek nicht geeignet ist.", "title": "Auf jeder Trek-Seite"}, {"text": "Wir melden uns zuerst, wenn sich Wetter, Straßen, Flüge oder Genehmigungen ändern, und sagen Ihnen, was das für Ihren Plan bedeutet.", "title": "Vor dem Abflug"}, {"text": "Ihr Guide erklärt den Grund für jede Umkehr und jede Routenänderung. Wenn wir einen Fehler machen, geben wir ihn zu und beheben ihn.", "title": "Unterwegs"}], "eyebrow": "02 · Ehrlich und vorausschauend", "heading": "Wir beraten Sie immer ehrlich, auch wenn uns das eine Buchung kostet.", "cardLink": "Ratschläge, die wir immer geben", "cardText": "Wir sagen Ihnen die Wahrheit, bevor Sie fragen, auch wenn Sie den Trek dann vielleicht absagen.", "cardTitle": "Wir sind ehrlich", "adviceHeading": "Ratschläge, die wir geben, auch wenn wir dadurch weniger buchen"}, "listen": {"body": "Bevor wir eine Route vorschlagen, hören wir zu. Wir möchten Ihre Gedanken, Ihre Interessen und Ihre Vorlieben kennen. Wir möchten auch wissen, wie Sie Entscheidungen treffen und warum Ihnen diese Reise wichtig ist.\r\n\r\nWenn wir das verstanden haben, schlagen wir den Reiseverlauf vor, der am besten zu Ihnen passt. Vielleicht ist es nicht der berühmteste Trek. Aber es ist der richtige für Sie.", "quote": "Erst hören wir zu, dann planen wir rund um Sie.", "steps": [{"text": "Wir stellen offene Fragen und lassen Sie erzählen. Es gibt keine Formulare und kein Verkaufsgespräch nach Schema.", "title": "1. Wir hören zu"}, {"text": "Wir schauen über den Namen des Treks hinaus auf das, was Sie wirklich suchen.", "title": "2. Wir verstehen"}, {"text": "Erst dann schlagen wir eine Route vor: den richtigen Trek, die richtige Zahl an Tagen und das richtige Tempo für Sie, mit einer Begründung für jede Entscheidung.", "title": "3. Wir schlagen vor"}], "example": "Wer zum ersten Mal trekkt, Angst vor steilen Anstiegen hat und ruhige Wege sucht, hört von uns vielleicht eher „Langtang, mit einer gemütlichen Tageswanderung ins Langshisha-Tal“ als „Everest Base Camp“.", "eyebrow": "01 · Wir hören zuerst zu", "heading": "Erst verstehen wir Sie. Dann schlagen wir den Trek vor, der zu Ihnen passt.", "cardLink": "Wie wir zuhören", "cardText": "Wir verstehen, was Sie sich von Nepal wünschen, bevor wir einen Reiseverlauf vorschlagen.", "cardTitle": "Wir hören zuerst zu", "questions": ["Wie sind Sie auf Nepal gekommen?", "Was machen Sie auf Reisen am liebsten?", "Was soll diese Reise für Sie bedeuten?", "Gibt es etwas, das Sie vermeiden möchten?"], "understand": [{"label": "Ihre Gedanken", "value": "Was Sie sich vorstellen"}, {"label": "Ihre Interessen", "value": "Gipfel, Dörfer, Essen"}, {"label": "Ihre Vorlieben", "value": "Tempo, Komfort, Andrang"}, {"label": "Ihr Anliegen", "value": "Warum diese Reise, warum jetzt"}], "understandNote": "Wir lernen auch, wie Sie Entscheidungen treffen, damit wir Ihnen unsere Vorschläge so erklären, wie es Ihnen am meisten hilft."}, "safety": {"facts": [{"text": "Fester Bestandteil jedes Treks in großer Höhe.", "title": "Akklimatisierungstage"}, {"text": "Sauerstoff und Puls, jeden Abend.", "title": "Tägliche Gesundheitschecks"}, {"text": "Koordiniert von unserem Büro in Kathmandu.", "title": "Rettungsplan"}], "eyebrow": "Die eine Regel über allen vier", "heading": "Ihr Trek, Ihr Weg. Nur bei Ihrer Sicherheit machen wir keine Kompromisse."}, "flexible": {"body": "Wir verkaufen kein fertiges Paket, in das Sie hineinpassen müssen. Ihr Privattrek entsteht aus dem, was Sie uns erzählt haben, und Sie können ihn so lange ändern, bis er sich richtig anfühlt.\r\n\r\nAuch nach der Buchung bleibt der Plan flexibel. Möchten Sie mitten im Trek etwas ändern, sind wir immer offen und tun unser Bestes, um es möglich zu machen. Brauchen Sie einen Ruhetag, ein langsameres Tempo oder eine Nacht mehr in einem Dorf? Ihr Guide kann das unterwegs ändern, und unser Büro in Kathmandu bucht Lodges, Jeeps und Flüge noch am selben Tag um.", "quote": "Wenn es machbar ist, machen wir es.", "stages": [{"text": "Sie erhalten zwei oder drei Varianten desselben Treks zum Vergleich. Änderungen sind kostenlos, bis der Plan passt.", "title": "Vor der Buchung"}, {"text": "Ihre eigenen Reisedaten und Ihre eigene Gruppe, ohne fremde Mitreisende. Ihr Plan nennt Ihren Guide und erklärt, warum jeder Tag so geplant ist, wie er ist.", "title": "Buchung"}, {"text": "Einen Ruhetag einlegen, das Tempo drosseln, einen Abstecher machen oder länger in einem Dorf bleiben, wenn es sicher ist und die Genehmigungen es erlauben.", "title": "Unterwegs"}, {"text": "Wir helfen bei zusätzlichen Tagen in Nepal, umgebuchten Flügen oder der Planung Ihrer nächsten Reise.", "title": "Nach dem Trek"}], "eyebrow": "03 · Privat und flexibel", "heading": "Wir passen den Plan an Sie an, nicht umgekehrt.", "cardLink": "Wie sich Pläne ändern lassen", "cardText": "Möchten Sie den Plan mitten im Trek ändern, sind wir immer offen und tun unser Bestes, um es möglich zu machen.", "cardTitle": "Wir sind flexibel", "quoteNote": "Auch wenn es für unser Team mehr Arbeit, eine neue Buchung oder ein langes Telefonat bedeutet.", "limitsLead": "Wo die Flexibilität endet, ganz ehrlich:", "limitsText": "Sicherheit geht immer vor. Genehmigungen für Sperrgebiete legen Ihre Reisedaten und das Tal fest, das Sie betreten dürfen. Zusätzliche Tage unterwegs kosten zusätzliche Guide-, Träger- und Lodgetage, und diese Kosten nennen wir Ihnen, bevor wir etwas ändern. Änderungen vor der Buchung sind immer kostenlos.", "photoCaption": "Auf 4.980 m beim Langtang Valley Trek, 2025", "stagesHeading": "Wie Ihr Trek flexibel bleibt"}, "openMind": {"body": "Offenheit schenkt Ihnen neue Blickwinkel und neue Erlebnisse. Das gilt überall, aber ganz besonders in den Bergen Nepals, wo jedes Tal seine eigene Lebensweise hat.", "more": "Zwei Menschen können denselben Weg gehen und von zwei ganz verschiedenen Reisen heimkehren. Wer verschlossen unterwegs ist, dem kommen Berge, Flüsse und Wälder nach ein paar Tagen alle gleich vor.\r\n\r\nWer offen ist, bemerkt die Unterschiede. Fels und Bäume ändern sich, je höher Sie steigen. Essen und Gebetsfahnen ändern sich von Tal zu Tal. Dörfer der Gurung, Sherpa, Tamang und tibetischen Buddhisten leben jeweils auf ihre eigene Weise. Gerade diese Neugier ist oft das, woran sich unsere Gäste am meisten erinnern.", "quote": "Bringen Sie einfach Offenheit mit.", "places": [{"text": "Ein Gurung-Dorf mit steingedeckten Häusern unterhalb der Annapurna South.", "title": "Ghandruk, Annapurna"}, {"text": "Bunte Teehäuser am Talschluss, unterhalb der Gipfel des Langtang.", "title": "Kyanjin Gompa, Langtang"}, {"text": "Steinhäuser in einem Sperrgebiet, das nur wenige Trekker je zu sehen bekommen.", "title": "Dorf Phu, Manang"}], "eyebrow": "04 · Unsere wichtigste Überzeugung", "heading": "Offenheit macht Ihre Reise besser.", "invites": [{"text": "eine kurze Einführung in die Dörfer, Kulturen und Bräuche auf Ihrer Route, mit ein paar nepalesischen Wörtern zum Ausprobieren.", "title": "Vor dem Trek:"}, {"text": "Ihr Guide zeigt Ihnen, was sich von Tal zu Tal ändert, etwa Häuser, Felder, Essen, Feste und Glauben, nicht nur die Gipfel.", "title": "Unterwegs:"}, {"text": "eine Einladung zum Tee, ein Besuch im Kloster, ein Essen im Dorf oder ein Abstecher zu einem Aussichtspunkt.", "title": "Kleine „Ja“-Momente:"}], "cardLink": "Warum das wichtig ist", "cardText": "Neugier schenkt Ihnen in den Bergen neue Blickwinkel und neue Erlebnisse.", "cardTitle": "Wir glauben an Offenheit", "quoteNote": "Um den Rest kümmern wir uns.", "inviteNote": "Wir laden ein, wir belehren nie. Respekt vor den Menschen vor Ort steht immer an erster Stelle.", "inviteHeading": "Wie wir Sie einladen"}, "promises": [{"icon": "tune", "text": "Jeder Trek ist privat, damit der Plan zu Ihnen passt. Sie möchten einen zusätzlichen Ruhetag, ein langsameres Tempo oder eine andere Route? Sagen Sie es uns, und wir ändern es ohne Aufpreis.", "title": "Ganz auf Sie zugeschnitten"}, {"icon": "chat", "text": "Wir beraten Sie so, wie wir einen Freund beraten würden, auch wenn Sie dann weniger bei uns buchen. Unsere Preise sind transparent, ohne versteckte Gebühren.", "title": "Ehrliche Gespräche"}, {"icon": "shield_person", "text": "Ihr Guide ist in diesen Bergen aufgewachsen und kennt jede Biegung des Weges, den Sie gehen.", "title": "Guides, die in diesen Bergen zu Hause sind"}, {"icon": "health_and_safety", "text": "Wir planen in jeden Reiseverlauf Akklimatisierungstage ein, messen täglich Ihre Sauerstoffsättigung und haben auf jedem Trek einen Rettungsplan bereit. Pläne können sich ändern, die Sicherheit nie.", "title": "Ihre Sicherheit geht vor"}, {"icon": "verified", "text": "Wir sind bei der Regierung von Nepal und bei TAAN registriert. Sie buchen direkt bei unserem Team in Nepal, ohne Zwischenhändler. Unsere Träger tragen begrenzte Lasten und bekommen warme Ausrüstung, eine Versicherung und faire Löhne.", "title": "Einheimisch, lizenziert und fair zu unserem Team"}, {"icon": "temple_buddhist", "text": "Unterwegs nimmt Ihr Guide Sie mit in Dorfhäuser, stille Klöster und einheimische Küchen. Viele Gäste erzählen uns, dass diese Momente ihren Blick auf Nepal verändert haben.", "title": "Mehr als ein Trek"}], "statLabel": "Guides aus ihren eigenen Tälern", "statValue": "Alle", "storyText": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ich bin Sandip Kshetri, lizenzierter Guide aus Mirlung, einem Dorf am Hang im Distrikt Tanahun nahe dem Annapurna-Gebiet. Ich habe mehr als 200 Reisende durch Nepal geführt.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Meine Reise begann 2022 auf dem Mardi Himal Trek.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "An einem klaren Nachmittag blieb ich stehen und sah einer kleinen Wolke zu, die über die Annapurna South zog. Wie ich so dastand, war es, als würde der Berg mir etwas zuflüstern. In diesem Moment wurde mir klar, dass Berge, Flüsse und Wälder ihre eigene Stimme haben und wir nur zuhören müssen. Von diesem Tag an wurde meine Liebe zur Natur und zu den Bergen immer stärker. Diese Leidenschaft führte mich in den Tourismus, und 2025 habe ich Annapurna Trekking mitgegründet.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Ich habe diese Firma gegründet, um in meinem eigenen Land zu bleiben und ihm etwas zurückzugeben. Wir zahlen unseren Guides und Trägern 50 % mehr als branchenüblich, und kein Träger trägt mehr als 20 kg. Außerdem zeigen wir Nepal durch einheimische Stimmen, auch kleine Dörfer, von denen die meisten Reisenden nie hören.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Wir trekken langsam und mit offenen Augen, damit Sie die Dörfer, Flüsse und Wälder wahrnehmen, nicht nur den Gipfelblick. Vor allem steht für uns immer Ihre Sicherheit an erster Stelle.", "type": "text"}]}]}, "teamIntro": "Lizenzierte Guides aus jeder Region und ein kleines Büro in Kathmandu, das Ihre Nachrichten beantwortet.", "voiceText": "Uns ist noch etwas aufgefallen. Wir Nepalesen haben in der Welt nur selten eine eigene Stimme. Viel zu oft stellen ausländische Firmen und Menschen Nepal auf ihre eigene Weise dar.\r\n\r\nWir sind allen, die unser Land bekannt gemacht haben, von Herzen dankbar und werden ihren Beitrag nie vergessen. Aber es ist Zeit, dass wir Nepalesen selbst zur Welt sprechen.\r\n\r\nMit Annapurna Trekking möchten wir Nepal auf unsere eigene Weise zeigen. Wenn wir wachsen, werden wir Dokumentationen, Geschichten und Videos über Nepal machen, damit andere nicht mehr auf der Weltbühne für uns sprechen müssen.", "safetyLead": "Alle vier beruhen auf einer Regel:", "safetyText": "Ihre Sicherheit geht vor.", "storyTeaser": "Ich bin Sandip Kshetri, lizenzierter Guide aus Mirlung, einem Dorf am Hang im Distrikt Tanahun nahe dem Annapurna-Gebiet. Ich habe mehr als 200 Reisende durch Nepal geführt.\r\n\r\nMeine Reise begann 2022 auf dem Mardi Himal Trek. \r\nAn einem klaren Nachmittag blieb ich stehen und sah einer kleinen Wolke zu, die über die Annapurna South zog. Wie ich so dastand, war es, als würde der Berg mir etwas zuflüstern. In diesem Moment wurde mir klar, dass Berge, Flüsse und Wälder ihre eigene Stimme haben und wir nur zuhören müssen. Von diesem Tag an wurde meine Liebe zur Natur und zu den Bergen immer stärker. Diese Leidenschaft führte mich in den Tourismus, und 2025 habe ich Annapurna Trekking mitgegründet.\r\nIch habe diese Firma gegründet, um in meinem eigenen Land zu bleiben und ihm etwas zurückzugeben. Wir zahlen unseren Guides und Trägern 50 % mehr als branchenüblich, und kein Träger trägt mehr als 20 kg. Außerdem zeigen wir Nepal durch einheimische Stimmen, auch kleine Dörfer, von denen die meisten Reisenden nie hören.\r\nWir trekken langsam und mit offenen Augen, damit Sie die Dörfer, Flüsse und Wälder wahrnehmen, nicht nur den Gipfelblick. Vor allem steht für uns immer Ihre Sicherheit an erster Stelle.", "teamHeading": "Die Menschen, die Ihren Trek planen und führen", "storyHeading": "Lernen Sie Sandip Kshetri kennen, den Gründer von Annapurna Trekking", "voiceEyebrow": "Unsere Stimme", "voiceHeading": "Nepal, gezeigt so, wie Einheimische es zeigen würden", "founderOrigin": "Aus Tanahun, nahe dem Annapurna-Gebiet", "licencesIntro": "Jede Zahl unten können Sie beim Department of Tourism in Nepal und bei TAAN überprüfen.", "promisesIntro": "", "trekkersGuided": "50+", "licencesHeading": "Registriert, lizenziert und versichert", "promisesHeading": "", "trekkingRegions": ""}'::jsonb where site_id = 'annapurna' and slug = 'about';
update public.site_pages set eyebrow = 'Unser Team ist online · Kathmandu', heading = 'Sprechen Sie mit einem einheimischen Trekking-Experten', intro = 'Fragen Sie uns alles, von „Welcher Trek passt zu mir?“ bis zu Genehmigungen und Preisen. Ein echter Mensch aus unserem Team in Kathmandu antwortet Ihnen, meist innerhalb weniger Stunden. Kostenlos und ohne Buchungsverpflichtung.', seo_title = 'Kontakt: Sprechen Sie mit einem Trekking-Experten vor Ort', seo_description = 'Fragen Sie unser Team in Kathmandu per WhatsApp oder E-Mail alles zum Trekking in Nepal. Antwort meist in wenigen Stunden, kostenlos und unverbindlich.', seo_keyword = 'Trekking Agentur Nepal Kontakt', content = '{"faqs": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Per WhatsApp meist innerhalb weniger Stunden während der Bürozeiten in Nepal, per E-Mail innerhalb von 24 Stunden.", "type": "text"}]}]}, "question": "Wie schnell antworten Sie?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Nein. Fragen, Vorschläge und Reiseverläufe sind kostenlos und ohne Buchungsverpflichtung.", "type": "text"}]}]}, "question": "Kostet eine Anfrage etwas?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Diese Website speichert Ihre Nachricht nicht. Sie öffnet WhatsApp oder Ihr E-Mail-Programm, und wir verwenden Ihre Angaben nur, um Ihnen zu antworten.", "type": "text"}]}]}, "question": "Speichern Sie meine Daten?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja. Schreiben Sie uns auf WhatsApp, und wir vereinbaren einen Sprach- oder Videoanruf zu einer Zeit, die Ihnen passt.", "type": "text"}]}]}, "question": "Können wir telefonieren?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Natürlich. Kommen Sie während der Öffnungszeiten im Büro vorbei, oder schreiben Sie uns, und wir treffen uns mit Ihnen.", "type": "text"}]}]}, "question": "Ich bin schon in Kathmandu. Kann ich vorbeikommen?"}], "timeNote": "Außerhalb dieser Zeiten? Hinterlassen Sie eine WhatsApp-Nachricht. Wir antworten gleich am nächsten Morgen.", "nextSteps": [{"text": "Nennen Sie uns Ihre Reisedaten, die Gruppengröße und was Sie gern sehen möchten. Auch reine Fragen sind willkommen.", "when": "Heute", "title": "Sie schicken uns eine Nachricht"}, {"text": "Ein Experte vor Ort schlägt Ihnen den passenden Trek vor, mit Reiseverlauf Tag für Tag und einem klaren Preis für Ihre Gruppe.", "when": "Innerhalb weniger Stunden", "title": "Wir antworten mit Plan und Preis"}, {"text": "Wir buchen Genehmigungen, Transport, Guides und Lodges. Sie können den Plan kostenlos ändern, bis er passt.", "when": "Wenn Sie bereit sind", "title": "Bestätigen Sie mit 10 % Anzahlung"}], "timeZones": ["Europe/Berlin", "Europe/London", "America/New_York"], "faqHeading": "Bevor Sie uns schreiben", "replyTimes": {"email": "Antwort innerhalb von 24 Stunden", "whatsApp": "Antwortet meist innerhalb weniger Stunden"}, "officeDirections": ""}'::jsonb where site_id = 'annapurna' and slug = 'contact';
update public.site_pages set heading = 'Cookie-Einstellungen', intro = 'Wählen Sie, was diese Website laden darf. Notwendige Funktionen sind immer aktiv; alles andere bleibt ausgeschaltet, bis Sie es erlauben.', content = '{"body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Was wir verwenden", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Name", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Zweck", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Speicherdauer", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "consent", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Speichert Ihre Auswahl auf dieser Seite", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "12 Monate", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Google Analytics", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Zählt Seitenaufrufe (nur mit Ihrer Einwilligung)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Von Google festgelegt", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Google Maps", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Interaktive Routen- und Bürokarten (nur mit Ihrer Einwilligung)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Von Google festgelegt", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "YouTube", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Trekking-Videos im erweiterten Datenschutzmodus (nur mit Ihrer Einwilligung)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Von Google festgelegt", "type": "text"}]}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Meinung geändert?", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Sie können jederzeit über den Link „Cookie-Einstellungen“ unten auf jeder Seite zu dieser Seite zurückkehren. Der Widerruf Ihrer Einwilligung berührt nicht die Rechtmäßigkeit dessen, was vorher geladen wurde.", "type": "text"}]}]}, "autoDate": true, "lastUpdated": "2026-10-29", "lawyerChecked": false}'::jsonb where site_id = 'annapurna' and slug = 'cookies';
update public.site_pages set intro = 'Rechtliche Angaben zu dieser Website (Angaben gemäß § 5 DDG und § 18 MStV für Besucher aus Deutschland).', content = '{"body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Anbieter", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "{company}", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "{address}", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Vertreten durch", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Sandip Kshetri, CEO", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Kontakt", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Telefon: {phone}", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "WhatsApp: {phone}", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "E-Mail: {email}", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Registrierung und Lizenzen", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "{registers}", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Verbraucherstreitbeilegung", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Wir sind nicht bereit oder verpflichtet, an Streitbeilegungsverfahren vor einer Verbraucherschlichtungsstelle teilzunehmen.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Fotos", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Alle Fotos auf dieser Website sind unsere eigenen, sofern nicht anders angegeben.", "type": "text"}]}]}, "autoDate": true, "lastUpdated": "2026-10-29", "lawyerChecked": false}'::jsonb where site_id = 'annapurna' and slug = 'impressum';
update public.site_pages set heading = 'Datenschutzerklärung', intro = 'Wie wir mit Ihren personenbezogenen Daten umgehen, wenn Sie diese Website besuchen oder uns kontaktieren. Kurz gesagt: Wir erheben so wenig wie möglich.', content = '{"body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Verantwortlicher", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "{company}, {address}. E-Mail: {email}. [EU representative under Art. 27 GDPR].", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Was diese Website nicht tut", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Auf dieser Website gibt es keine Benutzerkonten und keine Online-Zahlungen.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Unsere Kontakt- und Buchungsformulare senden oder speichern nichts auf unseren Servern. Sie öffnen nur WhatsApp oder Ihr E-Mail-Programm.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Schriftarten liegen auf unserem eigenen Server, es gehen also keine Daten an Google Fonts.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Server-Logfiles", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Wenn Sie eine Seite aufrufen, erfasst unser Hosting-Anbieter automatisch technische Daten wie IP-Adresse, Datum und Uhrzeit, aufgerufene Seite und Browser. Das ist nötig, um die Website sicher auszuliefern (Art. 6 Abs. 1 lit. f DSGVO), und wird nach 30 Tagen gelöscht. Hosting: Vercel Inc., auf Servern von Amazon Web Services (AWS) in Deutschland.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Kontakt per WhatsApp oder E-Mail", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Wenn Sie uns schreiben, verwenden wir Ihren Namen, Ihre Kontaktdaten und Ihre Nachricht nur, um Ihnen zu antworten und Ihren Trek zu planen (Art. 6 Abs. 1 lit. b DSGVO). WhatsApp ist ein Dienst der WhatsApp Ireland Ltd. (Meta); dabei können Daten in die USA übermittelt werden. Wenn Sie das nicht möchten, kontaktieren Sie uns stattdessen per E-Mail.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Zählung von Button-Klicks", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Wir zählen Klicks auf unsere WhatsApp- und E-Mail-Buttons ohne Cookies und ohne Ihre IP-Adresse zu speichern, um zu sehen, welche Seiten weiterhelfen. Diese Zahlen lassen keinen Rückschluss auf Ihre Person zu.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Cookies, Analyse und externe Medien", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Analysedienste nutzen wir und externe Medien (Google Maps, YouTube) laden wir nur, wenn Sie in unseren Cookie-Einstellungen eingewilligt haben (Art. 6 Abs. 1 lit. a DSGVO). Sie können Ihre Auswahl jederzeit unter Cookie-Einstellungen ändern.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Analyse: Google Analytics und Microsoft Clarity, um zu verstehen, welche Seiten gelesen werden", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Google Maps: zeigt Routenkarten und unser Büro, wird erst nach Ihrem Klick geladen", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "YouTube (erweiterter Datenschutzmodus): Trekking-Videos, werden erst nach Ihrem Klick geladen", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Wie lange wir Daten speichern", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Nachrichten zu einem Trek speichern wir so lange, wie es für die Planung und für gesetzliche Aufbewahrungspflichten in Nepal nötig ist. Wir speichern diese Daten 12 Monate lang und löschen sie dann.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Ihre Rechte", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Sie können jederzeit Auskunft über Ihre Daten, deren Berichtigung, Löschung, Einschränkung der Verarbeitung oder eine Kopie (Datenübertragbarkeit) verlangen, der Verarbeitung widersprechen oder Ihre Einwilligung widerrufen. Außerdem haben Sie das Recht, sich bei einer Datenschutz-Aufsichtsbehörde zu beschweren, zum Beispiel bei der Behörde an Ihrem Wohnort.", "type": "text"}]}]}, "autoDate": true, "lastUpdated": "2026-10-29", "lawyerChecked": false}'::jsonb where site_id = 'annapurna' and slug = 'privacy';
update public.site_pages set heading = 'AGB und Buchungsbedingungen', intro = 'Diese Bedingungen gelten, wenn Sie einen Trek bei Annapurna Trekking buchen. Bitte lesen Sie sie, bevor Sie eine Anzahlung leisten.', content = '{"body": {"type": "doc", "content": [{"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Wer wir sind", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Diese Bedingungen gelten für Treks, die von {company}, {address}, organisiert werden, registriert beim Department of Tourism unter der Nr. {licence} („wir“, „uns“).", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "So funktioniert die Buchung", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Sie planen Ihren Trek mit uns per WhatsApp oder E-Mail. Ihre Buchung ist bestätigt, sobald wir Ihre Anzahlung erhalten und Ihnen eine schriftliche Bestätigung mit Reiseverlauf und Reisepreis geschickt haben.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Preise und Zahlung", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Preise gelten pro Person in US-Dollar und richten sich nach der Gruppengröße. Was im Preis enthalten ist und was nicht, steht auf jeder Trek-Seite und in Ihrer Bestätigung.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Anzahlung: 10 % des Reisepreises zur Bestätigung Ihrer Buchung", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Restzahlung: fällig bei Ankunft in Kathmandu", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Zahlungsarten: bar oder per Banküberweisung", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Änderungen und Absage durch uns", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Bergwetter, Erdrutsche, gesperrte Wege oder Sicherheitsbedenken können Änderungen erzwingen. Ihr Guide kann die Route ändern oder umkehren, wenn das Weitergehen nicht sicher ist. Sagen wir vor der Abreise ab, erhalten Sie alles, was Sie uns gezahlt haben, vollständig zurück.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Rücktritt durch Sie", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Bitte teilen Sie uns Ihren Rücktritt schriftlich mit (per E-Mail oder WhatsApp). Was Sie zurückerhalten, hängt davon ab, wie lange vor Beginn Ihres Treks wir von Ihnen hören:", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Zeitpunkt des Rücktritts", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Erstattung", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Mehr als 72 Stunden vor Ihrem Trek", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Volle Erstattung, abzüglich Bankgebühren und etwaiger Kosten für Genehmigungen", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Zwischen 72 und 48 Stunden vor Ihrem Trek", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Erstattung abzüglich der Kosten, die wir für Ihren Trek bereits bezahlt haben", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Weniger als 48 Stunden vorher oder Nichterscheinen", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Keine Erstattung: Der volle Reisepreis wird berechnet", "type": "text"}]}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Vorzeitige Rückkehr", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Kehren Sie gleich aus welchem Grund vorzeitig von Ihrem Trek zurück, können wir nichts erstatten. Ihre Guides und Träger werden weiterhin für alle ursprünglich gebuchten Tage bezahlt.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Änderungen durch Sie", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Sie können Reisedaten, Route oder Gruppengröße vor der Abreise kostenlos ändern, sofern verfügbar. Mehrkosten, etwa für zusätzliche Tage oder Genehmigungen, berechnen wir zum Selbstkostenpreis.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Verspätungen und Ausfälle von Inlandsflügen", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Bergflüge in Nepal, zum Beispiel nach Lukla, verspäten sich wetterbedingt oft oder fallen aus. In diesem Fall tragen Sie die Kosten für dadurch nötige zusätzliche Hotelnächte.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Versicherung, Gesundheit und Fitness", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Eine persönliche Reiseversicherung ist Pflicht. Sie muss Notfälle abdecken, einschließlich Trekking in den Höhen Ihres Treks und Hubschrauberrettung. Unsere eigenen Guides und Träger versichern wir selbst. Sie bestätigen, dass Sie für den gebuchten Trek fit genug sind, und informieren uns über relevante gesundheitliche Einschränkungen.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Dokumente und Genehmigungen", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Sie benötigen einen Reisepass, der noch mindestens sechs Monate gültig ist, und ein Visum für Nepal. Wir besorgen Ihre Trekking-Genehmigungen; Sie stellen uns rechtzeitig Passkopien und Passfotos zur Verfügung.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Unsere Verantwortung", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Wir planen und führen Ihren Trek mit angemessener Sorgfalt und Sachkenntnis durch, mit lizenzierten Guides und bewährten Partnern vor Ort wie Lodges, Fahrern und Fluggesellschaften. Wir sind für die Erbringung der in Ihrer Bestätigung aufgeführten Leistungen verantwortlich.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Trekking im Himalaya birgt natürliche Risiken, darunter Höhenkrankheit, plötzliche Wetterumschwünge, Erdrutsche und raue Wege. Wir verringern diese Risiken mit Akklimatisierungstagen, täglichen Gesundheitschecks und einem Rettungsplan, können sie aber nicht ausschließen. Mit Ihrer Buchung akzeptieren Sie diese Risiken.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Wir haften nicht für Verletzungen, Krankheiten, Verluste, Verspätungen oder Mehrkosten durch Ereignisse außerhalb unserer Kontrolle, etwa Wetter, Naturkatastrophen, Streiks, politische Unruhen, behördliche Entscheidungen, Straßensperrungen oder Verspätungen und Ausfälle von Flügen durch Fluggesellschaften.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Wir haften nicht für Probleme, die entstehen, weil Sie die Sicherheitsanweisungen Ihres Guides nicht befolgt haben, oder durch gesundheitliche Einschränkungen, die Sie uns nicht mitgeteilt haben.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Bitte bewahren Sie Geld, Reisepass und Wertsachen sicher auf. Für Verlust oder Beschädigung Ihrer persönlichen Gegenstände haften wir nicht.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Notfallkosten wie Hubschrauberrettung, Krankenhausbehandlung oder zusätzliche Übernachtungen tragen Sie selbst bzw. Ihre Reiseversicherung.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Soweit wir haften, ist unsere Haftung auf den Betrag begrenzt, den Sie uns für Ihren Trek gezahlt haben, außer wenn das Gesetz diese Begrenzung nicht zulässt.", "type": "text"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"text": "Beschwerden", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Bitte sagen Sie Ihrem Guide oder unserem Büro sofort Bescheid, wenn etwas nicht stimmt, damit wir es vor Ort beheben können. Sind Sie danach noch unzufrieden, schreiben Sie uns innerhalb von 30 Tagen nach Ende Ihres Treks eine E-Mail.", "type": "text"}]}]}, "autoDate": true, "lastUpdated": "2026-10-29", "lawyerChecked": false}'::jsonb where site_id = 'annapurna' and slug = 'terms';
update public.site_pages set heading = 'Annapurna Trekking Blog', intro = 'Kosten, Reisezeiten, Genehmigungen, Packliste und Gesundheit, geschrieben von den Menschen, die die Treks führen. Lesen Sie vor der Reise nach, oder fragen Sie uns, was Sie hier nicht finden.', seo_title = 'Annapurna Trekking Blog: Kosten, Reisezeit, Packliste', seo_description = 'Praktische Tipps zum Trekking im Annapurna-Gebiet von einheimischen Guides: Kosten, beste Reisezeit, Genehmigungen und Packliste.', seo_keyword = 'Annapurna Trekking Blog' where site_id = 'annapurna' and slug = 'travel-guides';
update public.trek_translations set faqs = '[{"icon": "calendar_month", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Khopra Danda Trek ist ein mittelschwerer Trek. Er hat keine technischen Passagen, doch lange Steintreppen, 5 bis 7 Stunden Gehzeit am Tag und ein höchster Punkt auf 3.660 m machen ihn zu einer echten körperlichen Herausforderung. Fitte Einsteiger schaffen ihn mit etwas Training.", "type": "text"}]}]}, "question": "Wie schwierig ist der Khopra Danda Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Planen Sie 8 Tage ab Pokhara ein, inklusive eines freien Tages in Khopra zum Ausruhen oder für die optionale Wanderung zum Khayer-See. Fitte Trekker mit wenig Zeit schaffen ihn in 6 oder 7 Tagen, und ein 9-Tage-Plan enthält einen zusätzlichen Ruhetag für ein ruhigeres Tempo.", "type": "text"}]}]}, "question": "Wie viele Tage brauche ich für den Khopra Ridge Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja, fitte Einsteiger schaffen ihn mit guter Vorbereitung. Wenn Sie an zwei Tagen hintereinander 5 bis 6 Stunden mit einem Tagesrucksack wandern können, sind Sie bereit. Der höchste Punkt auf 3.660 m ist ein guter erster Schritt für alle, die noch keine Erfahrung mit der Höhe haben.", "type": "text"}]}]}, "question": "Können Einsteiger den Khopra Danda Trek machen?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Oktober bis November und März bis Mai sind die besten Monate. Im Herbst ist die Bergsicht am klarsten, im Frühling blüht der Rhododendronwald. Im Winter ist der Trek möglich, aber kalt; von den Monsunmonaten Juni bis August raten wir ab.", "type": "text"}]}]}, "question": "Wann ist die beste Reisezeit für den Khopra Danda Trek?"}], "title": "Reiseverlauf und Dauer"}, {"icon": "info", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Trek beginnt und endet in Pokhara. Sie fahren nach Nayapul und wandern über Ulleri und Ghorepani zum Khopra Ridge, steigen dann zu den heißen Quellen von Tatopani ab und fahren zurück nach Pokhara.", "type": "text"}]}]}, "question": "Wo beginnt und endet der Khopra Danda Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja, Poon Hill ist Teil unseres Khopra-Danda-Reiseverlaufs. Sie erleben den Sonnenaufgang am Poon Hill an Tag 3 und lassen die Menschenmengen danach auf dem ruhigeren Weg nach Khopra hinter sich.", "type": "text"}]}]}, "question": "Kann ich Poon Hill und Khopra kombinieren?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Khopra ist die bessere Wahl, wenn Sie ruhige Wege und einen nahen Blick auf den Dhaulagiri suchen. Poon Hill ist kürzer und belebter, das Annapurna Base Camp höher und länger. Khopra bietet Ihnen große Bergblicke mit weit weniger Menschen.", "type": "text"}]}]}, "question": "Ist Khopra besser als Poon Hill oder das Annapurna Base Camp?"}], "title": "Route und Höhepunkte"}, {"icon": "fitness_center", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Khopra Ridge auf 3.660 m ist der höchste Punkt und zugleich Ihr Übernachtungsort. Die optionale Tageswanderung zum Khayer-See führt auf 4.660 m und kehrt am selben Tag nach Khopra zurück.", "type": "text"}]}]}, "question": "Was ist der höchste Punkt des Khopra Danda Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ernsthafte Höhenkrankheit ist auf diesem Trek selten, leichte Kopfschmerzen in Khopra sind aber häufig. Die Route steigt über vier Tage allmählich an, was Ihrem Körper bei der Anpassung hilft. Trinken Sie 3 bis 4 Liter Wasser am Tag, gehen Sie langsam und informieren Sie Ihren Guide über jedes Symptom.", "type": "text"}]}]}, "question": "Bekomme ich auf dem Khopra Trek Höhenkrankheit?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja, mit guter Vorbereitung ist er sicher. Die Hauptrisiken sind die Höhe, das Wetter und rutschige Treppen. Ein lizenzierter Guide, eine passende Versicherung und ein flexibler Plan für den Tag am Khayer-See fangen die meisten dieser Risiken ab.", "type": "text"}]}]}, "question": "Ist der Khopra Danda Trek sicher?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja, eine Reiseversicherung ist Pflicht. Sie muss Trekking bis 4.500 m und eine Hubschrauberevakuierung abdecken, da eine Rettung vom Grat per Hubschrauber erfolgt.", "type": "text"}]}]}, "question": "Brauche ich eine Reiseversicherung?"}], "title": "Höhe und Gesundheit"}, {"icon": "description", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Sie benötigen die Genehmigung für das Annapurna Conservation Area (ACAP). Wir besorgen sie vor Ihrer Ankunft.", "type": "text"}]}]}, "question": "Welche Genehmigungen brauche ich für den Khopra Danda Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Nein, ausländische Trekker benötigen im Annapurna Conservation Area einen lizenzierten Guide.", "type": "text"}]}]}, "question": "Kann ich den Khopra Danda Trek ohne Guide machen?"}], "title": "Genehmigungen und Guides"}, {"icon": "restaurant", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Sie übernachten in einfachen Teehäusern, am oberen Grat in gemeindegeführten Lodges. Die Zimmer sind Zweibettzimmer, weiter oben mit Gemeinschaftstoiletten. Die Lodge in Khopra ist einfach und solarbetrieben, doch ihre Einnahmen unterstützen örtliche Schulen und die Gesundheitsversorgung.", "type": "text"}]}]}, "question": "Wie sind die Unterkünfte auf dem Khopra Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Nein, nach Pokhara gibt es keine Geldautomaten mehr. Heben Sie in Pokhara genug Nepalesische Rupien für Essen, Getränke, Aufladen und Trinkgelder ab und nehmen Sie kleine Scheine mit.", "type": "text"}]}]}, "question": "Gibt es auf dem Khopra Danda Trek Geldautomaten?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Rechnen Sie mit etwa US$25 bis 35 pro Tag für Mahlzeiten und heiße Getränke. Die Preise steigen mit der Höhe. Dal Bhat mit kostenlosem Nachschlag bietet das beste Preis-Leistungs-Verhältnis.", "type": "text"}]}]}, "question": "Wie viel sollte ich für Essen auf dem Trek einplanen?"}], "title": "Lodges, Essen und Geld"}]'::jsonb, summary = 'Eine ruhige Gratwanderung in der Annapurna-Region mit weiten Blicken auf Dhaulagiri und Annapurna South.', activity = 'Trekking / Wandern', category = 'Grat-Trek', excluded = '[{"text": "Sie bestellen von der Speisekarte der Lodges und zahlen direkt, was die Lodges unterstützt (siehe Essensbudget unten).", "title": "Mahlzeiten auf dem Trek:"}, {"text": "Internationale Flüge und Ihr Visum für Nepal.", "title": "Flüge und Visum:"}, {"text": "Gäste schließen ihre Reiseversicherung selbst ab.", "title": "Reiseversicherung:"}, {"text": "Für Ihren Guide und Träger, nach Ihrem Ermessen.", "title": "Trinkgelder:"}, {"text": "Zusätzliche Nächte, Transporte oder Evakuierungen aufgrund von Wetter, Erdrutschen, Krankheit oder Flugverspätungen.", "title": "Ungeplante Kosten:"}]'::jsonb, headline = 'Khopra Ridge (Danda) Trek – 8 Tage, USD 275', included = '[{"text": "Genehmigung für das Annapurna Conservation Area (ACAP), besorgt vor Ihrer Ankunft.", "title": "Genehmigungen:"}, {"text": "Ein erfahrener, lizenzierter Trekkingguide, der die Khopra-Route und die Gemeinde-Lodges kennt.", "title": "Guide:"}, {"text": "7 Nächte in Teehäusern und gemeindegeführten Lodges im Zweibettzimmer, von Ulleri bis Tatopani.", "title": "Unterkunft:"}, {"text": "Privater Jeep von Pokhara zum Ausgangspunkt und von Tatopani zurück nach Pokhara.", "title": "Transport:"}, {"text": "Verpflegung, Unterkunft, Lohn und Versicherung Ihres Guides.", "title": "Kosten des Guides:"}, {"text": "Ein Vorgespräch in Pokhara, um Ihre Ausrüstung zu prüfen und Ihre Fragen zu beantworten.", "title": "Briefing:"}, {"text": "Direkter Kontakt zu unserem Büro während des gesamten Treks und Notfallkoordination, falls nötig.", "title": "Betreuung:"}, {"text": "Alle staatlichen Steuern und Servicegebühren.", "title": "Steuern:"}]'::jsonb, days_note = '8 Tage', transport = 'Jeep nach Ghandruk', card_badge = 'Ruhiger als Poon Hill', high_point = 'Khayer-See', highlights = '[{"text": "Über die Kali Gandaki, die tiefste Schlucht der Erde", "title": "Dhaulagiri und Annapurna South auf Augenhöhe"}, {"text": "Sie übernachten mit Blick auf Annapurna South und Dhaulagiri und sehen so Sonnenuntergang und Sonnenaufgang direkt von Ihrer Lodgetür aus.", "title": "Übernachtung auf dem Grat auf 3.660 m"}, {"text": "Die Lodges auf dem Grat werden von den Gemeinden geführt, und ihre Einnahmen finanzieren örtliche Schulen und die Gesundheitsversorgung.", "title": "Lodges im Besitz der Dörfer"}, {"text": "Eine optionale Tageswanderung führt Sie zu einem heiligen Bergsee unterhalb der Annapurna South, den nur wenige Trekker je erreichen.", "title": "Heiliger Khayer-See (4.660 m)"}, {"text": "Steigen Sie zum Sonnenaufgang auf den Muldai-Aussichtspunkt (3.637 m) und genießen Sie ein weites Panorama über Dhaulagiri, die Annapurnas und den Machhapuchhre, fast ohne andere Menschen.", "title": "Muldai-Aussichtspunkt im Morgengrauen"}, {"text": "Beenden Sie Ihren Trek mit einem Bad in den natürlichen heißen Quellen am Kali-Gandaki-Fluss.", "title": "Heiße Quellen von Tatopani"}]'::jsonb, know_intro = 'Was unsere Guides jedem Trekker sagen, bevor es in Pokhara losgeht, aus vielen Jahren auf diesem Grat.', route_line = 'Übersicht der Route des Khopra Danda Trek (Pokhara → Khopra Danda → Pokhara)', faq_heading = 'Häufige Fragen zum Khopra Danda (Ridge) Trek', guide_ratio = '1 : 4 + Träger', know_topics = '[{"body": {"type": "doc", "content": [{"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Frühling (März bis Mai):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " warme Tage, Rhododendronwälder in voller Blüte und nachmittags etwas Dunst.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Herbst (Oktober bis November):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " der klarste Himmel des Jahres, scharfe Sicht auf den Dhaulagiri und kalte Nächte auf dem Grat.", "type": "text"}]}]}]}, {"type": "paragraph"}, {"type": "paragraph"}]}, "icon": "wb_twilight", "note": "Monsun (Juni bis August): nicht empfohlen, mit Regen, Blutegeln, rutschigen Treppen und Wolken über den Bergen.", "title": "Beste Reisezeit für den Khopra Danda (Ridge) Trek", "photoId": null, "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Auf dem Khopra Danda Trek übernachten Sie in einfachen Teehäusern, am oberen Grat in gemeindegeführten Lodges.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Zimmer:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Zweibettzimmer mit dünnen Matratzen und einer Decke. Bringen Sie einen warmen Schlafsack mit.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Toiletten:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " oberhalb von Ghorepani gemeinschaftlich und oft Hocktoiletten.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Heizung:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " die Schlafzimmer sind kalt, der Ofen im Speiseraum wird abends angeheizt.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Lodge in Khopra:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " im Besitz der Gemeinde und solarbetrieben, daher sind Duschen und Aufladen nur eingeschränkt möglich.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Mehr Komfort:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in Ghorepani und Tatopani, mit heißen Duschen und WLAN gegen Gebühr.", "type": "text"}]}]}]}, {"type": "paragraph"}]}, "icon": "cottage", "note": "", "title": "Teehäuser und Gemeinde-Lodges", "photoId": null, "videoId": null}, {"body": {"type": "doc", "content": [{"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Dal Bhat:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Reis, Linsen und Gemüse in den meisten Lodges.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Weitere Gerichte:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Nudeln, gebratener Reis, Momos, Porridge, Pfannkuchen und Eier. Weiter oben wird die Auswahl kleiner.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tägliches Essensbudget:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " etwa US$25–35 für drei Mahlzeiten und heiße Getränke.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Trinkwasser:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in den Lodges auffüllen und mit einem Filter oder Entkeimungstabletten aufbereiten.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Wie viel trinken:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " 3 bis 4 Liter am Tag, um Höhenkrankheit vorzubeugen.", "type": "text"}]}]}]}, {"type": "paragraph"}]}, "icon": "soup_kitchen", "note": "", "title": "Essen und Trinkwasser auf dem Trek", "photoId": null, "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die Höhe ist das Hauptrisiko auf dem Khopra Danda Trek, und die meisten Probleme lassen sich gut in den Griff bekommen, wenn Sie früh handeln.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Höchste Übernachtung:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " 3.660 m auf dem Khopra Ridge, wo leichte Kopfschmerzen häufig sind.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Warnzeichen:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Kopfschmerzen, die nicht vergehen, Übelkeit, Schwindel oder schlechter Schlaf. Sagen Sie es sofort Ihrem Guide.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Behandlung:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " zuerst ausruhen, dann absteigen, wenn die Symptome schlimmer werden.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Handyempfang:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " gut in Ghorepani und Tatopani, lückenhaft auf dem Grat.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Notfälle:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " wir koordinieren über Ihre Versicherung eine Hubschrauberevakuierung nach Pokhara.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Versicherung:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " muss Trekking bis 4.500 m und Hubschrauberrettung abdecken.", "type": "text"}]}]}]}, {"type": "paragraph"}]}, "icon": "emergency", "note": "", "title": "Höhe, Sicherheit und Notfälle", "photoId": null, "videoId": null}]'::jsonb, guides_intro = 'Sorgfältig ausgewählte, lizenzierte Guides, die den Khopra-Grat schon oft gegangen sind, in Erster Hilfe in der Wildnis geschult sind und Ihre Sicherheit im Blick haben.', introduction = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Khopra Ridge Trek ist ein 8-tägiger Trek von Pokhara zum Khopra Danda (3.660 m), einem offenen, grasbewachsenen Grat in Nepals Annapurna-Region mit nahem Blick auf Dhaulagiri und Annapurna South. Er beginnt im Gurung-Dorf Ghandruk, steigt durch ruhige Rhododendronwälder zum Grat hinauf und endet an den natürlichen heißen Quellen von Tatopani.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Nach Ghandruk und Tadapani gehen die meisten Trekker weiter in Richtung Annapurna Base Camp. Wir biegen nach Nordwesten auf einen Gemeindeweg ab, den nur wenige Gruppen nehmen. Der Pfad steigt durch alten Rhododendron-, Eichen- und Bambuswald nach Dobato, und oft gehen Sie einen halben Tag, ohne einer anderen Gruppe zu begegnen. Früh am nächsten Morgen wandern Sie hinauf zum Muldai-Aussichtspunkt (3.637 m) und erleben Ihren ersten großen Sonnenaufgang über Dhaulagiri und den Annapurnas. Oberhalb von Chistibung enden dann die Bäume, und Sie treten hinaus auf einen kahlen, windigen Grat.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Von Khopra aus steht der Dhaulagiri (8.167 m) direkt gegenüber, jenseits der Kali Gandaki, einer der tiefsten Schluchten der Welt. Die Annapurna South ragt ganz nah auf, dazwischen liegen der Nilgiri und das Annapurna-Massiv. Sie verbringen zwei Nächte auf dem Grat und sehen so zweimal, wie das Licht vom Sonnenuntergang bis zum Sonnenaufgang über die Berge wandert.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Die Lodges auf dem Khopra Ridge gehören den Gemeinden. Komitees aus den Dörfern unterhalb führen sie und teilen die Einnahmen, mit denen örtliche Schulen, Gesundheitsversorgung und Dorfprojekte finanziert werden. Wenn Sie hier essen oder übernachten, bleibt Ihr Geld in den Bergen, durch die Sie wandern.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Konditionsstarke Wanderer können eine Tageswanderung von Khopra zum Khayer-See (4.660 m) anhängen, einem heiligen See am Fuß der Annapurna South. Hin und zurück sind es lange 7 bis 8 Stunden, und nur wenige Trekker erreichen ihn. Pilger steigen jedes Jahr im August zum Vollmondfest hinauf. Den Rest des Jahres haben Sie den See vielleicht ganz für sich. Ihr Guide entscheidet am Morgen endgültig, je nach Wetter und danach, wie alle geschlafen haben.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Beim Abstieg übernachten Sie in Swanta, einem Magar-Dorf, das für seine gemeinschaftliche Käserei bekannt ist. Der letzte Wandertag folgt dem alten Weg des Annapurna Circuit durch die Dörfer Shikha und Ghara hinunter nach Tatopani im Tal der Kali Gandaki. Hier entspannen Sie müde Beine in natürlichen heißen Quellen, bevor es mit dem Auto zurück nach Pokhara geht.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Dieser Trek eignet sich für fitte Wanderer, die Himalaya-Blicke aus nächster Nähe ohne die Menschenmengen der Hauptrouten im Annapurna-Gebiet suchen. Es gibt keine Gletscher oder technischen Passagen, aber lange Steintreppen und Wandertage von 3 bis 6 Stunden, dazu einen Tag mit 7 bis 8 Stunden, wenn Sie zum Khayer-See wandern. Die Lodges sind einfach, und die Nächte in Khopra sind kalt. Mit 3.660 m ist der höchste Punkt ein guter erster Schritt für alle, die noch nie in der Höhe getrekkt sind.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Unsere Guides sind diesen Grat schon oft gegangen. Sie kennen die Lodge-Komitees, das Wetter und den richtigen Zeitpunkt für den Aufbruch zum Khayer-See. Wir kümmern uns vor Ihrer Ankunft um Ihre ACAP-Genehmigung, den Transport und die Lodges, damit Sie sich ganz aufs Wandern konzentrieren können.", "type": "text"}]}]}'::jsonb, know_heading = 'Khopra Danda Trek: Reisezeit, Lodges und Sicherheit', packing_line = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Packen Sie für zwei Klimazonen: frostige Nächte auf 3.660 m am Khopra Ridge und warme, sonnige Tage unten in Tatopani.", "type": "text"}]}]}'::jsonb, photo_badges = '[{"icon": "route", "tone": "green", "label": "Ruhiger Weg, weniger Andrang"}, {"icon": "star", "tone": "brand", "label": "Optionale Wanderung zum Khayer-See"}, {"icon": "nordic_walking", "tone": "brand", "label": "Heiße Quellen von Tatopani"}]'::jsonb, season_label = 'März–Mai und Okt.–Nov.', accommodation = 'Teehaus und Hotel', daily_walking = '5 bis 7 Stunden am Tag', intro_heading = 'Einführung', pricing_intro = 'Buchen Sie direkt bei unserem Team in Kathmandu, ohne Zwischenhändler. Jeder Trek ist ein Privattrek, Sie wählen Ihr Startdatum also selbst.', similar_intro = 'Treks, die wir mit Ihnen planen und die von lokalen Guides geführt werden.', elevation_note = 'Die Route steigt in vier Tagen langsam von 2.070 m (Ulleri) auf 3.660 m (Khopra Danda). Oben übernachten Sie zweimal und haben so einen ganzen Tag zur Akklimatisierung.', guides_heading = 'Lernen Sie Ihren Trekkingguide kennen', packing_groups = '[{"icon": "apparel", "items": [{"text": "Unverzichtbar in Khopra, wo die Nächte oft unter den Gefrierpunkt fallen.", "title": "Daunenjacke"}, {"text": "2 Thermo-Oberteile und 1 Thermohose für kalte Nächte auf dem Grat.", "title": "Basisschichten"}, {"text": "Eine warme Mittelschicht für Morgen, Abende und Pausen.", "title": "Fleecejacke"}, {"text": "Eine leichte Regenjacke gegen Wind, Schauer oder Schnee.", "title": "Wasserdichte Jacke und Hose"}, {"text": "2 schnell trocknende Hosen, davon eine mit abnehmbaren Beinen für Tatopani.", "title": "Trekkinghosen"}, {"text": "Eine warme Mütze, ein Sonnenhut, dünne Innenhandschuhe und isolierte Handschuhe.", "title": "Mützen und Handschuhe"}, {"text": "Hält auf der Fahrt den Staub und auf dem Grat den kalten Wind ab.", "title": "Buff oder Halstuch"}, {"text": "Für die heißen Quellen von Tatopani an Tag 7.", "title": "Badebekleidung"}], "title": "Kleidung und Schichten"}, {"icon": "footprint", "items": [{"text": "Wasserdichte, knöchelhohe Schuhe, vor dem Trek eingelaufen.", "title": "Trekkingschuhe"}, {"text": "4–5 Paar Socken aus Wolle oder Kunstfaser.", "title": "Trekkingsocken"}, {"text": "Ein dickes Paar, das für die Nächte in Khopra trocken bleibt.", "title": "Warme Schlafsocken"}, {"text": "Nützlich für die Wanderung zum Khayer-See bei Neuschnee, meist von November bis März.", "title": "Grödel (Microspikes)"}], "title": "Schuhwerk und Fußpflege"}, {"icon": "backpack", "items": [{"text": "mit Regenhülle für Kleidungsschichten, Wasser und Snacks.", "title": "Tagesrucksack (25–35 l)"}, {"text": "wird von Ihrem Träger getragen (max. 15 kg).", "title": "Reisetasche (Duffel Bag)"}, {"text": "für den Abstieg und die Sonnenaufgangswanderung.", "title": "Trekkingstöcke und Stirnlampe"}, {"text": "Komfortbereich bis −10 °C (Sie können einen in Kathmandu leihen).", "title": "Schlafsack"}], "title": "Ausrüstung und Gepäck"}, {"icon": "medical_services", "items": [{"text": "Ihre üblichen Medikamente sowie alles, was Ihr Arzt für die Höhe empfiehlt.", "title": "Persönliche Medikamente"}, {"text": "Sonnencreme mit LSF 50 und Lippenpflege mit LSF.", "title": "Sonnenschutz"}, {"text": "Die meisten Lodges weiter oben stellen kein Toilettenpapier.", "title": "Toilettenpapier"}, {"text": "Eine Filterflasche oder Entkeimungstabletten zum Nachfüllen in den Lodges.", "title": "Wasseraufbereitung"}, {"text": "Klein und leicht, zum Waschen und für die heißen Quellen.", "title": "Schnell trocknendes Handtuch"}], "title": "Gesundheit, Hygiene und Wasser"}, {"icon": "description", "items": [{"text": "Bewahren Sie beides für die Kontrollpunkte der Genehmigungen im Tagesrucksack auf.", "title": "Reisepass und Visum"}, {"text": "2–4 Abzüge für Genehmigungen und Formalitäten.", "title": "Passfotos"}, {"text": "Eine ausgedruckte oder gespeicherte Kopie, die Deckung bis 5.000 m und Hubschrauberevakuierung nachweist.", "title": "Reiseversicherung"}, {"text": "Genug für Essen, Extras und Trinkgelder, in kleinen Scheinen. Nach Pokhara gibt es keine Geldautomaten mehr.", "title": "Bargeld in Rupien"}], "title": "Dokumente und Geld"}]'::jsonb, itinerary_intro = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Unser 8-tägiger Reiseverlauf für den Khopra Ridge beginnt und endet in Pokhara und steigt allmählich an, sodass Ihr Körper Zeit zur Anpassung hat, bevor Sie auf 3.660 m übernachten. Er beginnt im Gurung-Dorf Ghandruk, verlässt in Tadapani die belebten Wege für eine ruhige Waldroute über den Muldai-Aussichtspunkt zum Khopra Ridge und führt dann durch das Magar-Dorf Swanta hinab zu den heißen Quellen von Tatopani.", "type": "text"}]}]}'::jsonb, meal_trail_tips = '[{"text": "unbegrenzter Nachschlag von Reis, Linsen und Gemüsecurry. Der beste Treibstoff in der Höhe.", "title": "„Dal-Bhat-Power“"}, {"text": "Fleisch wird ungekühlt hinaufgetragen, daher empfehlen wir oberhalb von Lama Hotel vegetarisches Essen.", "title": "Weiter oben vegetarisch essen"}, {"text": "trinken Sie 3–4 Liter am Tag (Ingwer-Zitrone-Honig-Tee, Knoblauchsuppe, abgekochtes Wasser).", "title": "Genug trinken"}, {"text": "auf dem Weg gibt es keine Geldautomaten. Bringen Sie genug Nepalesische Rupien aus Kathmandu mit.", "title": "Bargeld ist König"}]'::jsonb, packing_heading = 'Packliste für den Khopra Danda Trek', pricing_heading = 'Gruppenpreise nach Gruppengröße', similar_heading = 'Ähnliche Treks in Nepal', overview_heading = 'Reiseüberblick und wichtige Eckdaten', elevation_heading = 'Höhenprofil des Khopra Danda Trek', itinerary_heading = 'Reiseverlauf Tag für Tag', route_map_heading = 'Routenkarte des Khopra Danda Trek', suitability_intro = 'Ein ehrlicher Blick darauf, was der Trek von Ihnen verlangt, damit Sie vor der Buchung entscheiden können.', highlights_heading = 'Höhepunkte des Khopra Ridge Trek und warum Sie ihn lieben werden', inclusions_heading = 'Was enthalten ist · Was nicht enthalten ist', suitability_points = '[{"text": "Sie sollten an zwei Tagen hintereinander 5 bis 6 Stunden mit einem Tagesrucksack wandern können. Wenn Sie das jetzt schaffen, sind Sie bereit.", "title": "Fitness:"}, {"text": "Trekkingerfahrung ist nicht nötig. Für viele unserer Khopra-Trekker ist es der erste Trek im Himalaya.", "title": "Trekkingerfahrung:"}, {"text": "Sie übernachten eine Nacht auf 3.660 m, was leichte Kopfschmerzen verursachen kann, aber selten ernsthafte Höhenkrankheit. Der Khayer-See auf 4.660 m ist eine größere Herausforderung, und Sie können ihn auslassen.", "title": "Höhe:"}, {"text": "Es gibt keine Gletscher oder technischen Passagen, aber lange Abstiege wie von Khopra nach Swanta belasten die Knie stark, daher helfen Trekkingstöcke sehr.", "title": "Wegbeschaffenheit:"}, {"text": "In Ghandruk und Tadapani, die an der belebten Route zum Annapurna Base Camp liegen, treffen Sie andere Trekker. Nach Tadapani wird der Weg ruhig, und an manchen Tagen sehen Sie bis Tatopani nur wenige andere Gruppen.", "title": "Andrang:"}, {"text": "Die Zimmer sind einfache Zweibettzimmer, weiter oben mit Gemeinschaftstoiletten, oft Hocktoiletten. Die Nächte in Khopra sind kalt, daher brauchen Sie einen warmen Schlafsack.", "title": "Lodges:"}]'::jsonb, meal_teahouse_notes = '[{"text": "frühstücken und essen Sie zu Abend, wo Sie übernachten. Nur so können die Lodges die Zimmerpreise niedrig halten.", "title": "Teehaus-Regel"}, {"text": "bestellen Sie das Abendessen gegen 17 Uhr und legen Sie die Frühstückszeit am Vorabend fest.", "title": "Früh bestellen"}, {"text": "Duschen, Aufladen und WLAN kosten weiter oben jeweils ein paar Dollar.", "title": "Kleine Extras"}]'::jsonb, suitability_heading = 'Ist dieser Trek das Richtige für Sie?' where trek_id = 'aee9f0bb-9000-4d3a-808a-50d1c7a3b43e' and locale = 'de';
update public.trek_day_translations set title = 'Von Pokhara nach Ghandruk, dann Trek nach Tadapani', subtitle = 'Eine kurze Fahrt, dann ein Aufstieg durch den Wald nach Tadapani', duration = '2–3 Std. Fahrt, 3–4 Std. Gehzeit', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Tag beginnt mit einer Fahrt von Pokhara nach Ghandruk (1.940 m) und endet mit einem Aufstieg durch den Wald nach Tadapani (2.630 m). Heute gewinnen Sie zu Fuß etwa 700 Höhenmeter, ein gleichmäßiger Anstieg, der Sie sanft in den Trek einführt.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Die Straße steigt über Lumle und Naudanda aus dem Tal von Pokhara hinauf, und an einem klaren Morgen sehen Sie hinter sich den Machhapuchhre und die Annapurna-Kette. Nach Nayapul folgt der Jeep dem Tal der Modi Khola und klettert über eine holprige Bergstraße nach Ghandruk. Die Fahrt dauert je nach Straßenzustand 2 bis 3 Stunden. Ihr Guide zeigt Ihre ACAP-Genehmigung unterwegs am Kontrollpunkt vor.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Ghandruk ist eines der größten Gurung-Dörfer der Annapurna-Region, mit Steinhäusern, Schieferdächern und gepflegten Steinwegen. Nehmen Sie sich vor dem Losgehen Zeit, den alten Ortskern zu erkunden. Wenn es geöffnet hat, besuchen Sie das kleine Gurung-Museum mit traditioneller Kleidung, Werkzeugen und Haushaltsgegenständen. Viele Männer aus dieser Gegend haben in den britischen und indischen Gurkha-Regimentern gedient.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Nach dem Mittagessen in Ghandruk steigt der Weg über Steinstufen durch das obere Dorf und die Felder und führt dann in den Wald. Der Großteil der Strecke verläuft durch Rhododendron-, Eichen- und Bambuswald, der im Frühling rot und rosa blüht. Der Anstieg ist eher gleichmäßig als steil und dauert 3 bis 4 Stunden. Gehen Sie in ruhigem Tempo und machen Sie Pausen, wann immer Sie sie brauchen.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Tadapani ist eine kleine Gruppe von Lodges auf einem bewaldeten Grat. Der Name bedeutet auf Nepali „fernes Wasser“. An einem klaren Abend leuchten im Sonnenuntergang Annapurna South, Hiunchuli und Machhapuchhre. Heute übernachten Sie in einer einfachen Lodge mit Zweibettzimmern und meist gemeinschaftlichen Bädern. Heiße Duschen gibt es in der Regel gegen eine kleine Gebühr.", "type": "text"}]}]}'::jsonb where day_id = 'bd35d85a-23e3-4462-b6cf-6bb1878cf7b4' and locale = 'de';
update public.trek_day_translations set title = 'Von Tadapani nach Dobato', subtitle = 'Verlassen Sie die Hauptwege und steigen Sie durch ruhigen Wald zum Grat bei Dobato auf', duration = '5–6 Std.', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Heute steigen Sie auf einem ruhigen Gemeindeweg durch einige der schönsten Rhododendronwälder der Annapurna-Region rund 800 Höhenmeter von Tadapani (2.630 m) nach Dobato (3.420 m) auf. Hier verlässt der Khopra Ridge Trek die belebte Route zum Annapurna Base Camp.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Von Tadapani führt der Weg nach Nordwesten und steigt allmählich durch dichten Rhododendron- und Eichenwald. Sie passieren die kleinen Lichtungen von Meshar Danda und Isharu, unterwegs gibt es nur sehr wenige Lodges und Menschen. Ihr Guide kennt den Weg gut, was hier wichtig ist, denn es gibt kaum Wegweiser und Abzweigungen können verwirren.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Im März und April färbt sich der Wald rot, rosa und weiß vom blühenden Rhododendron, Nepals Nationalblume. Im Herbst ist der Wald grün und die Luft klar. Achten Sie auf Languren in den Bäumen und halten Sie an den oberen Hängen Ausschau nach dem farbenprächtigen Danphe, Nepals Nationalvogel.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Der letzte Abschnitt steigt zwischen kleinen Hügeln und offenen Grashängen an. Mit zunehmender Höhe lichten sich die Bäume, und die Sicht öffnet sich zur Annapurna South und zum Machhapuchhre. Dobato ist eine kleine Gruppe einfacher Lodges auf einem offenen Grat, viel ruhiger als die Dörfer weiter unten.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Heute ist Ihre erste Nacht über 3.000 m, lassen Sie es nach der Ankunft also ruhig angehen. Trinken Sie viel Wasser, verzichten Sie auf Alkohol und sagen Sie Ihrem Guide, wenn Sie Kopfschmerzen, Schwindel oder Übelkeit spüren. In Dobato wird es nach Sonnenuntergang kalt, halten Sie Ihre warmen Schichten und Ihre Mütze also griffbereit. Gehen Sie früh schlafen, denn morgen beginnt der Tag vor der Morgendämmerung mit der Sonnenaufgangswanderung zum Muldai-Aussichtspunkt.", "type": "text"}]}]}'::jsonb where day_id = '308bd420-47ed-499e-a6f4-f8ad69119062' and locale = 'de';
update public.trek_day_translations set title = 'Sonnenaufgang am Poon Hill, dann Trek nach Chistibang', subtitle = 'Der Tag, an dem Sie die Menschenmengen hinter sich lassen', duration = '7–8 Std.', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der heutige Tag beginnt mit dem berühmtesten Sonnenaufgang der Annapurna-Region und endet auf einem ruhigen Waldweg, weit weg vom Trubel.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Wir verlassen die Lodge gegen 4:30 Uhr und steigen 45 bis 60 Minuten im Schein der Stirnlampe auf den Poon Hill (3.210 m). Mit der aufgehenden Sonne leuchten Dhaulagiri, Tukuche, Nilgiri, Annapurna South und Machhapuchhre einer nach dem anderen auf. Oben gibt es eine kleine Eintrittsgebühr, einen Aussichtsturm und einen Teestand. Es ist kalt und voll, doch dieser Blick gehört zu den schönsten in Nepal.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Nach dem Frühstück in Ghorepani gehen die meisten Trekker nach Osten Richtung Tadapani. Wir nehmen stattdessen den ruhigeren Gratweg. Er steigt über Deurali (3.090 m) und entlang des Grats nach Dobato (3.420 m), dem höchsten Punkt des Tages. Fitte Trekker mit Energiereserven können einen kurzen Abstecher zum Mulde-Aussichtspunkt oberhalb von Dobato machen und ein weiteres weites Bergpanorama genießen.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Von Dobato führt der Weg durch alten Wald hinab nach Chistibang (2.950 m), einem kleinen Lodge-Stopp auf einer von Bäumen umgebenen Lichtung.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "In diesen Teil des Waldes kommen weit weniger Trekker. Die Bäume sind älter, mit Moos und herabhängenden Flechten bewachsen, und der Weg ist schmaler. In schattigen Abschnitten können sich Reif und Eis im November und Dezember bis zum späten Vormittag halten.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Chistibang hat einfache Lodges mit Zweibettzimmern und Gemeinschaftstoiletten. Der Ofen im Speiseraum ist abends der wärmste Ort.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Das ist ein langer Tag. Füllen Sie Ihre Trinkflaschen in Ghorepani auf und nehmen Sie Snacks mit, denn zwischen Deurali und Chistibang gibt es nur wenige Teestopps.", "type": "text"}]}]}'::jsonb where day_id = 'd7f2f069-d79f-4a92-9245-fd712507e8de' and locale = 'de';
update public.trek_day_translations set title = 'Von Chistibang zum Khopra Danda', subtitle = 'Aus dem Wald hinauf auf den Grat', duration = '5–6 Std.', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Heute steigen Sie rund 700 Höhenmeter vom Wald bei Chistibang zum offenen Grat des Khopra Danda (3.660 m) auf. An diesen Tag erinnern sich die meisten unserer Trekker am liebsten.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Weg steigt den größten Teil des Vormittags stetig durch Rhododendron- und Birkenwald an. Je höher Sie kommen, desto kleiner und lichter werden die Bäume, und Sie sehen die ersten Hochweiden (Kharka), auf die die Hirten im Sommer ihre Büffel und Yaks bringen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Dann endet der Wald ganz plötzlich. Eben noch gehen Sie unter Bäumen, im nächsten Moment stehen Sie auf einem breiten, grasbewachsenen Grat mit völlig freier Sicht.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Im Westen öffnet sich die Schlucht der Kali Gandaki, eine der tiefsten der Welt. Direkt gegenüber füllt der Dhaulagiri (8.167 m) den Himmel. Im Norden stehen Tukuche Peak und Nilgiri, im Osten ragen Annapurna South und Annapurna I ganz nah auf. Vom Poon Hill aus sind diese Gipfel weit entfernt. In Khopra schlafen Sie mit Blick auf sie.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Lodge auf dem Grat gehört der Gemeinde. Komitees aus den Dörfern unterhalb führen sie, und die Einnahmen finanzieren örtliche Schulen und die Gesundheitsversorgung. Die Zimmer sind einfache Zweibettzimmer mit Gemeinschaftstoiletten. Strom kommt aus Solarenergie, daher ist das Aufladen nur eingeschränkt möglich.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Das ist Ihr höchster Übernachtungsort. Gehen Sie langsam, trinken Sie 3 bis 4 Liter Wasser und verzichten Sie heute Abend auf Alkohol. Die Nächte auf dem Grat fallen oft unter den Gefrierpunkt, halten Sie Daunenjacke und warme Mütze also griffbereit. Kälte entlädt Akkus schnell, bewahren Sie Handy und Kamera nachts deshalb im Schlafsack auf.", "type": "text"}]}]}'::jsonb where day_id = '1ac99888-7352-4305-8ffa-fb76ce0244ca' and locale = 'de';
update public.trek_day_translations set high_place = 'Khayer-See', title = 'Ruhetag in Khopra mit optionaler Wanderung zum Khayer-See', subtitle = 'Sie haben die Wahl: ein ganzer Tag auf dem Grat oder eine Wanderung zum heiligen See', duration = 'Ruhetag oder Wanderung (7–8 Std.)', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Heute ist ein freier Tag am Khopra Danda (3.660 m). Sie können ihn mit Ausruhen und Erkunden des Grats verbringen oder an einer optionalen Wanderung zum Khayer-See (4.660 m) teilnehmen. Sie entscheiden, und beides ist eine schöne Art, den Tag zu verbringen.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Die Wanderung zum Khayer-See ist kein Pflichtteil des Treks. Entscheiden Sie nach Ihrer Fitness, danach, wie viel Energie Sie nach vier Wandertagen haben, wie Sie in der Höhe geschlafen haben und was Sie sich von dem Tag wünschen. Viele unserer Trekker bleiben auf dem Grat und verpassen dabei nicht den Hauptgrund ihrer Reise: den Blick von Khopra auf den Dhaulagiri.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Besprechen Sie es am Vorabend mit Ihrem Guide. Sie können sich auch erst am Morgen entscheiden, wenn Sie wissen, wie es Ihnen geht. Ein ruhiger Tag auf dem Grat gibt Ihrem Körper Zeit, sich vor dem langen Abstieg zu erholen. Gehen Sie den Grat entlang, um Dhaulagiri und Annapurna South aus verschiedenen Blickwinkeln zu sehen, fotografieren Sie das wechselnde Licht, lesen Sie am Ofen im Speiseraum oder besuchen Sie die nahen Weiden der Hirten. Die Berge sehen jede Stunde anders aus, vom ersten rosa Licht bei Sonnenaufgang bis zum goldenen Schein bei Sonnenuntergang.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Die Wanderung beginnt gegen 5:30 Uhr und steigt über Hochweiden und felsiges Gelände rund 1.000 Höhenmeter zum See an. Sie ist nicht technisch, doch der stetige Anstieg in dünner Luft macht sie zur anstrengendsten Etappe des Treks. Die meisten Gruppen erreichen den See in 4 bis 5 Stunden und sind nach etwa 3 Stunden zurück in Khopra.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Khayer-See liegt in einem Felskessel am Fuß der Annapurna South. Er ist den hinduistischen Gemeinschaften in den Dörfern unterhalb heilig, und jedes Jahr im August steigen Pilger zum Vollmondfest hinauf. Den Rest des Jahres haben Sie ihn vielleicht fast für sich allein.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Unterwegs gibt es keine Teehäuser, daher bereitet die Lodge ein Lunchpaket vor. Nehmen Sie mindestens 2 Liter Wasser, eine warme Schicht, Handschuhe und eine Sonnenbrille mit.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Auch wenn Sie sich für die Wanderung entscheiden, kann Ihr Guide sie absagen oder umkehren, wenn das Wetter umschlägt, Neuschnee liegt oder jemand Anzeichen von Höhenkrankheit zeigt. Sicherheit geht immer vor. Wie auch immer Sie sich entscheiden, Sie übernachten heute wieder in der Lodge in Khopra.", "type": "text"}]}]}'::jsonb where day_id = 'a9154e9c-d1d1-4871-8736-e213088194e5' and locale = 'de';
update public.trek_day_translations set title = 'Vom Khopra Danda nach Paudwar', subtitle = 'Ein langer, steiler Abstieg vom Khopra Ridge zum traditionellen Magar-Dorf Paudwar', duration = '5–6 Stunden', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Heute steigen Sie rund 1.700 Höhenmeter vom Khopra Danda nach Paudwar ab, einem 300 Jahre alten Magar-Dorf auf der Westseite des Grats. Starten Sie früh und genießen Sie vor dem Frühstück in der Lodge einen letzten Sonnenaufgang über Dhaulagiri, Tukuche Peak, Nilgiri und Annapurna South.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Stehen Sie früh auf für Ihren letzten Sonnenaufgang auf dem Grat. An einem klaren Morgen trifft das erste Licht den Dhaulagiri (8.167 m) und breitet sich dann über Tukuche Peak, Nilgiri, Annapurna South und Hiunchuli aus. Tief unten bleibt die Schlucht der Kali Gandaki im Schatten. Dieser Blick ist der Hauptgrund, warum Trekker nach Khopra kommen, lassen Sie sich also Zeit, bevor Sie packen.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Der Weg verlässt die Lodge Richtung Westen, weg von der Route, auf der Sie heraufgekommen sind. Er führt fast durchgehend über gut angelegte Steinstufen stetig bergab, mit nur sehr wenigen flachen Abschnitten. Der erste Teil quert offenes Grasland, wo Sie vielleicht grasende Yaks oder Himalaya-Fasane entdecken. Weiter unten führt der Weg in den Wald, und die Luft wird spürbar wärmer.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Je näher Sie Paudwar kommen, desto mehr öffnet sich der Wald zu Terrassenfeldern mit Hirse, Mais und Kartoffeln. Sie kommen an kleinen Bauernhäusern vorbei und begegnen Dorfbewohnern, die auf den Feldern arbeiten oder Tiere hüten. Dieser Wechsel vom hohen Berggrat zu lebendigem Ackerland an einem einzigen Tag ist einer der Höhepunkte dieses Abschnitts.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Wenn Sie sich eingerichtet haben, verbringen Sie den Nachmittag mit einem Rundgang durchs Dorf. Besuchen Sie das kleine Magar-Museum und erfahren Sie mehr über Bräuche, Kleidung und landwirtschaftliche Geräte der Region. Schauen Sie bei der gemeinschaftlichen Käserei vorbei und probieren Sie den örtlichen Honig, beides bekannte Erzeugnisse der Gegend. Der Abend ist ruhig und entspannt, eine gute Gelegenheit, die Beine nach dem langen Abstieg auszuruhen.", "type": "text"}]}]}'::jsonb where day_id = 'e9194bd3-045e-4662-ae46-97217b2a2f7f' and locale = 'de';
update public.trek_day_translations set title = 'Von Paudwar nach Tatopani', subtitle = 'Eine leichte Wanderung bergab von Paudwar zu den natürlichen heißen Quellen von Tatopani', duration = '3–5 Stunden', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Heute wandern Sie von Paudwar (2.000 m) hinunter nach Tatopani (1.190 m), ein Abstieg von etwa 800 Höhenmetern, der 3–5 Stunden dauert. Nach dem langen Abstieg vom Khopra Danda gestern ist dies ein kürzerer und sanfterer Tag, mit Zeit für die heißen Quellen am Nachmittag.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Beginnen Sie den Tag mit einem gemütlichen Morgen im Dorf. An einem klaren Tag leuchten Dhaulagiri und Tukuche Peak bei Sonnenaufgang über den Hügeln. Nach dem Abstieg von Khopra können sich Ihre Beine steif anfühlen, ein paar Minuten sanftes Dehnen helfen.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Die Route verlässt Paudwar auf der Jeepstraße des Dorfes und führt stetig bergab ins Tal der Kali Gandaki. Wo Fußwege lange Kurven der Straße abschneiden, nimmt Ihr Guide diese Abkürzungen. Das Gehen ist leicht, doch der stetige Abstieg beansprucht trotzdem die Knie, benutzen Sie also weiter Ihre Trekkingstöcke. ", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Tatopani bedeutet auf Nepali „heißes Wasser“, und das Dorf ist nach seinen natürlichen heißen Quellen an der Kali Gandaki benannt. Es liegt an der alten Handelsroute zwischen Tibet und dem Tiefland und ist heute ein bekannter Halt am Annapurna Circuit. Verglichen mit den ruhigen Dörfern am Grat wirkt Tatopani belebt, mit Lodges, kleinen Läden und durchfahrenden Jeeps.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Verbringen Sie den Nachmittag in den Becken der heißen Quellen, der beste Weg, müde Muskeln nach mehreren Trekkingtagen zu entspannen. Die Becken kosten eine kleine Eintrittsgebühr, nehmen Sie also etwas Bargeld mit. Bringen Sie Badekleidung und ein schnell trocknendes Handtuch mit und tragen Sie keinen Silberschmuck, der im mineralhaltigen Wasser anlaufen kann. Dies ist Ihre letzte Nacht auf dem Trek, eine gute Gelegenheit, ihn mit Ihrem Guide und den Trägern zu feiern.", "type": "text"}]}]}'::jsonb where day_id = 'cdf00ca3-334d-4a73-8687-5da7fc624d4e' and locale = 'de';
update public.trek_day_translations set title = 'Fahrt von Tatopani nach Pokhara', subtitle = 'Entlang der Kali Gandaki zurück an den See', duration = '5–6 Std. Fahrt', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Heute fahren Sie von Tatopani zurück nach Pokhara (820 m) und folgen dabei größtenteils dem Fluss Kali Gandaki.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Die Straße führt entlang der Kali Gandaki nach Süden bis Beni, einer belebten Marktstadt, wo die Myagdi Khola in den Fluss mündet. Ab Beni folgt sie den Tälern von Modi und Kali Gandaki über Kusma zurück ins Tal von Pokhara. Der erste Abschnitt bis Beni ist stellenweise holprig, und die ganze Fahrt dauert je nach Straßenzustand und Verkehr etwa 5 bis 6 Stunden.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Sie kommen an kleinen Dörfern am Straßenrand, langen Hängebrücken und den tiefen, steilen Hängen des Kali-Gandaki-Tals vorbei. Machen Sie eine Teepause in Beni und werfen Sie einen letzten Blick zurück auf die Hügel, durch die Sie gerade gewandert sind.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Am Nachmittag erreichen wir Pokhara. Dann warten eine heiße Dusche, ein gutes Essen am Phewa-See und der Schlaf, den man nur nach einer Woche echten Wanderns findet. Wenn Sie länger bleiben möchten, organisieren wir gern einen Ruhetag, Paragliding, eine Bootsfahrt auf dem Phewa-See oder die Weiterreise nach Kathmandu oder Chitwan.", "type": "text"}, {"type": "hardBreak"}, {"type": "hardBreak"}, {"text": "Der erste Teil der Straße ist holprig, nehmen Sie also bei Bedarf Tabletten gegen Reiseübelkeit. Während des Monsuns und kurz danach können Erdrutsche die Fahrt verzögern, buchen Sie daher keinen Flug ab Pokhara am selben Abend.", "type": "text"}]}]}'::jsonb where day_id = '7ffa4961-aff4-40e4-bb5c-05b851ee1833' and locale = 'de';
update public.trek_translations set faqs = '[{"icon": "calendar_month", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Machapuchare aus nächster Nähe, der Aufstieg im Morgengrauen zum Aussichtspunkt am Mardi Himal Base Camp, moosbewachsene Rhododendronwälder, ein Wolkenmeer unterhalb des Grats und ruhige, familiengeführte Teehäuser.", "type": "text"}]}]}, "question": "Was sind die Höhepunkte des Mardi Himal Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Das Mardi Himal Base Camp auf etwa 4.500 m an Tag 6. Sie übernachten nie höher als im High Camp auf 3.580 m.", "type": "text"}]}]}, "question": "Was ist der höchste Punkt des Treks?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Mardi Himal Trek ist kürzer und ruhiger und führt über einen offenen Grat. Für das Annapurna Base Camp brauchen Sie 7–10 Tage, dafür gelangen Sie bis ins Innere des Sanctuary. Mit einer Woche Zeit wählen Sie den Mardi Himal Trek.", "type": "text"}]}]}, "question": "Mardi Himal oder Annapurna Base Camp?"}], "title": "Allgemeine Informationen"}, {"icon": "nordic_walking", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Unser Standard-Reiseverlauf dauert 7 Tage ab Pokhara und zurück, davon 5 Tage auf dem Trek. Für ein ruhigeres Tempo können wir einen Tag hinzufügen.", "type": "text"}]}]}, "question": "Wie lange dauert der Mardi Himal Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Fliegen oder fahren Sie von Kathmandu nach Pokhara, von dort sind es etwa eine Stunde mit dem Jeep bis Kande. Der Jeep von Siding zurück nach Pokhara ist inbegriffen.", "type": "text"}]}]}, "question": "Wie komme ich zum Ausgangspunkt?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja. Über Landruk und Ghandruk lässt er sich mit dem Poon Hill Trek oder dem Annapurna Base Camp zu einer Reise von 10–14 Tagen verbinden.", "type": "text"}]}]}, "question": "Kann ich den Mardi Himal Trek mit einem anderen Trek kombinieren?"}], "title": "Reiseverlauf und Dauer"}, {"icon": "fitness_center", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Mittelschwer, Stufe 3 von 5. Die Tagesetappen sind kurz, aber steil, und der Aufstieg im Morgengrauen vom High Camp ist der anstrengendste Teil.", "type": "text"}]}]}, "question": "Wie schwierig ist der Mardi Himal Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Treppensteigen, Wochenendwanderungen in Ihren Trekkingschuhen mit leichtem Rucksack und regelmäßiges Ausdauertraining 6–8 Wochen vor der Abreise.", "type": "text"}]}]}, "question": "Wie sollte ich trainieren?"}], "title": "Schwierigkeit und Fitness"}, {"icon": "medical_services", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Das Risiko ist gering, da Sie nie höher als auf 3.580 m übernachten. Trotzdem steigen wir in gleichmäßigem Tempo auf, messen täglich die Sauerstoffsättigung und kehren um, wenn ernste Symptome auftreten.", "type": "text"}]}]}, "question": "Bekomme ich am Mardi Himal Höhenkrankheit?"}], "title": "Höhe und Gesundheit"}]'::jsonb, summary = 'Eine ruhige Gratwanderung von Pokhara bis an den Fuß des Machapuchare, mit großen Annapurna-Blicken in einer Woche.', activity = 'Trekking / Wandern', category = 'Kurzer Grat-Trek', excluded = '[{"text": "bestellen Sie frei von der Speisekarte (etwa $20–30 pro Tag).", "title": "Mahlzeiten auf dem Trek"}, {"text": "Flug oder Touristenbus, den wir gern für Sie buchen.", "title": "Reise Kathmandu – Pokhara"}, {"text": "Pflicht, mit Deckung für Hubschrauberrettung.", "title": "Reiseversicherung"}, {"text": "bei der Ankunft am Flughafen.", "title": "Touristenvisum für Nepal"}, {"text": "heiße Duschen, Akkuladen und WLAN.", "title": "Extras in den Lodges"}]'::jsonb, headline = 'Mardi Himal Trek in 7 Tagen (Reiseverlauf, Kosten, kompletter Ratgeber)', included = '[{"text": "Pokhara – Kande und Siding – Pokhara im privaten Jeep.", "title": "Transport vor Ort"}, {"text": "in Erster Hilfe geschult, versichert und fair bezahlt.", "title": "Lizenzierter Guide und Träger"}, {"text": "5 Nächte auf dem Trek und 2 Hotelnächte in Pokhara.", "title": "Unterkunft in Teehäusern"}, {"text": "Genehmigung für das Annapurna Conservation Area (ACAP) sowie eine TIMS-Karte, wo Kontrollpunkte danach fragen.", "title": "Genehmigungen"}, {"text": "Pulsoximeter und Erste-Hilfe-Set.", "title": "Sicherheitsausrüstung"}, {"text": "Abholung und Rückbringung vom Flughafen oder Busbahnhof in Pokhara.", "title": "Transfers in Pokhara"}]'::jsonb, days_note = 'Hin und zurück ab Pokhara', seo_title = 'Mardi Himal Trek 7 Tage: Reiseverlauf, Kosten $540', transport = 'Jeep ab Pokhara', card_badge = 'Kurz und ruhig', highlights = '[{"text": "Vom High Camp aus füllt der Fishtail den Himmel, näher als fast überall sonst auf einem Teehaus-Trek.", "title": "Der Machapuchare aus nächster Nähe (6.993 m)"}, {"text": "Ein Aufstieg im Morgengrauen entlang des Grats zu einem Blick auf Mardi Himal, Machapuchare und Annapurna South.", "title": "Aussichtspunkt am Mardi Himal Base Camp (etwa 4.500 m)"}, {"text": "An klaren Morgen liegen die Täler um Pokhara unter den Wolken, während Sie darüber stehen.", "title": "Ein Wolkenmeer unterhalb des Grats"}, {"text": "Ruhiger Wald zwischen Pothana und Low Camp, im Frühling rot vor Blüten.", "title": "Moosbewachsener Rhododendronwald"}, {"text": "Kleine Familien-Teehäuser und weit weniger Trekker als auf den klassischen Annapurna-Routen.", "title": "Ruhiger als die Nachbarrouten"}, {"text": "Kurze Fahrten zum Ausgangspunkt und zurück, ganz ohne Inlandsflug.", "title": "Passt in eine Woche ab Pokhara"}]'::jsonb, know_intro = 'Wichtiges Wissen von unseren einheimischen Trekkingguides.', route_line = 'Übersicht der Route des Mardi Himal Trek (Pokhara – Kande – High Camp – Siding)', faq_heading = 'Häufige Fragen zum Mardi Himal Trek', guide_ratio = '1 : 4 + Träger', know_topics = '[{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Frühling (März bis Mai):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " blühende Rhododendren unterhalb des High Camp und warme Tage.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Herbst (Oktober bis November):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " trockene Wege und die klarste Sicht auf den Machapuchare.", "type": "text"}]}]}, "icon": "wb_twilight", "note": "Der Winter ist klar, doch Schnee kann den Grat oberhalb des High Camp unpassierbar machen. Der Monsun bringt Regen, Blutegel und verhangene Aussichten.", "title": "Beste Reisezeit und Wetterfenster", "photoId": null, "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Zimmer:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " kleine Zweibettzimmer mit Decken; legen Sie Ihren Schlafsack darüber.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "High Camp:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " nur wenige Lodges, daher sind die Zimmer einfach und im Oktober gut belegt.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "WLAN und Strom:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " in den meisten Lodges können Sie gegen eine kleine Gebühr Akkus laden; der Empfang ist lückenhaft.", "type": "text"}]}]}, "icon": "cottage", "note": "", "title": "Unterkunft und Ausstattung der Teehäuser", "photoId": null, "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Dal Bhat:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Reis, Linsensuppe, Gemüse und Pickles, mit kostenlosem Nachschlag.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Speisekarten unterwegs:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Porridge, tibetisches Brot, Nudeln, gebratener Reis und Ingwertee.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Trinken:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " trinken Sie 3–4 Liter am Tag und bereiten Sie Ihr Wasser auf; verzichten Sie auf Einwegplastik.", "type": "text"}]}]}, "icon": "soup_kitchen", "note": "", "title": "Essen, Ernährung und sicheres Trinkwasser", "photoId": null, "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Rettung:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " unser Büro koordiniert im Ernstfall eine Hubschrauberevakuierung mit Ihrer Versicherung.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Unterwegs:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Ihr Guide hat ein Erste-Hilfe-Set und ein Pulsoximeter dabei, und die Krankenhäuser in Pokhara sind nah.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Versicherung:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " eine Reiseversicherung mit Deckung für Notfallevakuierung ist für jeden Trekker Pflicht.", "type": "text"}]}]}, "icon": "emergency", "note": "", "title": "Notfallplan und Hubschrauberevakuierung", "photoId": null, "videoId": null}]'::jsonb, seo_keyword = 'Mardi Himal Trek', guides_intro = 'Lizenzierte Guides aus den Ausläufern des Annapurna, in Erster Hilfe geschult, die jede Teehaus-Familie am Grat kennen.', introduction = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Mardi Himal Trek folgt einem schmalen Grat von den Wäldern oberhalb von Pokhara direkt auf den Machapuchare (6.993 m) zu, den heiligen Fishtail, der für Bergsteiger gesperrt ist. Der Weg wurde erst in den 2010er-Jahren für Teehaus-Trekking erschlossen und ist daher im Vergleich zum Poon Hill oder Annapurna Base Camp noch ruhig.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Sie steigen durch moosbewachsenen Rhododendronwald zum Forest Camp und Low Camp, dann über die Baumgrenze zum High Camp und zum Aussichtspunkt am Mardi Himal Base Camp (etwa 4.500 m), umgeben von Annapurna South, Hiunchuli und Mardi Himal. Die Ausgangspunkte liegen eine Stunde von Pokhara entfernt, sodass der ganze Trek in eine Woche passt.", "type": "text"}]}]}'::jsonb, know_heading = 'Mardi Himal Trek: Reisezeit, Teehäuser und Sicherheit', packing_line = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Bewährte Ausrüstung für den Grat: von frostigen Morgen im High Camp bis zu warmen Tagen im Wald.", "type": "text"}]}]}'::jsonb, photo_badges = '[{"icon": "route", "tone": "brand", "label": "Nah an Pokhara"}, {"icon": "nordic_walking", "tone": "green", "label": "Mit einheimischem Guide"}, {"icon": "landscape", "tone": "brand", "label": "Blick auf den Machapuchare"}]'::jsonb, season_label = 'März–Mai, Okt.–Nov.', start_finish = 'Pokhara / Kande und Siding', accommodation = 'Teehaus und Hotel', daily_walking = '4 bis 7 Stunden am Tag', pricing_intro = 'Buchen Sie direkt bei unserem Team, ohne Zwischenhändler. Jeder Trek ist ein Privattrek, Sie wählen Ihr Startdatum also selbst.', similar_intro = 'Treks, die wir mit Ihnen planen und die von lokalen Guides geführt werden.', elevation_note = 'Sie übernachten nie höher als im High Camp auf 3.580 m und wandern nur tagsüber zum Base Camp.', guides_heading = 'Lernen Sie Ihren Trekkingguide kennen', packing_groups = '[{"icon": "apparel", "items": [{"text": "2–3 Ober- und Unterteile aus Merino oder Kunstfaser.", "title": "Basisschichten"}, {"text": "ein warmes Fleece oder eine Softshelljacke.", "title": "Fleece als Mittelschicht"}, {"text": "ausgelegt für etwa −10 °C, für den Aufstieg im Morgengrauen vom High Camp.", "title": "Daunenjacke"}, {"text": "Jacke und Hose gegen Regen und Wind auf dem Grat.", "title": "Wasserdichte Außenschicht"}], "title": "Kleidung und Schichten"}, {"icon": "footprint", "items": [{"text": "wasserdicht, eingelaufen, mit gutem Grip für steile Stufen.", "title": "Trekkingschuhe"}, {"text": "leichte Turnschuhe oder Sandalen für das Teehaus.", "title": "Hüttenschuhe"}, {"text": "4–5 Paar gepolsterte Trekkingsocken.", "title": "Socken"}, {"text": "nützlich im Winter oder frühen Frühling, wenn der obere Grat vereist ist.", "title": "Grödel (Microspikes)"}], "title": "Schuhwerk und Fußpflege"}, {"icon": "backpack", "items": [{"text": "mit Regenhülle für Kleidungsschichten, Wasser und Snacks.", "title": "Tagesrucksack (25–35 l)"}, {"text": "wird von Ihrem Träger getragen (max. 15 kg).", "title": "Reisetasche (Duffel Bag)"}, {"text": "Komfortbereich bis −10 °C (Sie können einen in Pokhara leihen).", "title": "Schlafsack"}, {"text": "für den langen Abstieg und die Wanderung im Morgengrauen.", "title": "Trekkingstöcke und Stirnlampe"}], "title": "Ausrüstung und Gepäck"}, {"icon": "medical_services", "items": [{"text": "Tabletten oder ein UV-Stift sowie zwei 1-Liter-Flaschen.", "title": "Wasseraufbereitung"}, {"text": "Blasenpflaster, Schmerzmittel, Elektrolytpulver.", "title": "Reiseapotheke"}, {"text": "Sonnencreme mit LSF 50, Sonnenbrille und Lippenpflege.", "title": "Sonnenschutz"}, {"text": "Feuchttücher, Handdesinfektionsmittel und ein schnell trocknendes Handtuch.", "title": "Hygiene"}], "title": "Gesundheit, Hygiene und Wasser"}]'::jsonb, itinerary_intro = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Sieben entspannte Tage von Pokhara bis an den Fuß des Machapuchare und zurück. Sie fahren nach Kande, wandern über Pothana und durch den Rhododendronwald hinauf zum Low Camp und High Camp, steigen im Morgengrauen zum Aussichtspunkt am Mardi Himal Base Camp und kehren über das Dorf Siding zur Straße zurück. Jede Nacht auf dem Trek verbringen Sie in einem familiengeführten Teehaus.", "type": "text"}]}]}'::jsonb, meal_trail_tips = '[{"text": "unbegrenzter Nachschlag von Reis, Linsen und Gemüsecurry. Der beste Treibstoff für den Grat.", "title": "„Dal-Bhat-Power“"}, {"text": "Fleisch wird ungekühlt hinaufgetragen, daher empfehlen wir oberhalb des Forest Camp vegetarisches Essen.", "title": "Weiter oben vegetarisch essen"}, {"text": "trinken Sie 3–4 Liter am Tag (Ingwer-Zitrone-Honig-Tee, Knoblauchsuppe, abgekochtes Wasser).", "title": "Genug trinken"}, {"text": "auf dem Weg gibt es keine Geldautomaten. Bringen Sie genug Nepalesische Rupien aus Pokhara mit.", "title": "Bargeld ist König"}]'::jsonb, packing_heading = 'Packliste für den Mardi Himal Trek', pricing_heading = 'Gruppenpreise nach Gruppengröße', seo_description = 'Privater Mardi Himal Trek in 7 Tagen ab Pokhara mit lokalem Guide: ruhige Gratwanderung zum Base Camp (4.500 m) am Machapuchare, Nächte im Teehaus.', similar_heading = 'Ähnliche Treks in Nepal', elevation_heading = 'Route und Höhenprofil', itinerary_heading = 'Reiseverlauf Tag für Tag', route_map_heading = 'Routenkarte des Mardi Himal Trek', suitability_intro = 'Eine ehrliche Checkliste unserer Guides, die Ihnen hilft zu entscheiden, ob der Mardi-Himal-Grat zu Ihnen passt.', highlights_heading = 'Höhepunkte des Mardi Himal Trek und warum Sie ihn lieben werden', inclusions_heading = 'Was enthalten ist · Was nicht enthalten ist', suitability_points = '[{"text": "4 bis 7 Stunden Gehzeit am Tag mit steilen Steinstufen und Anstiegen am Grat. Eine mittlere Fitness reicht aus.", "title": "Körperliche Anforderungen und Fitness"}, {"text": "Sie übernachten nie höher als im High Camp (3.580 m) und wandern tagsüber auf etwa 4.500 m. Für alle mit guter Gesundheit geeignet.", "title": "Höhe und Akklimatisierung"}, {"text": "Keine. Der obere Grat ist schmal und kann im Winter vereist sein, erfordert aber weder Seile noch Kletterausrüstung.", "title": "Erforderliche Technik"}, {"text": "Kleine Familien-Teehäuser mit einfachen Zweibettzimmern. Die Zimmer im High Camp sind einfach und im Oktober schnell ausgebucht.", "title": "Komfort unterwegs und Unterkunft"}, {"text": "Stellen Sie sich am Tag zum Base Camp auf einen frühen, kalten Start ein und auf Wolken, die die Aussicht verdecken können.", "title": "Mentale Belastbarkeit"}, {"text": "Bei Herz- oder Lungenerkrankungen oder schwerem Asthma sprechen Sie vor der Buchung mit Ihrem Arzt.", "title": "Gesundheitliche Voraussetzungen"}]'::jsonb, meal_teahouse_notes = '[{"text": "frühstücken und essen Sie zu Abend, wo Sie übernachten. Nur so können die Lodges die Zimmerpreise niedrig halten.", "title": "Teehaus-Regel"}, {"text": "bestellen Sie das Abendessen gegen 17 Uhr; im High Camp gibt es am Tag zum Base Camp früh Frühstück.", "title": "Früh bestellen"}, {"text": "Duschen, Aufladen und WLAN kosten weiter oben jeweils ein paar Dollar.", "title": "Kleine Extras"}]'::jsonb, suitability_heading = 'Ist dieser Trek das Richtige für Sie?' where trek_id = '281b116d-69c3-43b6-9b20-edf8bc6219a7' and locale = 'de';
update public.trek_day_translations set title = 'Ankunft in Pokhara (822 m), Begrüßung und Reisebesprechung', subtitle = 'Hotel am See · Ausrüstungscheck', duration = 'Ankunft', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Fliegen oder fahren Sie von Kathmandu nach Pokhara. Am Abend prüft Ihr Guide Ihre Ausrüstung und Genehmigungen und bespricht mit Ihnen die Route.", "type": "text"}]}]}'::jsonb where day_id = 'f6840c15-4f01-4c48-85fd-0e0e8c44ebce' and locale = 'de';
update public.trek_day_translations set title = 'Fahrt nach Kande, Trek nach Pothana (1.890 m)', subtitle = 'Australian Camp · Erste Blicke auf die Annapurnas', duration = '1 Std. Fahrt · 3–4 Std.', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Eine kurze Fahrt nach Kande, dann ein gleichmäßiger Aufstieg durch Dörfer und Wald zum Australian Camp und weiter nach Pothana, mit Annapurna South und Machapuchare vor Augen.", "type": "text"}]}]}'::jsonb where day_id = '817ee26e-773c-4fc1-919b-87a890b0c535' and locale = 'de';
update public.trek_day_translations set title = 'Von Pothana zum Forest Camp (2.550 m)', subtitle = 'Rhododendron- und Eichenwald · Ruhiger Weg', duration = '5–6 Std.', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Verlassen Sie in Deurali den Hauptweg im Annapurna-Gebiet und folgen Sie dem ruhigen Gratpfad durch dichten Rhododendron- und Eichenwald zum Forest Camp.", "type": "text"}]}]}'::jsonb where day_id = 'd69ab908-dd7f-418e-b4ac-39160d6078cf' and locale = 'de';
update public.trek_day_translations set title = 'Vom Forest Camp zum Low Camp (2.970 m)', subtitle = 'Moosiger Wald · Der Machapuchare taucht auf', duration = '3–4 Std.', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ein kürzerer Tag durch moosbewachsenen Wald zum Low Camp, wo der Machapuchare direkt über den Teehäusern aufragt. Ein guter Tag, um sich auszuruhen und an die Höhe zu gewöhnen.", "type": "text"}]}]}'::jsonb where day_id = 'a48d4804-639a-4113-9933-de2c543ef66f' and locale = 'de';
update public.trek_day_translations set title = 'Vom Low Camp zum High Camp (3.580 m) über Badal Danda', subtitle = 'Über der Baumgrenze · Sonnenuntergang am Fishtail', duration = '4–5 Std.', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Steigen Sie über die Baumgrenze nach Badal Danda, dem „Wolkengrat“, und weiter über offenes Grasland zum High Camp, um den Sonnenuntergang an Machapuchare und Annapurna South zu erleben.", "type": "text"}]}]}'::jsonb where day_id = '7a904171-ecbe-4172-88a1-bbc5cc254193' and locale = 'de';
update public.trek_day_translations set title = 'Wanderung im Morgengrauen zum Aussichtspunkt am Mardi Himal Base Camp (etwa 4.500 m), Abstieg zum Low Camp', subtitle = 'Der Höhepunkt des Treks · Gratwanderung bei Sonnenaufgang', duration = '8–9 Std.', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ein früher Aufbruch über den Grat zum Aussichtspunkt und weiter zum Base Camp, umgeben von Mardi Himal, Machapuchare und Annapurna South. Zum Mittagessen zurück ins High Camp, dann hinab zum Low Camp.", "type": "text"}]}]}'::jsonb where day_id = 'e2fb6399-54d1-4532-aa56-699839240c30' and locale = 'de';
update public.trek_day_translations set title = 'Vom Low Camp nach Siding (1.750 m), Rückfahrt nach Pokhara (822 m)', subtitle = 'Abstieg durch die Dörfer · Feiern mit Ihrem Team', duration = '4–5 Std. · 2–3 Std. Fahrt', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ein langer Abstieg durch Wald und Terrassenfelder ins Dorf Siding, dann mit dem Jeep zurück nach Pokhara zu einem Abendessen am See mit Ihrem Guide.", "type": "text"}]}]}'::jsonb where day_id = '539b18dc-5501-4d6b-b4e5-9048ad28dff7' and locale = 'de';
update public.trek_day_translations set title = 'Vom Low Camp nach Siding (1.750 m), Rückfahrt nach Pokhara (822 m)', subtitle = 'Vom Low Camp nach Siding (1.750 m), Rückfahrt nach Pokhara (822 m)', duration = '4–5 Std. · 2–3 Std. Fahrt', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "4–5 Std. · 2–3 Std. Fahrt, Testdaten mit Bild ", "type": "text"}, {"type": "hardBreak"}]}, {"type": "image", "attrs": {"alt": "arenanp.com", "width": 878, "height": 892, "photoId": "8f28700d-67a8-4b75-b980-c71617aa9477", "variantWidths": [400, 800, 878]}}, {"type": "paragraph"}]}'::jsonb where day_id = 'd9456878-c10c-422c-a652-f288721ae66f' and locale = 'de';
update public.trek_group_price_translations set label = '1 Person (allein)', short_label = '1 Pers.', team = 'Privater Guide + privater Träger' where price_id = '30c214c9-7926-415b-8706-915a517adc8f' and locale = 'de';
update public.trek_group_price_translations set label = '2 Personen', short_label = '2 Pers.', team = 'Guide + 1 Träger' where price_id = 'f221c12c-fa48-4d6d-96a7-f4f39fb57a62' and locale = 'de';
update public.trek_group_price_translations set label = '3–5 Personen', short_label = '3–5 Pers.', team = 'Hauptguide + Assistent + Träger' where price_id = 'f2f8ffa7-2857-4e21-9ee5-7dabd049de46' and locale = 'de';
update public.trek_group_price_translations set label = '6–10 Personen', team = 'Hauptguide + 2 Assistenten + Träger' where price_id = '7cd01d48-7ba4-4dd0-8e8d-c20d1739b8e7' and locale = 'de';
update public.trek_group_price_translations set label = '11+ Personen', short_label = '11+ Pers.', team = 'Komplettes Trekkingteam' where price_id = 'cc0b0a0a-a161-4e56-99b7-d8988e35f11c' and locale = 'de';
update public.trek_translations set faqs = '[{"icon": "info", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Nar Phu Valley Trek ist ein 10-tägiger Trek zu zwei abgelegenen tibetisch-buddhistischen Dörfern, Nar (4.110 m) und Phu (4.080 m), im Distrikt Manang. Er verlässt den Annapurna Circuit in Koto, steigt durch die Schlucht des Nar Khola auf und überquert den Kang La Pass (5.320 m) nach Ngawal. Da es sich um ein Sperrgebiet handelt, kommen nur wenige Trekker hierher.", "type": "text"}]}]}, "question": "Was ist der Nar Phu Valley Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Nar Phu liegt im Distrikt Manang in der Provinz Gandaki im nördlichen Zentralnepal. Es ist ein Seitental des Marsyangdi-Flusses, nördlich des Annapurna-Massivs und nahe der Grenze zu Tibet, innerhalb des Annapurna Conservation Area.", "type": "text"}]}]}, "question": "Wo liegt das Nar Phu Valley?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Nar Phu Trek dauert 10 Tage ab und bis Kathmandu, davon 7 Tage zu Fuß. Sie gehen 87,4 km in rund 41,5 Stunden, einschließlich der Wanderung zum Himlung-Basislager. Mit Thorong La und dem Annapurna Circuit sind es etwa 15 Tage.", "type": "text"}]}]}, "question": "Wie lange dauert der Nar Phu Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Kang La Pass ist 5.320 m (17.454 ft) hoch und damit der höchste Punkt des Treks. Am höchsten übernachten Sie in Nar auf 4.110 m.", "type": "text"}]}]}, "question": "Wie hoch ist der Kang La Pass?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Nar Phu liegt nahe der Grenze zu Tibet, daher hielt die Regierung das Tal bis 2003 für ausländische Trekker geschlossen. Es ist bis heute ein Sperrgebiet, weshalb Sie eine Sondergenehmigung und einen lizenzierten Guide brauchen.", "type": "text"}]}]}, "question": "Warum war Nar Phu für Trekker gesperrt?"}], "title": "Grundlagen zum Trek"}, {"icon": "description", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Sie können Nar Phu allein trekken, aber nie ohne Guide. Seit dem 22. März 2026 kann auch ein einzelner Trekker die Sperrgebietsgenehmigung erhalten. Die Genehmigung wird nur über eine registrierte Agentur ausgestellt, und ein lizenzierter Guide muss Sie die ganze Zeit begleiten.", "type": "text"}]}]}, "question": "Kann man Nar Phu allein oder ohne Guide trekken?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die Sperrgebietsgenehmigung kostet von September bis November US$100 für die ersten 7 Tage und von Dezember bis August US$75, dazu US$15 für jeden weiteren Tag. Die ACAP kostet NPR 3.000 für Ausländer und NPR 1.000 für Staatsangehörige der SAARC-Länder. Beide Genehmigungen sind in unserem Trekpreis enthalten.", "type": "text"}]}]}, "question": "Was kosten die Genehmigungen für Nar Phu?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Nein. Die Sperrgebietsgenehmigung für Nar Phu und die ACAP sind die einzigen Genehmigungen, die Sie brauchen.", "type": "text"}]}]}, "question": "Braucht man für Nar Phu eine TIMS-Karte?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ihr Guide zeigt Ihre Genehmigungen am Polizei- und ACAP-Kontrollposten in Koto vor, bevor Sie das Tal betreten. ACAP-Beamte können sie in Dharapani oder Manang erneut prüfen, tragen Sie Ihren Reisepass und Kopien also immer bei sich.", "type": "text"}]}]}, "question": "Wo werden die Genehmigungen kontrolliert?"}], "title": "Genehmigungen und Guide"}, {"icon": "wb_twilight", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die besten Monate sind April–Mai und Oktober–November, wenn der Himmel klar und der Kang La meist offen ist. Auch März, September sowie Anfang bis Mitte Dezember sind gut. Meiden Sie Ende Dezember bis Februar und Juni bis August.", "type": "text"}]}]}, "question": "Wann ist die beste Reisezeit für den Nar Phu Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja, Anfang bis Mitte Dezember ist eine gute Zeit für klare Sicht und ruhige Wege. Die Nächte in Nar und Phu sinken jedoch auf etwa −10 °C, Wasser gefriert, und am Kang La fällt viel Schnee. Ab Mitte bis Ende Dezember kann Schnee den Pass versperren, und viele Dorfbewohner ziehen in die Städte.", "type": "text"}]}]}, "question": "Kann man den Nar Phu Trek im Dezember machen?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "In Phu sinken die Nachttemperaturen im Oktober auf etwa −3 °C, im November auf −7 °C und im Dezember auf −10 °C. Tagsüber werden es im Oktober etwa 9 °C und im November 6 °C. Das sind Schätzwerte, packen Sie also für kältere Temperaturen.", "type": "text"}]}]}, "question": "Wie kalt wird es in Phu und Nar?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Wir raten davon ab. Das obere Tal liegt im Regenschatten und bekommt nur leichten Regen, doch weiter unten bringt starker Regen Erdrutsche und Blutegel und blockiert oft die Straße nach Koto.", "type": "text"}]}]}, "question": "Kann man Nar Phu während des Monsuns trekken?"}], "title": "Reisezeit und Wetter"}, {"icon": "medical_services", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Nar Phu Trek ist anspruchsvoll (Stufe 4 von 5). Schwierig sind die drei Nächte über 4.000 m, der 10-stündige Tag über den Kang La und der abgelegene Weg. Sie brauchen eine gute Kondition und etwas Trekkingerfahrung, aber keine Kletterkenntnisse.", "type": "text"}]}]}, "question": "Wie schwer ist der Nar Phu Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Für die meisten Trekker ja, obwohl der Kang La (5.320 m) niedriger ist als der Thorong La (5.416 m). Bei Nar Phu verbringen Sie mehr Nächte über 4.000 m, die Lodges sind einfacher, der Weg ist abgelegener und der Abstieg vom Pass steiler.", "type": "text"}]}]}, "question": "Ist Nar Phu schwerer als der Annapurna Circuit?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Steigen Sie langsam auf, trinken Sie 3–4 Liter Wasser am Tag, verzichten Sie auf Alkohol und nutzen Sie den Akklimatisierungstag in Phu. Unser Reiseverlauf teilt die Strecke von Meta nach Phu auf zwei Tage auf und sieht zwei Nächte in Phu vor. Wenn Sie Kopfschmerzen, Übelkeit oder Schwindel spüren, sagen Sie es sofort Ihrem Guide.", "type": "text"}]}]}, "question": "Wie vermeidet man Höhenkrankheit am Nar Phu Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ihr Guide bringt Sie hinunter in ein tiefer gelegenes Dorf, etwa von Nar nach Nar Phedi oder von Phu in Richtung Meta. Phu und Nar haben nur einfache Gesundheitsposten. In ernsten Fällen organisieren wir eine Hubschrauberrettung, die etwa US$5.000–7.000 kostet, Ihre Versicherung muss sie also abdecken.", "type": "text"}]}]}, "question": "Was passiert, wenn jemand unterwegs krank wird?"}], "title": "Schwierigkeit und Gesundheit"}, {"icon": "route", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die Reise beginnt und endet in Kathmandu. An Tag 1 fahren Sie nach Koto (2.620 m), bis Tag 8 wandern Sie nach Ngawal (3.650 m) und fahren dann an Tag 9 und 10 über Ngadi zurück nach Kathmandu.", "type": "text"}]}]}, "question": "Wo beginnt und endet der Nar Phu Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Wir gehen auf demselben Weg zurück: von Nar nach Nar Phedi, hinauf zur Abzweigung oberhalb von Meta und dann über Meta nach Koto. Das dauert 2 Tage und rund 23 km, ab Koto geht es mit dem Fahrzeug weiter. So geschah es im Oktober 2026, als Unwetter den Pass vom 7. bis 15. Oktober sperrten.", "type": "text"}]}]}, "question": "Was passiert, wenn der Kang La gesperrt ist?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja. Nach dem Kang La können Sie von Ngawal nach Manang wandern und über den Thorong La (5.416 m) nach Muktinath gehen. Das dauert etwa 5 Tage länger, und für den zweiten Pass sind Sie dann bereits gut akklimatisiert.", "type": "text"}]}]}, "question": "Kann man Nar Phu mit dem Annapurna Circuit verbinden?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Tag über den Kang La dauert etwa 10 Stunden und umfasst 15,6 km. Sie steigen etwa 6 Stunden von Nar zum Pass auf und etwa 4 Stunden nach Ngawal ab. Wir brechen gegen 5:00 Uhr auf.", "type": "text"}]}]}, "question": "Wie lang ist der Tag über den Kang La?"}], "title": "Route und Reiseverlauf"}, {"icon": "cottage", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Sie übernachten in einfachen Teehäusern und bei Gastfamilien, dazu eine Nacht im Gästehaus der Satek Gompa in Nar Phedi. Die besten Zimmer gibt es in Koto und Ngawal. In Phu und Nar wohnen Sie in traditionellen Steinhäusern mit wenigen Zimmern.", "type": "text"}]}]}, "question": "Wie übernachtet man am Nar Phu Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Eigene Badezimmer gibt es nur in einigen Lodges in Koto, Ngawal und Ngadi. Von Meta bis Nar sind die Toiletten gemeinschaftlich, in Kyang gibt es keine Zimmer mit eigener Toilette, und die Dusche in Meta, Phu und Nar ist ein Eimer heißes Wasser gegen Gebühr.", "type": "text"}]}]}, "question": "Gibt es heiße Duschen und eigene Badezimmer?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Das Essen kostet etwa US$15–25 am Tag. Ein Dal Bhat kostet etwa NPR 700, Momos etwa NPR 800. Ihre gesamten Tageskosten mit den Leistungen der Lodges liegen bei NPR 2.500–4.500.", "type": "text"}]}]}, "question": "Was kostet das Essen am Nar Phu Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Nach Besisahar gibt es keinen Geldautomaten, bringen Sie also Ihr ganzes Bargeld mit. Auf dem Weg gibt es keinen Handyempfang, in Dörfern wie Chyakhu, Kyang, Phu und Nar nur ein schwaches, unzuverlässiges Signal. In Koto ist das WLAN langsam, in einigen Lodges in Ngawal kostet es etwa NPR 100.", "type": "text"}]}]}, "question": "Gibt es Handyempfang, WLAN oder einen Geldautomaten?"}], "title": "Teehäuser, Essen und Erreichbarkeit"}, {"icon": "payments", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Das Paket kostet je nach Gruppengröße US$490–855 pro Person. Die beliebteste Gruppengröße, 3–5 Trekker, kostet US$570 pro Person. Rechnen Sie zusätzlich mit NPR 2.500–4.500 am Tag für Ausgaben unterwegs.", "type": "text"}]}]}, "question": "Was kostet der Nar Phu Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Nicht enthalten sind Mahlzeiten, ein Träger, Versicherung, heiße Duschen, Getränke, Telefonate, Trinkgelder, internationale Bankgebühren sowie zusätzliche Nächte durch Änderungen am Plan. Enthalten sind Genehmigungen, Transport, Ihr Guide und die Zimmer in den Teehäusern.", "type": "text"}]}]}, "question": "Was ist im Preis nicht enthalten?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Rechnen Sie mit etwa US$15 am Tag für den Guide, die sich die ganze Gruppe teilt, und etwa US$12 am Tag für jeden Träger. Die meisten Gruppen geben das Trinkgeld am Ende des Treks.", "type": "text"}]}]}, "question": "Wie viel Trinkgeld gibt man am Nar Phu Trek?"}], "title": "Kosten und Buchung"}, {"icon": "backpack", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Nehmen Sie eine Daunenjacke, einen Vier-Jahreszeiten-Schlafsack, eingelaufene Schuhe, zwei Trekkingstöcke, eine Stirnlampe, eine Powerbank und von November bis April Grödel mit. Packen Sie Wasseraufbereitung, Sonnenschutz und Ihr ganzes Bargeld ein.", "type": "text"}]}]}, "question": "Was sollte man für den Nar Phu Trek einpacken?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die Menschen in Nar und Phu folgen dem tibetischen Buddhismus. Gehen Sie im Uhrzeigersinn um Manimauern und Chörten, fragen Sie, bevor Sie Menschen oder das Innere von Klöstern fotografieren, kleiden Sie sich zurückhaltend und ziehen Sie die Schuhe aus, bevor Sie eine Gompa betreten.", "type": "text"}]}]}, "question": "Was sollte man über die örtliche Kultur wissen?"}], "title": "Ausrüstung und Kultur"}]'::jsonb, name = 'Nar Phu Valley Trek in 10 Tagen', summary = 'Ein 10-tägiger Trek ins Sperrgebiet zu den tibetisch-buddhistischen Dörfern Nar und Phu in Manang, mit Überquerung des Kang La Pass (5.320 m) zum Annapurna Circuit.', activity = 'Trekking / Wandern', category = 'Talwanderung im Sperrgebiet', excluded = '[{"text": "Gegen Aufpreis können Sie einen Träger buchen; was Träger üblicherweise bekommen, steht im Abschnitt zum Trinkgeld.", "title": "Träger"}, {"text": "Essen und Getränke unterwegs bezahlen Sie selbst.", "title": "Mahlzeiten und Getränke"}, {"text": "Ein privater Jeep oder ein privates Fahrzeug statt der im Plan vorgesehenen öffentlichen Fahrzeuge und Jeeps.", "title": "Privater Jeep oder Transport"}, {"text": "Ihre eigene Reiseversicherung für große Höhen.", "title": "Versicherung"}, {"text": "Heiße Duschen, Telefonate, Aufladen, Snacks und Souvenirs; internationale Bankgebühren.", "title": "Persönliche Ausgaben"}, {"text": "Zusätzliche Nächte durch Wetter, Straßensperren oder andere Änderungen am Plan sowie Trinkgelder für Ihr Trekkingteam.", "title": "Änderungen"}]'::jsonb, headline = 'Nar Phu Trek – 10 Tage über den Kang La Pass', included = '[{"text": "Öffentliches Fahrzeug von Kathmandu nach Besisahar, öffentlicher Jeep von Besisahar nach Koto, öffentlicher Jeep von Ngawal nach Ngadi und öffentliches Fahrzeug von Ngadi zurück nach Kathmandu.", "title": "Transport"}, {"text": "Ein staatlich geprüfter, Englisch sprechender Trekkingguide. Gruppen ab 7 Personen bekommen einen zweiten Guide.", "title": "Guide"}, {"text": "Die Sperrgebietsgenehmigung für Nar Phu und die Genehmigung für das Annapurna Conservation Area (ACAP), einschließlich staatlicher Gebühren.", "title": "Genehmigungen"}, {"text": "Jede Nacht ein Zimmer im besten verfügbaren Teehaus oder Homestay.", "title": "Unterkunft"}, {"text": "Ein Erste-Hilfe-Set und eine von uns organisierte Hubschrauberrettung, sobald Sie uns die Daten Ihrer Höhenversicherung geschickt haben.", "title": "Sicherheit"}, {"text": "Eine Trinkflasche, die Sie abends mit heißem Wasser füllen können, eine Trekkingkarte, ein Sonnenhut und eine Urkunde über den abgeschlossenen Trek.", "title": "Extras"}]'::jsonb, days_note = 'Ab/bis Kathmandu', seo_title = 'Nar Phu Trek 10 Tage: Reiseverlauf, Kosten und Tipps', transport = 'Öffentliches Fahrzeug und Jeep über Besisahar', card_badge = 'Verborgenes Tal', highlights = '[{"text": "Phu (4.080 m) thront wie eine Festung auf einem hohen Hügel über dem Phu Khola, mit der Yul Gompa ganz oben und dem Kloster Tashi Lakhang (4.150 m) 20 Gehminuten entfernt.", "title": "Das Dorf Phu und das Kloster Tashi Lakhang"}, {"text": "Von den Gebetsfahnen auf dem Pass blicken Sie über das Manang-Tal zur Annapurna II (7.937 m), zur Annapurna III und IV, zum Gangapurna und zum Kang Guru (6.981 m).", "title": "Kang La Pass (5.320 m)"}, {"text": "Am Ruhetag in Phu können Sie nah an den Himlung Himal (7.126 m), den Nemjung (7.140 m) und die Gletscher Himlung und Pangri heranwandern.", "title": "Himlung-Basislager (4.900 m)"}, {"text": "Nar (4.110 m) ist das größte Dorf im Tal, mit Steinhäusern, bewirtschafteten Terrassen und drei Nyingmapa-Klöstern in der Nähe.", "title": "Das Dorf Nar"}, {"text": "Der Weg führt durch Kiefernwald, vorbei an Wasserfällen und Felswänden, dann durch einen engen Canyon bis zum steinernen Tor von Phu auf 4.010 m.", "title": "Die Schlucht des Nar Khola und das Phu-Tor"}, {"text": "In Nar Phedi übernachten Sie im Gästehaus von Sartek Thrangu Choepel Ling, einem bewohnten Kloster mit sauberen Zimmern.", "title": "Eine Nacht in der Satek Gompa"}]'::jsonb, know_intro = 'Die häufigsten praktischen Fragen zur Planung von Nar Phu: wann Sie gehen sollten, wo Sie schlafen, was Sie essen, wie Sie in der Höhe sicher bleiben und was es kostet.', route_line = 'Routenübersicht (Kathmandu – Koto – Meta – Kyang – Phu – Nar Phedi – Nar – Kang La – Ngawal – Ngadi – Kathmandu)', faq_heading = 'Häufige Fragen zum Nar Phu Trek', guide_ratio = '1 : 6 (2 Guides ab 7 Trekkern)', know_topics = '[{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die besten Monate für den Nar Phu Trek sind April–Mai und Oktober–November, wenn der Kang La meist offen ist, der Himmel klar ist und die Lodges geöffnet haben. Auch März, September sowie Anfang bis Mitte Dezember sind gut, mit einigen Abstrichen. Meiden Sie Ende Dezember bis Februar, wenn Schnee oft den Pass versperrt, und Juni bis August, wenn der Monsun Erdrutsche auf die Straße bringt.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die folgenden Temperaturen sind Tageshöchst- und Nachttiefstwerte für Phu (4.080 m). Es sind Schätzwerte auf Grundlage der Wetterstation in Jomsom, die Nächte können also kälter sein, besonders wenn es klar und windig ist.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Januar–Februar (Winter):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Sehr kalt, trocken und klar; in Phu tagsüber etwa 2–3 °C und nachts −9 bis −11 °C. Starker Schnee versperrt oft den Kang La, und viele Dorfbewohner ziehen in die Städte, auch wenn einige Teehäuser geöffnet bleiben. Nicht empfohlen.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "März (früher Frühling):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Meist klar mit windigen Nachmittagen; tagsüber etwa 6 °C, nachts −7 °C. Auf dem Pass kann noch tiefer Schnee liegen, prüfen Sie die Bedingungen also vor der Buchung.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "April–Mai (Frühling):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Klare Vormittage, nachmittags Wolken und Wind; tagsüber etwa 10–12 °C, nachts −4 bis −1 °C. Eine gute Reisezeit, und die Sperrgebietsgenehmigung ist günstiger (US$75 statt US$100 für die ersten 7 Tage).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Juni–August (Monsun):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Nar Phu liegt im Regenschatten, daher bekommt das obere Tal nur leichten Regen. Am unteren Marsyangdi gibt es jedoch starken Regen, Blutegel und Erdrutsche, die oft die Straße nach Koto blockieren. Nicht empfohlen.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "September (früher Herbst):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Der Monsun geht zu Ende, mit einigen frühen Schauern; tagsüber etwa 13 °C, nachts 3 °C. Die Straßen sind noch anfällig für Erdrutsche.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Oktober–November (Herbst):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Klar, trocken und beständig; im Oktober tagsüber etwa 9 °C und nachts −3 °C, im November sinkend auf 6 °C und −7 °C. Die beste Zeit für die Aussicht und für die Überquerung des Kang La.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Anfang bis Mitte Dezember:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Klare Sicht und ruhige Wege, aber sehr kalte Abende und Nächte in Nar und Phu (etwa −10 °C). Wasser gefriert, und am Kang La fällt viel Schnee. Ab Mitte bis Ende Dezember kann starker Schnee den Pass versperren.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Selbst in den besten Monaten kann das Wetter umschlagen. Ende September 2026 sperrten Unwetter den Kang La am 7. Oktober, am 15. Oktober war er wieder offen. Wir prüfen die Bedingungen an Pass und Straße vor jedem Aufbruch.", "type": "text"}]}]}, "icon": "wb_twilight", "note": "Schnee kann den Kang La selbst im Herbst tagelang sperren: 2026 war er vom 7. bis 15. Oktober geschlossen.", "title": "Beste Reisezeit für den Nar Phu Trek", "photoId": "9c3d3b98-5bf4-4dcc-824c-935aa3d900c0", "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Sie übernachten jede Nacht in einfachen, familiengeführten Teehäusern und bei Gastfamilien, mit Ausnahme einer Nacht im Gästehaus eines Klosters. Am komfortabelsten ist es in Koto und Ngawal am Annapurna Circuit, am einfachsten in Phu und Nar.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Koto und Meta", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Koto hat richtige Trekkinglodges mit Einzel- und Doppelzimmern, einige mit eigenem Bad. Heiße Duschen und Aufladen kosten extra, und das WLAN ist langsam. In Meta gibt es ein paar kleine Teehäuser mit Zweibettzimmern, gemeinsamen Hocktoiletten und Eimerduschen.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Kyang und Phu", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Kyang hat ein paar einfache Lodges, keine davon mit eigener Toilette. In Phu dienen traditionelle Familienhäuser als Gästehäuser. Die Zimmer sind knapp und einfach, die Toiletten gemeinschaftlich, und die Dusche ist ein Eimer heißes Wasser.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Kloster Nar Phedi und Nar", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In Nar Phedi übernachten Sie im Gästehaus der Satek Gompa (Sartek Thrangu Choepel Ling), deren Zimmer sauber und gepflegt sind. Nar hat mehrere kleine Homestays in Steinhäusern, aber nur wenige Zimmer, daher buchen wir in den beliebten Monaten im Voraus.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Ngawal nach dem Kang La", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Ngawal hat mehrere Lodges, Cafés und Teehäuser, einige Zimmer mit eigenem Bad und Bergblick. Manche Lodges bieten WLAN für etwa NPR 100. Auf dem Rückweg hat Ngadi ein paar Lodges mit guter Ausstattung, einige Zimmer mit eigener Toilette.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Gut zu wissen", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Zimmer sind nicht beheizt, der warme Ort in jeder Lodge ist daher der Speiseraum, in dem abends der Ofen angeheizt wird. Bringen Sie einen warmen Schlafsack, eine Stirnlampe für nächtliche Toilettengänge und Toilettenpapier mit. In den meisten Teehäusern können Sie Geräte aufladen, aber Kälte entlädt Akkus schnell, halten Sie sie nachts also warm.", "type": "text"}]}]}, "icon": "cottage", "note": "", "title": "Unterkunft am Nar Phu Trek", "photoId": "361cae09-ece4-4402-bdc3-29b6392c95ca", "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Rechnen Sie am Nar Phu Trek mit etwa US$15–25 am Tag für Essen: US$15 für einfache Gerichte wie Dal Bhat, Momos und Tee, bis zu US$25 für westliche Gerichte wie Pizza und Pasta. Die Preise sind höher als in Kathmandu, weil alles per Jeep, Träger oder Lasttier ins Tal gebracht wird.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Essen unterwegs", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Koto und Ngawal haben vollständige Trekking-Speisekarten mit nepalesischen, tibetischen und westlichen Gerichten. Von Meta bis Nar sind die Karten kurz: meist Dal Bhat (Reis, Linsensuppe und Gemüse), Nudeln, Suppe, Kartoffeln und tibetisches Brot. Das Kloster in Nar Phedi serviert einfache Menüs.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Ungefähre Preise für Essen und Leistungen", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Posten", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Ungefährer Preis", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dal Bhat", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "NPR 700", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Momos", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "NPR 800", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Essen pro Tag", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "US$15–25", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Gesamtkosten pro Tag (Essen und Leistungen)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "NPR 2.500–4.500", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Aufladen in Koto", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "US$1–3 pro Gerät", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "WLAN in Ngawal", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Etwa NPR 100", "type": "text"}]}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Nützliche Tipps", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Bestellen Sie dasselbe Gericht wie der Rest der Gruppe, denn so kochen die kleinen Küchen schneller. Essen Sie oberhalb von Meta frisch gekochte vegetarische Gerichte, denn Fleisch hat dort oft einen langen Weg ohne Kühlschrank hinter sich. Verzichten Sie bis nach dem Kang La auf Alkohol, da er die Höhenkrankheit verschlimmert. Bringen Sie für die langen Tage Snacks wie Nüsse, Schokolade und Energieriegel aus Kathmandu mit.", "type": "text"}]}]}, "icon": "soup_kitchen", "note": "", "title": "Essen am Nar Phu Trek (und Kosten)", "photoId": "77094c84-6ae9-46ae-8d29-52d1c34892a5", "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Wenn Sie mehr Zeit haben, können Sie Nar Phu mit dem Annapurna Circuit verbinden und einen zweiten hohen Pass überqueren, den Thorong La (5.416 m). Nach den Nächten in Phu und Nar und der Überquerung des Kang La sind die meisten Trekker dafür bereits gut akklimatisiert. Dieser längere Trek endet auf der Mustang-Seite in Muktinath.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tag 1–8:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Wie im Hauptreiseverlauf, von Kathmandu über den Kang La nach Ngawal.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tag 9:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Von Ngawal über Humde und Braga nach Manang (3.540 m), etwa 10 km und 4 Stunden.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tag 10:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Ruhetag in Manang.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tag 11:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Von Manang nach Yak Kharka (4.050 m), etwa 11 km und 4–5 Stunden.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tag 12:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Von Yak Kharka über Ledar nach Thorong Phedi (4.450 m), etwa 7 km und 4 Stunden.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tag 13:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Von Thorong Phedi über den Thorong La (5.416 m) nach Muktinath (3.800 m), etwa 16 km und 8–9 Stunden.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tag 14:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Mit dem Jeep von Muktinath nach Jomsom (2.720 m), etwa 23 km und 1 Stunde.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Tag 15:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Flug von Jomsom nach Pokhara (20–25 Minuten), dann Weiterreise nach Kathmandu.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Von Manang aus können Sie auch den Tilicho-See anhängen, das dauert etwa 3 Tage länger. Fragen Sie uns nach einem Preis für diese längeren Varianten.", "type": "text"}]}]}, "icon": "route", "note": "", "title": "Alternativer Reiseverlauf für Nar Phu mit dem Thorong La", "photoId": null, "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die Höhenkrankheit ist das größte Gesundheitsrisiko am Nar Phu Trek, denn Sie schlafen auf 4.080 m und 4.110 m und überqueren einen Pass auf 5.320 m. Die akute Höhenkrankheit (AMS) tritt auf, wenn Sie schneller aufsteigen, als sich Ihr Körper an die dünne Luft anpassen kann.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "So beugen Sie vor", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Langsam aufsteigen:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Unser Reiseverlauf teilt die Strecke von Meta nach Phu auf zwei Tage auf und sieht zwei Nächte in Phu vor.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Hoch steigen, tief schlafen:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Nutzen Sie an Tag 5 die Wanderung zum Himlung-Basislager oder nach Guru Sangbo und schlafen Sie danach wieder in Phu.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Wasser trinken:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Ziel sind 3–4 Liter am Tag, an heißen Tagen mehr.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Kein Alkohol und kein Rauchen:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Beides erschwert Ihrem Körper die Anpassung.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Langsam gehen und gut essen:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Ein gleichmäßiges Tempo und volle Mahlzeiten geben Ihrem Körper die nötige Energie.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Medikamente:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Manche Trekker nehmen Acetazolamid (Diamox), aber nur auf ärztlichen Rat.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Die Anzeichen kennen:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Frühe Anzeichen sind Kopfschmerzen, Übelkeit, Appetitlosigkeit, Schwindel, Müdigkeit und schlechter Schlaf. Ernste Anzeichen sind Verwirrtheit, Gleichgewichtsstörungen, Atemnot in Ruhe und feuchter Husten.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Bei frühen Anzeichen ruhen Sie sich aus und steigen nicht höher. Bei ernsten Anzeichen steigen Sie sofort ab: von Kyang oder Phu nach Meta, von Nar nach Nar Phedi (etwa 1,5 Stunden) und beim Aufstieg zum Kang La zurück nach Nar. Ihr Guide fragt jeden Morgen und Abend nach dem Befinden aller und trifft die endgültige Entscheidung über den Pass. Phu und Nar haben nur einfache Gesundheitsposten. Die Himalayan Rescue Association betreibt im Frühling und Herbst eine Hilfsstation in Manang.", "type": "text"}]}]}, "icon": "health_and_safety", "note": "", "title": "So beugen Sie der Höhenkrankheit am Nar Phu Trek vor", "photoId": null, "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Sie brauchen eine Reiseversicherung, die Trekking bis mindestens 5.320 m abdeckt, die Höhe des Kang La. Viele Standardpolicen enden bei 3.000 m oder 4.000 m, lesen Sie also vor dem Abschluss das Kleingedruckte.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Ihre Police sollte abdecken", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Höhe:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Trekking bis 6.000 m, um auf der sicheren Seite zu sein.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Hubschrauberrettung:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Eine Rettung aus dem Nar-Phu-Tal kostet etwa US$5.000–7.000.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Medizinische Versorgung und Rücktransport:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Krankenhausbehandlung in Kathmandu und bei Bedarf den Heimflug.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Stornierung und Verspätung:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Straßensperren und Schnee am Kang La können Ihre Reise um Tage verlängern.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Gepäck:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Verlust oder Diebstahl Ihres Gepäcks und Ihrer Ausrüstung.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Prüfen Sie, ob Ihre Police Trekking mit Guide abdeckt (nicht Klettern mit Seil) und eine rund um die Uhr erreichbare Notrufnummer hat. Schicken Sie uns vor dem Trek Ihre Policennummer, die Notrufnummer und eine Kopie Ihres Reisepasses. Mit diesen Angaben können wir im Notfall schnell eine Hubschrauberrettung organisieren.", "type": "text"}]}]}, "icon": "emergency", "note": "", "title": "Höhenversicherung für den Nar Phu Trek", "photoId": "e52c8350-8d25-4f49-8bca-cd07bd49943c", "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Trinkgeld ist in Nepal ein Brauch, keine Pflicht, doch Guides und Träger rechnen damit als Teil ihres Einkommens. Geben Sie, was Sie für die erhaltene Leistung angemessen finden.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Empfohlenes Trinkgeld", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Guide:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Etwa US$15 am Tag, von der ganzen Gruppe gemeinsam, nicht von jeder Person. Für den 10-tägigen Trek sind das etwa US$150 für die Gruppe.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Träger:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Etwa US$12 am Tag für jeden Träger, falls Sie einen buchen. Für 10 Tage sind das etwa US$120 pro Träger.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Die meisten Gruppen geben das Trinkgeld am letzten Abend oder am Ende der Rückfahrt nach Kathmandu. Stecken Sie das Geld in einen Umschlag und überreichen Sie es jeder Person selbst, damit der Träger seinen Anteil direkt bekommt. Trinkgeld kann in US-Dollar oder nepalesischen Rupien gegeben werden, bringen Sie aber saubere, unbeschädigte Scheine mit. Wenn Sie Ausrüstung wie eine Jacke oder Schuhe verschenken möchten, geben Sie sie zusätzlich zum Trinkgeld, nicht stattdessen.", "type": "text"}]}]}, "icon": "payments", "note": "", "title": "Trinkgeld am Nar Phu Trek", "photoId": null, "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Nar Phu Trek ist anspruchsvoll (Stufe 4 von 5). Schwer ist er wegen der Höhe, des 10-stündigen Tages über den Kang La und des abgelegenen Weges, nicht wegen Kletterei. Sie brauchen weder Seile noch technische Kenntnisse, aber eine gute Kondition und etwas Erfahrung mit mehrtägigen Treks.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Schwierigkeit nach Etappen", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Tag", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Etappe", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Höhe", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Gehzeit", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Unsere Einstufung", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "2", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Koto nach Meta", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "2.620 → 3.560 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "7 Std.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Schwer: lang, auf und ab, steiles Ende", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "3", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Meta nach Kyang", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "3.560 → 3.850 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "5 Std.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Mittelschwer: sanft, dann kurze steile Abschnitte", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "4", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Kyang nach Phu", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "3.850 → 4.080 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "3 Std.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Mittelschwer: Steinschlag im Canyon", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "5", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Himlung-Basislager", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "4.080 → 4.900 → 4.080 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "6 Std.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Schwer (Guru Sangbo ist kürzer, aber sehr steil)", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "6", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Phu nach Nar Phedi", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "4.080 → 3.490 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "8 Std.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Mittelschwer bis schwer: lang, belastet die Knie", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "7", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Nar Phedi nach Nar", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "3.490 → 4.110 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "2,5 Std.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Mittelschwer: kurz, aber steil", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "8", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Nar über den Kang La nach Ngawal", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "4.110 → 5.320 → 3.650 m", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "10 Std.", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Sehr schwer: hoch, lang, steiles Geröll", "type": "text"}]}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Was macht den Nar Phu Trek anspruchsvoll?", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Große Höhe:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Drei Nächte über 4.000 m und ein Pass auf 5.320 m. Über 5.000 m gibt es nur etwa halb so viel Sauerstoff wie auf Meereshöhe.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Der lange Passtag:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Etwa 10 Stunden, mit 1.261 m Aufstieg und 1.670 m Abstieg auf losem Geröll.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Ein abgelegener Weg mit einfachen Lodges:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Gemeinschaftstoiletten, Eimerduschen, kein Handyempfang auf dem Weg, ein schwacher in den Dörfern und auf langen Abschnitten keine Läden.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Kälte:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Ab Oktober fallen die Nachttemperaturen in Phu und Nar deutlich unter den Gefrierpunkt.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Wetter und Erdrutsche:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Schnee kann den Kang La sperren, und Erdrutsche können die Straße nach Koto blockieren.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Lange Fahrten:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Etwa 11,5 Stunden an Tag 1 und 8 Stunden an Tag 9 auf holprigen Straßen.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Wenn Sie schon einen Trek wie den Annapurna Circuit oder zum Everest Base Camp gemacht und sich in der Höhe wohlgefühlt haben, schaffen Sie auch Nar Phu. Ist es Ihr erster Trek im Himalaya, beginnen Sie mit einer niedrigeren und kürzeren Route.", "type": "text"}]}]}, "icon": "route", "note": "", "title": "Nar Phu Trek: Schwierigkeit", "photoId": null, "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Das Paket für den Nar Phu Trek kostet je nach Gruppengröße US$490–855 pro Person, dazu kommen unterwegs etwa NPR 2.500–4.500 am Tag für Essen und Leistungen der Lodges. Jeder Trek ist ein Privattrek, der Preis hängt also nur von der Größe Ihrer eigenen Gruppe ab.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Preis nach Gruppengröße", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Paketpreis reicht von US$855 für einen Alleinreisenden bis zu US$490 pro Person für eine Gruppe von 9–12. Die beliebteste Gruppengröße, 3–5 Trekker, kostet US$570 pro Person. Alle Größen finden Sie in der Tabelle der Gruppenpreise oben. Im Preis enthalten sind Genehmigungen, Transport vor Ort, Ihr Guide und die Zimmer in den Teehäusern.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Tägliche Ausgaben unterwegs", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Budget", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Essen pro Tag", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Gesamt pro Tag (Essen und Leistungen)", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Einfach: Dal Bhat, Momos und Tee, wenige Extras", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "US$15", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Ab NPR 2.500", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Komfort: westliche Gerichte wie Pizza und Pasta, täglich eine heiße Dusche, abgekochtes Wasser, Aufladen mehrerer Geräte", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "US$25", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Bis zu NPR 4.500", "type": "text"}]}]}]}]}, {"type": "paragraph", "content": [{"text": "Die Lodges rechnen in nepalesischen Rupien ab, prüfen Sie also vor der Reise den Wechselkurs und nehmen Sie Rupien mit. Planen Sie Geld für 2–3 zusätzliche Tage ein, falls es Verzögerungen gibt.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Weitere Kosten, die Sie einplanen sollten", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Kosten", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Preis", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Hinweise", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Mahlzeiten", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "US$15–25 am Tag", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dal Bhat etwa NPR 700, Momos etwa NPR 800", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Träger", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Fragen Sie uns", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Optional; trägt Ihr Hauptgepäck", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Trinkgelder", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Guide etwa US$15 am Tag pro Gruppe; Träger etwa US$12 am Tag", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Wird am Ende gegeben", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Visum für Nepal", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Siehe Department of Immigration", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Bei der Ankunft oder online erhältlich", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Versicherung", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Abhängig von Ihrem Anbieter", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Muss 5.320 m und Hubschrauberrettung abdecken", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Heiße Duschen, Aufladen, WLAN", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Kleine Gebühren in jeder Lodge", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Aufladen in Koto etwa US$1–3", "type": "text"}]}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Beispiel für die Gesamtkosten pro Person", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Dieses Beispiel umfasst den Paketpreis und 9 Tage Ausgaben unterwegs. Nicht enthalten sind Trinkgelder, Flüge, Visum, Versicherung und ein Träger.", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Kosten", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Gruppe von 4 (pro Person)", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "2 Trekker (pro Person)", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Alleinreisende", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Paket", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "US$570", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "US$610", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "US$855", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Ausgaben unterwegs (9 Tage × NPR 2.500–4.500)", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "NPR 22.500–40.500", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "NPR 22.500–40.500", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "NPR 22.500–40.500", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Geschätzte Summe", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "US$570 + NPR 22.500–40.500", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "US$610 + NPR 22.500–40.500", "type": "text", "marks": [{"type": "bold"}]}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "US$855 + NPR 22.500–40.500", "type": "text", "marks": [{"type": "bold"}]}]}]}]}]}, {"type": "paragraph", "content": [{"text": "Trinkgelder kommen hinzu. Rechnen Sie mit etwa US$15 am Tag für den Guide, die sich die ganze Gruppe teilt, und etwa US$12 am Tag für jeden Träger, den Sie buchen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Heben Sie Ihr ganzes Bargeld für unterwegs in Kathmandu oder Besisahar ab, dazu Geld für 2–3 zusätzliche Tage, falls es Verzögerungen gibt: etwa NPR 5.000–13.500 mehr.", "type": "text"}]}]}, "icon": "payments", "note": "", "title": "Nar Phu Trek: Gesamtkosten und Tagesbudget", "photoId": null, "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Für den Nar Phu Trek brauchen Sie zwei Genehmigungen: die Sperrgebietsgenehmigung für Nar Phu (Restricted Area Permit, RAP) und die Genehmigung für das Annapurna Conservation Area (ACAP). Beide sind in unserem Preis enthalten.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Kosten der Genehmigungen für Nar Phu", "type": "text"}]}, {"type": "table", "content": [{"type": "tableRow", "content": [{"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Genehmigung", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Saison", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Kosten für Ausländer", "type": "text"}]}]}, {"type": "tableHeader", "content": [{"type": "paragraph", "content": [{"text": "Kosten für SAARC-Staatsangehörige", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Sperrgebietsgenehmigung für Nar Phu", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "September–November", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "US$100 für die ersten 7 Tage, danach US$15 pro Tag", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "—", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Sperrgebietsgenehmigung für Nar Phu", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Dezember–August", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "US$75 für die ersten 7 Tage, danach US$15 pro Tag", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "—", "type": "text"}]}]}]}, {"type": "tableRow", "content": [{"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "ACAP", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "Ganzjährig", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "NPR 3.000", "type": "text"}]}]}, {"type": "tableCell", "content": [{"type": "paragraph", "content": [{"text": "NPR 1.000", "type": "text"}]}]}]}]}, {"type": "paragraph", "content": [{"text": "Die ACAP-Gebühr enthält die Mehrwertsteuer. Bei Online-Zahlung fällt eine Kartengebühr von 2,9 % an. Wenn Sie die ACAP unterwegs kaufen, auch in Besisahar, kostet sie das Doppelte: NPR 6.000 für Ausländer und NPR 2.000 für SAARC-Staatsangehörige.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Wo und wie Sie die Genehmigungen bekommen", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Sperrgebietsgenehmigung stellt das Department of Immigration in Kathmandu aus, und zwar nur über eine registrierte Trekkingagentur. Sie müssen mit einem lizenzierten Guide trekken. Seit dem 22. März 2026 kann auch ein einzelner Trekker die Genehmigung erhalten, und ein Guide darf bis zu 7 Trekker führen. Wir beantragen die Genehmigung mit Ihren Passdaten für Sie. Die ACAP verkauft das Nepal Tourism Board in Kathmandu und Pokhara oder online. Ihr Guide zeigt die Genehmigungen am Kontrollposten in Koto vor, und ACAP-Beamte können sie in Dharapani und Manang erneut prüfen.", "type": "text"}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"text": "Braucht man eine TIMS-Karte?", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Nein, für den Nar Phu Trek brauchen Sie keine TIMS-Karte. Die Sperrgebietsgenehmigung und die ACAP sind die einzigen Genehmigungen, die Sie brauchen.", "type": "text"}]}]}, "icon": "description", "note": "Ihr Guide trägt die Genehmigungen bei sich. Haben Sie Ihren Reisepass für die Kontrolle in Koto im Tagesrucksack.", "title": "Nar Phu Trek: Genehmigungen", "photoId": "4b062b68-2d54-41fe-b9ce-797416f115f0", "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die Route des Nar Phu Treks besteht aus drei Teilen: der Anfahrt, sieben Tagen zu Fuß und der Rückfahrt.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Anfahrt (Tag 1):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Kathmandu (1.400 m) → Besisahar (760 m) → Ngadi (1.100 m) → Jagat (1.300 m) → Tal (1.700 m) → Dharapani (1.860 m) → Koto (2.620 m).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Trek (Tag 2–8):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Koto (2.620 m, Beginn des Treks) → Odhar (2.970 m) → Hulaki Odhar (3.060 m) → Singenge Dharmasala (3.230 m) → Meta (3.560 m) → Jhunum (3.610 m) → Chyakhu (3.735 m) → Kyang (3.850 m) → Phu (4.080 m), mit Abstechern nach Tashi Lakhang (4.150 m) und zum Himlung-Basislager (4.900 m) → zurück über Kyang nach Nar Phedi (3.490 m) → Nar (4.110 m) → Kang La Phedi → Kang La (5.320 m) → Ngawal (3.650 m, Ende des Treks).", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Rückfahrt (Tag 9–10):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Ngawal (3.650 m) → Ngadi (1.100 m) → Besisahar (760 m) → Kathmandu (1.400 m).", "type": "text"}]}]}]}, {"type": "paragraph"}]}, "icon": "route", "note": "", "title": "Nar Phu Trek: Route", "photoId": null, "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Nar Phu Trek ist im November 2026 geöffnet, und der Kang La ist begehbar. Unwetter Ende September sperrten den Pass, der am 15. Oktober wieder öffnete.", "type": "text"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Kang La Pass:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Seit dem 15. Oktober 2026 offen. Ab Mitte November ist mit kälteren Morgen und möglichem Eis nahe dem Gipfel zu rechnen.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Straße nach Koto:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Die Straße Besisahar–Chame war durch die Unwetter nahe Koto blockiert und ist seit dem 3. Oktober wieder frei. Rechnen Sie mit langsamen Abschnitten.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Straße ab Ngawal:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Der Abschnitt zwischen Chame und Bhratang wurde beschädigt. Die Jeeps fahren, können aber langsamer sein oder kurze Fußwege um beschädigte Stellen erfordern.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Lodges:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Die Lodges in Koto, Meta, Kyang, Phu, Nar Phedi, Nar und Ngawal sind für die Herbstsaison geöffnet.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Wetter:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Klare, trockene Tage, nachts im November etwa −7 °C in Phu, im Dezember kälter.", "type": "text"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"text": "Genehmigungen:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Seit dem 22. März 2026 können Alleinreisende die Sperrgebietsgenehmigung mit einem lizenzierten Guide erhalten.", "type": "text"}]}]}]}, {"type": "paragraph", "content": [{"text": "Wir aktualisieren diesen Abschnitt jede Saison.", "type": "text"}]}]}, "icon": "wb_twilight", "note": "Wir aktualisieren diesen Abschnitt jede Saison.", "title": "Nar Phu Trek: aktuelle Lage (November 2026)", "photoId": "0f67f046-4e9e-425a-ab49-bac30a141b01", "videoId": null}]'::jsonb, guides_intro = 'Lizenzierte Guides, die die Täler von Manang gut kennen, in Wildnis-Erster-Hilfe ausgebildet sind und Erfahrung am Kang La haben.', introduction = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Nar Phu Trek ist ein 10-tägiger Trek in ein verborgenes Seitental des Distrikts Manang im nördlichen Zentralnepal. Sie verlassen den Annapurna Circuit in Koto (2.620 m), wandern durch die enge Schlucht des Nar Khola hinauf zu den Steindörfern Phu (4.080 m) und Nar (4.110 m) und überqueren den Kang La Pass (5.320 m) nach Ngawal (3.650 m). Die Route ist eine Schleife abseits des Circuit, keine Sackgasse. Denselben Weg gehen Sie nur zwischen Phu und der Abzweigung oberhalb von Meta zweimal.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Das Tal liegt im Annapurna Conservation Area, nahe der Grenze zu Tibet. Deshalb war es bis 2003 für ausländische Trekker gesperrt, und es ist bis heute ein Sperrgebiet. Sie brauchen eine Sondergenehmigung und müssen mit einem lizenzierten Guide trekken, der über eine registrierte Agentur gebucht ist. Seit dem 22. März 2026 kann eine Person diese Genehmigung allein erhalten, Alleinreisende müssen also keinen Partner mehr suchen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Menschen in Nar und Phu folgen dem tibetischen Buddhismus. Ihre Dörfer haben Steinhäuser mit Flachdächern, Gebetsfahnen, Chörten (buddhistische Schreine) und alte Klöster. Nur wenige Trekker kommen hierher: Im Haushaltsjahr 2025–26 erhielten nur etwa 1.338 Personen die Genehmigung für Nar Phu. Vergleichen Sie das mit dem belebten Annapurna Circuit gleich nebenan, und Sie verstehen, warum wir dies einen der ruhigsten Hochgebirgstreks Nepals nennen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Trek ist anstrengend. Sie schlafen drei Nächte über 4.000 m, und der Tag über den Kang La dauert etwa 10 Stunden. Der Weg erfordert aber keine Kletterkenntnisse, nur eine gute Kondition, Geduld und Zeit, sich an die Höhe zu gewöhnen.", "type": "text"}]}]}'::jsonb, know_heading = 'Ratgeber zum Nar Phu Trek: Reisezeit, Unterkünfte und Sicherheit', packing_line = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Packen Sie für kalte Nächte und einen hohen Pass. Ihre Ausrüstung ist größtenteils dieselbe wie bei jedem Teehaus-Trek, doch einige Dinge sind hier wichtiger.", "type": "text"}]}]}'::jsonb, photo_badges = '[{"icon": "nordic_walking", "tone": "green", "label": "Mit lokalem Guide"}, {"icon": "health_and_safety", "tone": "brand", "label": "Akklimatisierungstage"}]'::jsonb, season_label = 'Apr.–Mai, Okt.–Nov.', start_finish = 'Kathmandu / Kathmandu (zu Fuß von Koto nach Ngawal)', accommodation = 'Teehäuser und Homestays', daily_walking = '2,5 bis 10 Stunden am Tag', intro_heading = 'Nar Phu Valley Trek im Überblick', pricing_intro = 'Der Nar Phu Trek kostet ab US$570 pro Person für eine Gruppe von 3–5 Trekkern, unsere beliebteste Gruppengröße. Alle Preise enthalten den Transport vor Ort, die Genehmigungen, Ihren Guide und die Zimmer in den Teehäusern.', similar_intro = 'Wenn Ihnen Nar Phu gefällt, bieten diese Treks eine ähnliche Mischung aus hohen Pässen, tibetisch-buddhistischer Kultur und ruhigen Wegen.', elevation_note = 'Höchster Übernachtungsort: Nar, 4.110 m. Höchster Punkt: Kang La Pass, 5.320 m.', guides_heading = 'Lernen Sie Ihren Trekkingguide kennen', packing_groups = '[{"icon": "apparel", "items": [{"text": "Die Nächte in Phu sinken im Oktober auf etwa −3 °C und im November auf −7 °C, im Dezember wird es noch kälter.", "title": "Daunenjacke"}, {"text": "Thermo-Unterwäsche, eine Fleecejacke, eine wasserdichte Jacke und Hose, eine warme Mütze und zwei Paar Handschuhe.", "title": "Schichten"}], "title": "Kleidung"}, {"icon": "footprint", "items": [{"text": "Eingelaufene Trekkingschuhe mit gutem Knöchelhalt für das Geröll am Kang La.", "title": "Schuhe"}, {"text": "Für einen vereisten Pass am frühen Morgen, besonders ab November.", "title": "Grödel"}, {"text": "Leichte Sandalen oder Turnschuhe für die Abende.", "title": "Hüttenschuhe"}], "title": "Schuhwerk"}, {"icon": "backpack", "items": [{"text": "Ein warmer Schlafsack für Temperaturen weit unter dem Gefrierpunkt; die Decken der Lodges allein halten Sie in Phu und Nar womöglich nicht warm.", "title": "Schlafsack"}, {"text": "Zwei Stöcke für den Abstieg von 1.670 m nach Ngawal.", "title": "Trekkingstöcke"}, {"text": "Für den Aufbruch um 5:00 Uhr am Tag über den Kang La und nächtliche Gänge zu Außentoiletten.", "title": "Stirnlampe"}, {"text": "Mindestens 10.000 mAh, warm gehalten in Ihrer Jacke oder Ihrem Schlafsack.", "title": "Powerbank"}], "title": "Taschen und Ausrüstung"}, {"icon": "medical_services", "items": [{"text": "Medikamente gegen Höhenkrankheit auf ärztlichen Rat, dazu Ihre eigene Erste-Hilfe-Grundausstattung.", "title": "Medikamente"}, {"text": "Ein Filter oder Entkeimungstabletten und Flaschen für 2–3 Liter.", "title": "Wasseraufbereitung"}, {"text": "Sonnenbrille, Sonnencreme und Lippenpflege für die hohen, hellen Tage.", "title": "Sonnenschutz"}], "title": "Gesundheit und Wasser"}, {"icon": "description", "items": [{"text": "Ihr Guide zeigt Ihre Genehmigungen in Koto vor, und die Polizei kann Ihren Reisepass kontrollieren.", "title": "Reisepass"}, {"text": "Alle nepalesischen Rupien, die Sie für den Trek brauchen, abgehoben in Kathmandu oder Besisahar.", "title": "Bargeld"}], "title": "Dokumente"}]'::jsonb, itinerary_intro = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der 10-tägige Plan umfasst eine lange Anfahrt, sieben Tage zu Fuß und zwei Tage Rückfahrt. Einer der sieben Wandertage ist ein Akklimatisierungstag in Phu. Den Aufstieg von Meta nach Phu teilen wir auf zwei Tage auf, mit einer Nacht in Kyang, damit sich Ihr Körper vor den hoch gelegenen Dörfern anpassen kann. Alle Zeiten und Entfernungen unten stammen aus unseren eigenen Aufzeichnungen, für einen gleichmäßigen Geher mit Guide. Ihr Tag kann je nach Tempo, Wetter und Fotopausen kürzer oder länger sein.", "type": "text"}]}, {"type": "image", "attrs": {"alt": "Karte des Nar Phu Valley Trek", "width": 1200, "height": 820, "photoId": "41ec4d93-1f0a-43a7-8b37-812990fe2685", "fileName": "nar-phu-valley-trek-map-mini-overview-map", "variantWidths": [400, 800, 1200]}}, {"type": "paragraph"}]}'::jsonb, meal_trail_tips = '[{"text": "Planen Sie ein oder zwei Reservetage für Schnee, Erdrutsche oder Krankheit ein. Schnee kann den Kang La tagelang sperren: Im Oktober 2026 blieb er vom 7. bis 15. Oktober geschlossen. Erdrutsche blockieren außerdem die Jeepstraße nach Koto, besonders im September und Oktober. Mit einem Reservetag können Sie sicher in Nar warten, statt den Pass zu überstürzen.", "title": "Planen Sie einen Reservetag ein"}, {"text": "Die Temperaturen schwanken auf diesem Trek stark. Eine Novembernacht in Koto sinkt auf etwa 2 °C, in Phu dagegen auf etwa −7 °C und im Dezember auf etwa −10 °C. Nehmen Sie eine Funktionsunterwäsche, eine Fleecejacke, eine Daunenjacke und eine wasserdichte Jacke mit, dazu einen Vier-Jahreszeiten-Schlafsack.", "title": "Packen Sie für große Temperaturunterschiede"}, {"text": "Laufen Sie Ihre Schuhe vor der Reise nach Nepal auf mehreren langen Wanderungen ein. Neue Schuhe verursachen auf langen Treks die meisten Blasen. Wählen Sie wasserdichte Schuhe mit gutem Knöchelhalt für den felsigen Canyon unterhalb von Phu und das lose Geröll am Kang La.", "title": "Laufen Sie Ihre Trekkingschuhe vor der Reise ein"}, {"text": "Trinken Sie 3–4 Liter am Tag, damit sich Ihr Körper an die Höhe anpassen kann. Verwenden Sie Entkeimungstabletten, einen Filter oder einen UV-Entkeimer, oder kaufen Sie abgekochtes Wasser in der Lodge. Heißer Zitronen- oder Ingwertee zählt auch.", "title": "Trinken Sie genug und bereiten Sie Ihr Wasser auf"}, {"text": "Ein Teller Dal Bhat kostet etwa NPR 700 und hält Sie stundenlang beim Wandern satt. Wählen Sie oberhalb von Meta frisch gekochte vegetarische Gerichte, denn Fleisch war dort womöglich tagelang ohne Kühlschrank unterwegs.", "title": "Essen Sie Dal Bhat für Energie"}, {"text": "Wir brechen gegen 5:00 Uhr in Nar auf. Wer früh startet, ist vor dem Nachmittagswind und den Wolken über den Pass. Nehmen Sie eine Stirnlampe, warmes Wasser, Snacks, Ihr Lunchpaket aus Nar und bei Neuschnee Grödel mit. Wenn wir den Gipfel nicht bis etwa 11:00 Uhr erreichen, kehren wir um.", "title": "Starten Sie früh am Tag über den Kang La"}, {"text": "Packen Sie Energieriegel, Nüsse, Trockenobst und Schokolade ein, bevor Sie die Stadt verlassen. Alles im Tal wird per Jeep, Träger oder Lasttier hinaufgebracht und kostet deshalb viel mehr. Snacks geben Ihnen schnelle Energie für den langen Aufstieg zum Kang La.", "title": "Bringen Sie Snacks aus Kathmandu mit"}, {"text": "Die Lodges verlangen für jedes Gerät eine Gebühr (etwa US$1–3 in Koto), und in Phu und Nar entlädt die Kälte die Akkus schnell. Bewahren Sie Powerbank und Handy nachts in Ihrem Schlafsack auf.", "title": "Nehmen Sie eine Powerbank mit mindestens 10.000 mAh mit"}, {"text": "Im Canyon zwischen Kyang und Phu gibt es brüchige Felswände und Steinschlag, nach Regen noch mehr. Halten Sie dort nicht für Pausen oder Fotos an. Wenn Sie einen Stein hören, schauen Sie nach oben und gehen Sie zur Seite.", "title": "Gehen Sie unter den Felswänden unterhalb von Phu zügig"}, {"text": "An Tag 6 biegt der Weg nach Nar Phedi etwa 1,8 km oberhalb von Meta ohne deutliche Beschilderung nach rechts (Westen) ab. Bleiben Sie hier bei Ihrem Guide, sonst gehen Sie womöglich 1,8 km zu weit hinunter nach Meta.", "title": "Achten Sie auf die Abzweigung oberhalb von Meta"}, {"text": "Gehen Sie links an Manimauern und Chörten vorbei, also im Uhrzeigersinn. Fragen Sie, bevor Sie Menschen, Mönche oder das Innere einer Gompa fotografieren. Kleiden Sie sich zurückhaltend, ziehen Sie vor dem Betreten eines Klosters die Schuhe aus und sprechen Sie in der Satek Gompa in Nar Phedi leise.", "title": "Respektieren Sie die örtliche Kultur und die Klöster"}, {"text": "Geben Sie Ihre Bestellung für das Abendessen bald nach der Ankunft auf und bestellen Sie das Frühstück am Vorabend. Die Küchen in Phu, Nar und Kyang sind klein und kochen oft auf einem einzigen Herd. Bestellen Sie in Nar Ihr Lunchpaket für den Tag über den Kang La am Vorabend.", "title": "Bestellen Sie Ihre Mahlzeiten im Voraus"}, {"text": "Wenn eine Maultier- oder Yakkarawane den Weg entlangkommt, treten Sie auf die Bergseite und warten Sie. Stellen Sie sich nie an die Kante über einem Abgrund. Tiere mit breiten Lasten können Sie vom schmalen Pfad stoßen.", "title": "Stellen Sie sich auf die Bergseite, wenn Tiere vorbeiziehen"}, {"text": "Im Spätherbst, Winter und Frühling ist der Kang La am frühen Morgen oben oft vereist. Grödel sind leicht und geben Ihren Schuhen auf dem gefrorenen Geröll festen Halt. Ihr Guide prüft die Bedingungen am Vorabend des Passes in Nar.", "title": "• Nehmen Sie von November bis April Grödel mit"}]'::jsonb, packing_heading = 'Packliste für den Nar Phu Trek', pricing_heading = 'Nar Phu Trek: Kosten nach Gruppengröße', seo_description = 'Trek zu den Dörfern Nar und Phu über den Kang La Pass (5.320 m) in 10 Tagen. Reiseverlauf, Genehmigungen, Kosten ab US$490, beste Reisezeit und Tipps.', similar_heading = 'Ähnliche Treks wie Nar Phu in Nepal', overview_heading = 'Nar Phu Trek: die wichtigsten Fakten', elevation_heading = 'Höhenprofil des Nar Phu Trek', itinerary_heading = 'Reiseverlauf des Nar Phu Valley Trek', route_map_heading = 'Routenkarte des Nar Phu Trek', suitability_intro = 'Der Nar Phu Trek passt zu fitten Wanderern, die schon einen mehrtägigen Trek gemacht haben und eine ruhige, kulturreiche Route mit einem großen Pass suchen. Als erster Trek ist er nicht geeignet.', highlights_heading = 'Highlights des Nar Phu Trek', inclusions_heading = 'Leistungen und nicht enthaltene Kosten beim Nar Phu Trek', suitability_points = '[{"text": "Rechnen Sie mit zwei langen Tagen. An Tag 2 (Koto nach Meta) steigen Sie in 7 Stunden auf einem Weg mit vielen Auf und Abs 940 m auf. An Tag 8 (Kang La) steigen Sie in 10 Stunden 1.261 m auf und 1.721 m ab. Trainieren Sie einige Monate vor der Reise mit langen Bergwanderungen mit Tagesrucksack.", "title": "Körperliche Anforderungen und Kondition"}, {"text": "Vor dem Pass auf 5.320 m schlafen Sie zwei Nächte in Phu (4.080 m) und eine in Nar (4.110 m). An Tag 2 schlafen Sie 940 m höher als in der Nacht davor, der größte Höhensprung des Treks.", "title": "Höhe und Akklimatisierung"}, {"text": "Sie brauchen weder Seile noch Kletterkenntnisse. Schwierig sind das lose Geröll (kleine rollende Steine) auf beiden Seiten des Kang La und nach Schneefall Eis nahe dem Gipfel.", "title": "Erforderliche Technik"}, {"text": "Die Zimmer sind einfach. Oberhalb von Koto sind die meisten Toiletten gemeinschaftliche Hocktoiletten, und die Dusche in Meta, Phu und Nar ist ein Eimer heißes Wasser.", "title": "Komfort unterwegs und Unterkunft"}, {"text": "Das Tal ist abgelegen. Auf dem Weg gibt es keinen Handyempfang, in den Dörfern nur ein schwaches, unzuverlässiges Signal, und die erste Fahrt dauert etwa 11,5 Stunden. Sie brauchen Geduld, wenn Wetter oder Straße die Gruppe aufhalten.", "title": "Mentale Belastbarkeit"}, {"text": "Wenn Sie Herz-, Lungen- oder Blutdruckprobleme haben, sprechen Sie vor der Buchung mit Ihrem Arzt. Phu und Nar haben nur einfache Gesundheitsposten, und richtige Hilfe ist nur per Hubschrauber erreichbar.", "title": "Gesundheitliche Voraussetzungen"}]'::jsonb, meal_teahouse_notes = '[{"text": "Essen Sie Frühstück und Abendessen dort, wo Sie übernachten. Die Lodges halten die Zimmerpreise niedrig, weil die Gäste dort essen.", "title": "Teehaus-Regel"}, {"text": "Nar Phu ist ein Sperrgebiet, Sie können es also nicht allein trekken. Sie müssen über eine registrierte nepalesische Trekkingagentur buchen, die Ihre Genehmigungen und einen lizenzierten Guide organisiert. Seit dem 22. März 2026 können Alleinreisende die Genehmigung erhalten, und ein Guide darf bis zu 7 Trekker führen.", "title": "Ein lizenzierter Guide ist Pflicht"}, {"text": "Bewahren Sie Ihren Reisepass und einige Fotokopien in einer wasserdichten Hülle auf. Ihre Genehmigungen werden in Koto kontrolliert, bevor Sie das Tal betreten, und ACAP-Beamte können sie in Dharapani oder Manang erneut prüfen.", "title": "Haben Sie Reisepass und Kopien der Genehmigungen dabei"}, {"text": "Ihre Police sollte Trekking bis 6.000 m und Hubschrauberrettung abdecken. Der Kang La ist 5.320 m hoch, und eine Rettung aus dem Tal kostet etwa US$5.000–7.000. Schicken Sie uns vor dem Trek die Daten Ihrer Police, damit wir im Notfall schnell eine Rettung organisieren können.", "title": "Die Reiseversicherung muss die Hubschrauberrettung abdecken"}, {"text": "Die Überquerung dauert etwa 10 Stunden. Sie steigen von Nar 1.261 m auf und 1.721 m nach Ngawal ab, und die letzten 1.670 m Abstieg führen über steiles, loses Geröll. Ihr Guide kann die Überquerung bei schlechtem Wetter verschieben, folgen Sie also immer seiner Entscheidung.", "title": "Der Kang La ist der schwerste Tag"}, {"text": "Sie schlafen drei Nächte über 4.000 m. Achten Sie auf Kopfschmerzen, Übelkeit, Schwindel, schlechten Schlaf und Appetitlosigkeit, und sagen Sie es sofort Ihrem Guide. Wenn die Beschwerden schlimmer werden, steigen Sie ab: von Nar nach Nar Phedi oder von Phu in Richtung Meta.", "title": "Kennen Sie die Anzeichen der Höhenkrankheit"}, {"text": "Von Meta bis Nar sind die Zimmer einfach und die Toiletten gemeinschaftlich. In Kyang gibt es keine Zimmer mit eigener Toilette, die Dusche in Meta, Phu und Nar ist ein Eimer heißes Wasser, und Nar hat nur wenige Zimmer. In den beliebten Monaten buchen wir im Voraus.", "title": "Die Teehäuser im oberen Tal sind einfach"}, {"text": "Die Fahrt von Kathmandu nach Koto ist etwa 236 km lang und dauert etwa 11,5 Stunden, das letzte Stück auf einer holprigen Jeepstraße. Der Jeep von Ngawal nach Ngadi braucht etwa 8 Stunden. Der Zustand der Straßen ändert sich nach jedem Monsun, rechnen Sie also mit Staub, Schlaglöchern und Verzögerungen.", "title": "Die Fahrten sind lang und holprig"}, {"text": "Meiden Sie Juni bis August. Das obere Tal bleibt recht trocken, doch weiter unten verursacht starker Regen Erdrutsche und Blutegel und blockiert oft die Straße nach Koto.", "title": "Der Monsun bringt Erdrutsche"}, {"text": "Ab Mitte bis Ende Dezember kann starker Schnee den Kang La bis zum Frühling versperren. Viele Dorfbewohner ziehen über den Winter in die Städte, auch wenn einige Teehäuser geöffnet bleiben. Fragen Sie uns nach den aktuellen Bedingungen, bevor Sie einen Wintertrek planen.", "title": "Im Winter kann der Pass gesperrt sein"}, {"text": "Auf dem Weg gibt es keinen Empfang, in Dörfern wie Chyakhu, Kyang, Phu und Nar nur ein schwaches, unzuverlässiges Signal. Kaufen Sie in Kathmandu eine NTC-SIM-Karte und sagen Sie Ihrer Familie, dass Sie mehrere Tage offline sein könnten.", "title": "Der Handyempfang ist eingeschränkt"}, {"text": "Nehmen Sie Ihren Plastikmüll zurück nach Besisahar oder Kathmandu. Verwenden Sie eine nachfüllbare Flasche und meiden Sie verpackte Produkte, damit dieses abgelegene Tal sauber bleibt.", "title": "Hinterlassen Sie keine Spuren"}]'::jsonb, suitability_heading = 'Ist der Nar Phu Trek das Richtige für Sie?' where trek_id = '52779a4e-13b7-46a5-8460-0131108a4458' and locale = 'de';
update public.trek_day_translations set title = 'Kathmandu nach Koto (2.620 m)', subtitle = 'Fahrt durch das Marsyangdi-Tal · Umstieg in den Jeep in Besisahar · Kontrolle der Genehmigungen in Koto', duration = '11,5 Std. Fahrt', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Heute ist die längste Fahrt der Reise, deshalb brechen wir früh in Kathmandu auf. Die ersten 176 km bis Besisahar (760 m) dauern auf einer asphaltierten, aber langsamen Fernstraße etwa 7 Stunden. Sie folgt dem Trishuli-Fluss, bevor sie nach Norden in den Distrikt Lamjung abbiegt. Besisahar ist der Hauptort des Distrikts und hat mehrere Banken. Hier steht auch der letzte zuverlässige Geldautomat des Treks, deshalb bitten wir alle Trekker, hier das ganze nötige Bargeld abzuheben.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In Besisahar steigen wir für die holprige Straße das Marsyangdi-Tal hinauf in einen öffentlichen Jeep um. Der Jeep erreicht Ngadi (1.100 m) in etwa 20 Minuten, Jagat (1.300 m) nach weiteren 1 Stunde 20 Minuten, dann Tal (1.700 m) und Dharapani (1.860 m), jeweils nach etwa 40 Minuten. Das letzte Stück bis Koto dauert etwa 1,5 Stunden. An klaren Tagen sehen Sie im unteren Tal zum ersten Mal den Manaslu (8.163 m), den Himalchuli (7.893 m), den Ngadi Chuli (7.871 m) und den Lamjung Himal (6.983 m).", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Jeepstraße ist holprig und staubig. Erdrutsche sind im Monsun sowie im September und Oktober häufig. Ende September 2026 blockierten Unwetter die Straße nahe Koto bis zum 3. Oktober, weshalb unser Team die Straße vor jedem Aufbruch prüft. Wenn die Fahrt sehr spät wird, übernachten wir eventuell in Besisahar oder Ngadi und fahren am nächsten Morgen weiter.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Koto liegt am Annapurna Circuit, gleich östlich von Chame. Die Lodges haben Einzel- und Doppelzimmer, einige mit eigenem Bad. Heiße Duschen kosten extra, Aufladen kostet etwa US$1–3 pro Gerät, und das WLAN ist langsam. Im November sinken die Nachttemperaturen in Koto auf etwa 2 °C. Haben Sie Ihren Reisepass im Tagesrucksack, denn Ihr Guide zeigt Ihre Genehmigungen am Polizei- und ACAP-Kontrollposten in Koto vor, bevor Sie das Tal betreten.", "type": "text"}]}]}'::jsonb where day_id = 'a984b79d-39f5-4a62-b781-a2a0dafa1071' and locale = 'de';
update public.trek_day_translations set title = 'Koto nach Meta (3.560 m)', subtitle = 'Schlucht des Nar Khola · Kiefernwald und Wasserfälle · Steiler Aufstieg nach Meta', duration = '7 Std.', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Dies ist der schwerste Aufstiegstag vor dem Pass, und wir brechen bald nach dem Frühstück auf. Nach der Kontrolle der Genehmigungen verlassen wir die Straße des Circuit, steigen zu einer Hängebrücke über den Marsyangdi ab und betreten die Schlucht des Nar Khola. Ab hier gibt es keine Straßen mehr und nur sehr wenige Menschen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Weg führt durch Kiefernwald, vorbei an Wasserfällen und an Felskanten entlang. Er steigt immer wieder an und fällt wieder ab, sodass sich der Tag härter anfühlt als die 940 m, die Sie bis zum Abend gewinnen. Die meisten Gruppen erreichen Odhar (2.970 m) nach etwa 4 Stunden und 7,2 km, und hier machen wir meist Mittagspause. Von Odhar ist es 1 Stunde (3,7 km) bis Hulaki Odhar, auch Tatopani genannt (3.060 m), und 1 Stunde 20 Minuten (3,6 km) bis Singenge Dharmasala (3.230 m), einem kleinen Rastplatz mit Unterstand.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der letzte Abschnitt ist der härteste. Auf nur 1,1 km steigt der Weg in 40 Minuten rund 365 m an, aus dem Wald hinaus auf die offene Terrasse von Meta. Lassen Sie sich Zeit. Kleine Schritte und gleichmäßiges Atmen funktionieren besser als schnelle Spurts und lange Pausen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Meta hat kleine Teehäuser mit Zweibettzimmern. Die Toiletten sind Hocktoiletten außerhalb des Zimmers, und eine Dusche bedeutet einen Eimer heißes Wasser. Der Handyempfang kommt und geht. Heute Nacht schlafen Sie 940 m höher als in der letzten Nacht, der größte Höhensprung des Treks. Leichte Kopfschmerzen sind häufig. Trinken Sie viel Wasser, essen Sie ein vollständiges Abendessen und sagen Sie Ihrem Guide, wie Sie sich fühlen. Wenn die Beschwerden schlimmer werden, führt der Weg nach unten auf dem Aufstiegsweg zurück nach Koto.", "type": "text"}]}]}'::jsonb where day_id = '8af72453-d6bd-4d5a-a99e-677b6431af67' and locale = 'de';
update public.trek_day_translations set title = 'Meta nach Kyang (3.850 m)', subtitle = 'Manimauern und Chörten · Mittagessen in Chyakhu · Weideland von Kyang', duration = '5 Std.', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Heute ist ein kürzerer Tag, der Ihrem Körper bei der Anpassung hilft. Etwa 1,8 km oberhalb von Meta teilt sich der Weg ohne deutliche Beschilderung. Halten Sie sich rechts (Norden) Richtung Phu. Der linke Abzweig führt nach Nar Phedi, und an diese Abzweigung kommen wir an Tag 6 zurück, Ihr Guide zeigt sie Ihnen also.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Weg steigt sanft an Chörten und langen Manimauern (Steinmauern mit eingemeißelten Gebeten) vorbei nach Jhunum (3.610 m), etwa 2,5 Stunden und 4,6 km von Meta entfernt. Eine Stunde weiter liegt Chyakhu (3.735 m). Beide sind alte saisonale Siedlungen, die einst von Khampa-Kämpfern genutzt wurden. Jhunum besteht heute meist aus Ruinen und Tierunterständen, in Chyakhu aber gibt es Lodges, in denen Trekker zu Mittag essen oder übernachten können. In Chyakhu sitzt außerdem die Verwaltung der Landgemeinde Narpa Bhumi, der örtlichen Gemeindeverwaltung für Nar und Phu.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Vor dem letzten Abschnitt machen wir meist Mittagspause in einer Lodge in Chyakhu, etwa 3,5 Stunden von Meta entfernt. Die letzten 2,8 km von Chyakhu nach Kyang dauern etwa 1,5 Stunden, mit kurzen, sehr steilen Auf- und Abstiegen. Achten Sie hier auf Ihre Schritte.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Kyang ist eine weite Weide mit Blick auf den Pisang Peak (6.091 m) und die Annapurna II. Ein paar einfache Lodges versorgen hier die Trekker. Keine hat Zimmer mit eigener Toilette, packen Sie also eine Stirnlampe für nächtliche Gänge nach draußen ein. Warum hier Halt machen und nicht bis Phu weitergehen? Von Meta nach Phu am Stück sind es 17,2 km und etwa 8 Stunden. Durch die Teilung schlafen Sie heute nur 290 m höher. Nutzen Sie den freien Nachmittag, um zu ruhen, Wasser zu trinken und vor dem Abendessen ein Stück bergauf zu gehen, und kommen Sie dann zum Schlafen wieder herunter.", "type": "text"}]}]}'::jsonb where day_id = '66dd06c0-366d-4418-a9b2-b7150938f0a6' and locale = 'de';
update public.trek_day_translations set high_place = 'Kloster Tashi Lakhang', title = 'Kyang nach Phu (4.080 m)', subtitle = 'Canyon mit Steinschlag · Phu-Tor · Kloster Tashi Lakhang', duration = '3 Std. + Kloster', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Heute erreichen Sie das höchste Dorf des Tals. Der Weg ist kurz, doch der Canyon unterhalb von Phu ist der gefährlichste Teil des unteren Weges. Der Pfad führt unter brüchigen Felswänden entlang und über mehrere Brücken. Kleine Steine können jederzeit fallen, nach Regen noch häufiger. Unsere Guides halten die Gruppe in diesen Abschnitten in Bewegung und legen unter den Felswänden nie Pausen ein. Wenn Sie einen Stein hören, schauen Sie nach oben und gehen Sie dann rasch zur Seite.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Kurz vor dem oberen Ende des Canyons passieren Sie das steinerne Eingangstor von Phu. Das Schild zeigt hier 4.010 m. Etwas weiter taucht das Dorf auf: dicht gedrängte Steinhäuser auf einem hohen Hügel, an der Ostseite ein senkrechter Abbruch zum Phu Khola. Ganz oben steht die Yul Gompa und überblickt das ganze Dorf.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Nach dem Mittagessen in Phu wandern wir zum Kloster Tashi Lakhang (4.150 m). Es ist nur 1 km und 20 Minuten entfernt, mit 80 m Aufstieg, bietet aber den besten Blick über die Dächer. Dieser kurze Weg hilft Ihrem Körper auch bei der Anpassung, weil Sie etwas höher steigen, bevor Sie tiefer schlafen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "In Phu dienen traditionelle Familienhäuser als Gästehäuser. Die Zimmer sind knapp, die Toiletten gemeinschaftlich, und die Dusche ist ein Eimer heißes Wasser. In den meisten Häusern können Sie Ihr Handy aufladen. Im Dorf gibt es etwas Handyempfang, aber er ist schwach und unzuverlässig. Vom Dorf aus sehen Sie den Gyaji Kang (7.038 m). Die Nächte sind hier kalt: etwa −3 °C im Oktober und −7 °C im November. Gehen Sie im Uhrzeigersinn um Chörten und Manimauern und fragen Sie, bevor Sie Menschen fotografieren.", "type": "text"}]}]}'::jsonb where day_id = '713684bc-5282-42ae-ab56-5f60a442cbc7' and locale = 'de';
update public.trek_day_translations set high_place = 'Himlung-Basislager', title = 'Akklimatisierungstag in Phu – Himlung-Basislager (4.900 m)', subtitle = 'Hoch steigen, tief schlafen · Himlung-Basislager oder Guru Sangbo', duration = '6 Std. hin und zurück', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Heute bleiben Sie eine zweite Nacht in Phu und nutzen den Tag, damit sich Ihr Körper anpasst. Die Regel ist einfach: tagsüber hoch steigen, dann tief schlafen. Wir bieten zwei Wanderungen an, und Ihr Guide wählt am Morgen gemeinsam mit Ihnen aus, je nachdem, wie alle geschlafen haben.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Hauptvariante ist das Himlung-Basislager (4.900 m). Der Weg führt von Phu nach Osten das Tal hinauf Richtung Himlung Himal. Er beginnt sanft und wird dann steil. Der Aufstieg ist 8,3 km lang und dauert etwa 4 Stunden, mit 945 m Höhengewinn. Der Abstieg dauert etwa 2 Stunden. Sie kommen am Rand des Himlung-Gletschers vorbei, dessen unteres Ende auf etwa 4.750 m liegt. Vom Basislager haben Sie einen nahen Blick auf den Himlung, den Nemjung und die Gletscher Himlung und Pangri.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Auf diesem Weg gibt es weder Lodges noch Wasserstellen. Nehmen Sie mindestens 2 Liter Wasser, ein Lunchpaket aus Phu und warme Kleidung mit, denn der Wind am Basislager ist selbst an sonnigen Tagen kalt. Das Basislager liegt 820 m höher als Ihr Schlafplatz. Wir gehen nur hinauf, wenn niemand Kopfschmerzen, Übelkeit oder Schwindel hat. Fühlt sich unterwegs jemand unwohl, kehren wir um.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die kürzere Variante ist der Aussichtspunkt Guru Sangbo (4.700 m). Er ist pro Richtung nur 2,2 km entfernt, aber sehr steil: 620 m Aufstieg in etwa 2,5 Stunden und 1,5 Stunden Abstieg. Von oben sehen Sie einen weiten Kreis von Gipfeln: Himlung Himal (7.126 m), Nemjung (7.140 m), Gyaji Kang (7.038 m), Ratna Chuli (7.035 m), Lugla Himal und weitere rund um das obere Phu-Tal. Diese Wanderung wählen wir, wenn jemand die Höhe bei der Ankunft gespürt hat oder das Wetter weiter oben schlecht ist.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Beide Wanderungen bringen Sie bis zum Nachmittag zurück nach Phu. Ruhen Sie sich aus, trinken Sie viel Wasser und essen Sie ein reichliches Abendessen. Eine gute zweite Nacht hier ist das beste Zeichen, dass Sie für Nar und den Pass bereit sind.", "type": "text"}]}]}'::jsonb where day_id = '22f9b5a9-e934-49d4-b22d-35222a05d3dd' and locale = 'de';
update public.trek_day_translations set title = 'Phu nach Nar Phedi (3.490 m)', subtitle = 'Zurück das Tal hinab · Abzweigung oberhalb von Meta · Satek Gompa', duration = '8 Std.', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Heute wandern Sie das Tal wieder hinunter und wechseln auf die Seite von Nar. Es ist ein langer Tag, aber meist bergab, und durch die geringere Höhe schlafen die meisten heute Nacht so gut wie sonst nie auf dem Trek.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die erste Hälfte folgt dem Weg, den Sie an Tag 3 und 4 heraufgekommen sind: hinunter durch den Canyon, vorbei am Phu-Tor, nach Kyang. Seien Sie unter den Felswänden genauso vorsichtig wie zuvor. Meist machen wir in Kyang Mittagspause, wo die Lodges eine warme Mahlzeit kochen. Von Kyang führt der Weg weiter an Chyakhu und Jhunum vorbei.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "An der Abzweigung etwa 1,8 km oberhalb von Meta verlassen wir den Aufstiegsweg und biegen nach rechts (Westen) ab. Viele Trekker verpassen diese Abzweigung, weil es keine deutliche Beschilderung gibt, und landen in Meta, 1,8 km zu weit. Von der Abzweigung fällt der Weg etwa 1,5 km zum Nar Khola ab, überquert den Fluss und erreicht Nar Phedi.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Anstiege an diesem Tag sind kurz, summieren sich aber auf 632 m, erwarten Sie also keinen leichten Spaziergang. Insgesamt verlieren Sie außerdem 1.222 m an Höhe, was die Knie stark belastet. Verwenden Sie auf den steilen Abstiegen Ihre Trekkingstöcke.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Heute Nacht schlafen Sie im Gästehaus von Sartek Thrangu Choepel Ling, auch Satek Gompa genannt. Es ist ein bewohntes buddhistisches Kloster, kürzlich in Weiß, Rot und Gold neu gestrichen, vor einer steilen Felswand gelegen. Die Zimmer sind sauber und gepflegt, und die Küche serviert einfache Menüs. Bitte kleiden Sie sich zurückhaltend, sprechen Sie im Innenhof leise und fragen Sie, bevor Sie in der Gebetshalle fotografieren. Wenn Sie früh auf sind, lohnt es sich, die Morgengebete der Mönche zu hören.", "type": "text"}]}]}'::jsonb where day_id = '938b45fa-013b-4a86-98d3-d6b8907119e5' and locale = 'de';
update public.trek_day_translations set title = 'Nar Phedi nach Nar (4.110 m)', subtitle = 'Steiler Serpentinenaufstieg · Chörten · Das Dorf Nar', duration = '2,5 Std.', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der heutige Weg ist kurz, aber steil und bringt Sie zu Ihrem höchsten Übernachtungsort. Wir verlassen das Kloster nach dem Frühstück und nehmen den Serpentinenweg direkt den Hang dahinter hinauf. Folgen Sie hier nicht dem Fluss: Der Weg nach Nar führt nach oben, nicht am Wasser entlang.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Aufstieg gewinnt auf 4,6 km etwa 635 m. Gehen Sie langsam, denn jetzt sind Sie wirklich in der Höhe. Etwa auf halber Strecke kommen Sie an einer Reihe bunter Chörten vorbei. Dann wird der Weg flacher und führt auf die bewirtschafteten, von Steinmauern gesäumten Terrassen von Nar, und das Dorf kommt in Sicht.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Nar ist das größte Dorf im Tal, mit mehr Häusern, Lodges und Feldern als Phu. Seine drei Nyingmapa-Klöster stehen in den Feldern nahe dem Dorf. Über den Dächern erhebt sich der Kang Guru (6.981 m), der Gipfel, unter dem Sie morgen entlanggehen. Hier überwiegen Homestays, und es gibt nur wenige Zimmer. In den beliebten Monaten buchen wir im Voraus, damit die Gruppe zusammenbleibt. Die Toiletten sind gemeinschaftlich, die Dusche ist ein Eimer heißes Wasser, und der Handyempfang ist schwach und unzuverlässig.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Sie kommen vor dem Mittagessen an, der Nachmittag ist also frei. Gehen Sie langsam durch das Dorf, besuchen Sie ein Kloster und trinken Sie viel Wasser. Dies ist auch die Zeit zur Vorbereitung auf den Pass. Vor dem Abendessen prüfen wir die Ausrüstung jedes Trekkers: warme Kleidung, Handschuhe, eine Stirnlampe mit frischen Batterien, Trinkflaschen für 2 bis 3 Liter, Sonnencreme und bei Schnee Grödel. Außerdem bestellen wir in der Lodge Lunchpakete für morgen, denn zwischen Nar und Ngawal gibt es nirgends etwas zu essen zu kaufen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Gehen Sie früh schlafen. Hat heute Abend jemand in der Gruppe Kopfschmerzen, die nicht vergehen, Appetitlosigkeit oder Schwindel, bleiben wir einen zusätzlichen Tag in Nar, statt zum Pass aufzubrechen.", "type": "text"}]}]}'::jsonb where day_id = '0bc99195-56ac-4140-9579-fd5edbfae1da' and locale = 'de';
update public.trek_day_translations set title = 'Nar über den Kang La Pass nach Ngawal (3.650 m)', subtitle = 'Aufbruch um 5:00 Uhr · Kang La Pass · Steiler Geröllabstieg nach Ngawal', duration = '10 Std.', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Dies ist der große Tag des Treks und der Grund für die ganze Akklimatisierung davor. Wir gehen gegen 5:00 Uhr mit Stirnlampen los. Der frühe Start ist wichtig: Wind und Wolken nehmen am Pass meist nach Mittag zu, und der gefrorene Boden ist am Morgen fester.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der erste Teil ist ein allmählicher Aufstieg durch ein weites Tal westlich von Nar, vorbei an Steinmauern und Yakweiden. Nach einigen Stunden erreichen Sie Kang La Phedi, auch Jhombu Kharka genannt, den Fuß des Passes. Es ist der letzte ebene Ort, um zu rasten und einen Snack zu essen. Darüber wird der Weg steil und steigt in engen Serpentinen über loses Gestein und Geröll an. Der Aufstieg von Nar zum Gipfel ist etwa 9 km lang und dauert rund 6 Stunden, Sie kommen also nur mit etwa 1,5 km pro Stunde voran. Machen Sie kleine Schritte und bleiben Sie zum Durchatmen stehen, so oft Sie es brauchen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Unsere Guides halten sich an klare Regeln zur Umkehr. Wir gehen zurück nach Nar, wenn wir den Gipfel nicht bis etwa 11:00 Uhr erreichen, wenn der Neuschnee höher als knietief ist, wenn Wolken den Weg verdecken, wenn der Wind sehr stark ist oder wenn jemand Anzeichen von Höhenkrankheit zeigt. Am Pass gibt es keinen Handyempfang.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Von den Gebetsfahnen auf 5.320 m öffnet sich der Blick über das Manang-Tal zur Annapurna II (7.937 m), zur Annapurna IV und III, zum Gangapurna (7.455 m), zum Tilicho Peak (7.134 m) und zum Pisang Peak, mit dem Kang Guru (6.981 m) ganz nah. An klaren Tagen zeigt sich der Manaslu am Horizont.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Der Abstieg nach Ngawal ist der steilste Abschnitt des ganzen Treks: 1.670 m hinunter auf 6,6 km, etwa 4 Stunden. Der obere Teil ist loses Geröll, das unter den Füßen rutscht. Setzen Sie vor jedem Schritt beide Stöcke unterhalb von sich auf, halten Sie die Knie locker und gehen Sie dicht beieinander, damit lose Steine niemanden weiter unten treffen. Im Frühling und Herbst kann der obere Teil am frühen Morgen vereist sein, dann helfen Grödel. Weiter unten wird der Pfad staubig und führt durch Weiden und Wacholderbüsche, tief unten liegt die Landepiste von Humde.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Ngawal ist ein ruhiges tibetisch-buddhistisches Dorf mit einer Gompa und Gebetsmühlen in der Mitte. Die Lodges sind komfortabler als die im Tal, einige mit eigenem Bad, und manche bieten WLAN für etwa NPR 100. Ist der Pass gesperrt, gehen wir auf demselben Weg zurück, über Nar Phedi und Meta nach Koto: etwa 23 km in 2 Tagen.", "type": "text"}]}]}'::jsonb where day_id = 'a2b0d1d6-6b58-4c41-accc-396d84f15a0f' and locale = 'de';
update public.trek_day_translations set title = 'Ngawal nach Ngadi (1.100 m)', subtitle = 'Mit dem Jeep das Marsyangdi-Tal hinab · Optional zu Fuß nach Manang', duration = '8 Std. Jeep', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Heute verlassen Sie die Berge auf der Straße. Ein öffentlicher Jeep bringt Sie von Ngawal hinunter zur Hauptstraße im Marsyangdi-Tal unterhalb von Humde, dann vorbei an Pisang, Chame und Dharapani bis nach Ngadi. Die Straße ist größtenteils holprig und unbefestigt, und die Fahrt dauert mit Pausen etwa 8 Stunden.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Die Fahrt ist langsam, rechnen Sie also mit Schlaglöchern und Staub und tragen Sie ein Halstuch oder eine Maske. Ende September 2026 beschädigten Unwetter die Straße zwischen Chame und Bhratang, sodass einige Abschnitte langsamer sein oder einen kurzen Fußweg um eine beschädigte Stelle erfordern können. Wir prüfen die Straße vor der Abfahrt und planen Pausen für Mittagessen und Erholung ein.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Wenn Sie mehr Zeit und Energie haben, können Sie auf den Jeep verzichten und stattdessen auf dem Annapurna Circuit weiterwandern. Von Ngawal sind es etwa 2 km und 1 Stunde bis Humde, 6 km und 2,5 Stunden bis Braga und weitere 2 km und 30 Minuten bis Manang (3.540 m). Von dort gehen viele Trekker weiter zum Tilicho-See oder über den Thorong La (siehe den alternativen Reiseverlauf unten).", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Ngadi liegt tief im Tal auf 1.100 m, daher fühlt sich der Abend nach den kalten Nächten in Nar und Phu warm an. Das Dorf hat ein paar Lodges mit guter Ausstattung, einige Zimmer mit eigener Toilette. An klaren Abenden sehen Sie talaufwärts den Himalchuli und den Ngadi Chuli. Ein guter Abend, um sich auszuruhen, zu waschen und die Ausrüstung zu trocknen.", "type": "text"}]}]}'::jsonb where day_id = '297e715c-4da5-4777-a0dc-01c1347eea8b' and locale = 'de';
update public.trek_day_translations set title = 'Ngadi nach Kathmandu (1.400 m)', subtitle = 'Rückfahrt über Besisahar nach Kathmandu', duration = '7 Std. 20 Min. Fahrt', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der letzte Tag ist die Rückfahrt nach Kathmandu. Von Ngadi bringt Sie eine kurze Fahrt von 14,3 km in etwa 20 Minuten hinunter nach Besisahar (760 m). Von dort führt die asphaltierte Fernstraße 176 km zurück nach Kathmandu, was etwa 7 Stunden dauert. Rechnen Sie insgesamt mit etwa 7 Stunden 20 Minuten Fahrzeit, dazu Pausen für Tee und Mittagessen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Bei der Einfahrt ins Kathmandutal am späten Nachmittag kann viel Verkehr sein, die Ankunftszeiten schwanken also von Tag zu Tag. Wir bringen Sie zurück nach Kathmandu und setzen Sie in der Gegend Ihres Hotels ab. Wenn Sie einen internationalen Flug haben, buchen Sie ihn für den nächsten Tag oder später, denn Verzögerungen auf dieser Strecke sind häufig.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "An diesem Tag bedanken sich die meisten Gruppen auch bei ihrem Guide und den Trägern.", "type": "text"}]}]}'::jsonb where day_id = '5e008586-29b2-4daa-90d8-504e39e2b7b2' and locale = 'de';
update public.trek_group_price_translations set label = '1 Trekker', short_label = 'Allein', team = '1 lizenzierter Guide' where price_id = 'c05e0159-b176-4d26-bf69-92d987fb37ba' and locale = 'de';
update public.trek_group_price_translations set label = '2 Trekker', team = '1 lizenzierter Guide' where price_id = '1a9adf23-f507-4132-886f-994e0b0c8135' and locale = 'de';
update public.trek_group_price_translations set label = '3–5 Trekker', short_label = '3 bis 5', team = '1 lizenzierter Guide' where price_id = '7742bf22-2b3a-4421-a761-90a23faa21be' and locale = 'de';
update public.trek_group_price_translations set label = '6–8 Trekker', short_label = '6 bis 8', team = '1 lizenzierter Guide (2 Guides bei 7–8 Trekkern)' where price_id = '3f5aa49e-03ac-4062-b251-bda5026f6608' and locale = 'de';
update public.trek_group_price_translations set label = '9+ Trekker', short_label = '9 und mehr', team = '2 lizenzierte Guides' where price_id = '9296472d-1aa7-4423-afcb-b5c71aa2c9ff' and locale = 'de';
update public.trek_translations set faqs = '[{"icon": "calendar_month", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "An einem klaren Morgen Dhaulagiri (8.167 m), Tukuche Peak, Annapurna South, Annapurna I, Hiunchuli und Machapuchare, mit dem Tal der Kali Gandaki darunter.", "type": "text"}]}]}, "question": "Was sehe ich vom Poon Hill aus?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Oktober bis April. Herbst und Winter bieten die klarste Sicht, im März und April blühen die Rhododendren. Der Monsun (Juni bis August) ist nass und wolkig.", "type": "text"}]}]}, "question": "Wann ist die beste Reisezeit für den Poon Hill Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ja. Für Kinder, die das Wandern gewohnt sind, ist er einer der besten ersten Treks in Nepal. Die Steintreppe nach Ulleri ist der anstrengendste Teil, und wir können sie auf zwei Tage aufteilen.", "type": "text"}]}]}, "question": "Ist der Poon Hill Trek für Familien geeignet?"}], "title": "Allgemeine Informationen"}, {"icon": "nordic_walking", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Fünf Tage ab Pokhara und zurück, mit vier Nächten in Teehäusern. Er lässt sich auf vier Tage verkürzen oder mit dem Annapurna Base Camp oder dem Mardi Himal Trek kombinieren.", "type": "text"}]}]}, "question": "Wie lange dauert der Poon Hill Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Trek beginnt in Nayapul, etwa 1,5 Stunden mit dem Jeep von Pokhara. Pokhara erreichen Sie von Kathmandu in 6–7 Stunden mit dem Bus oder in 25 Minuten mit dem Flugzeug.", "type": "text"}]}]}, "question": "Wie komme ich zum Ausgangspunkt?"}], "title": "Reiseverlauf und Dauer"}, {"icon": "fitness_center", "items": [{"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Leicht, Stufe 2 von 5. Die Tagesetappen dauern 4–6 Stunden und haben lange Steintreppen, doch die Höhe bleibt gering und es gibt keine Kletterstellen.", "type": "text"}]}]}, "question": "Wie schwer ist der Poon Hill Trek?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Die Genehmigung für das Annapurna Conservation Area (ACAP) sowie eine TIMS-Karte, wo Kontrollpunkte danach fragen. Wir besorgen beides. In Nepal müssen ausländische Trekker mit einem lizenzierten Guide gehen, der über eine registrierte Agentur vermittelt wird. Bei all unseren Treks ist einer inbegriffen.", "type": "text"}]}]}, "question": "Welche Genehmigungen brauche ich?"}, {"answer": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Kaum. Die höchste Übernachtung ist in Ghorepani (2.860 m), und der Poon Hill liegt nur einen kurzen Morgenspaziergang höher. Trinken Sie viel und sagen Sie Ihrem Guide, wenn Sie sich unwohl fühlen.", "type": "text"}]}]}, "question": "Besteht ein Risiko für Höhenkrankheit?"}], "title": "Schwierigkeit, Genehmigungen und Sicherheit"}]'::jsonb, summary = 'Ein kurzer Trek von Pokhara zum berühmten Sonnenaufgang über Dhaulagiri und den Annapurnas.', activity = 'Trekking / Wandern', category = 'Kurzer Klassiker', excluded = '[{"text": "bestellen Sie frei von der Speisekarte (etwa $20–25 pro Tag).", "title": "Mahlzeiten auf dem Trek"}, {"text": "Bus oder Flug ab Kathmandu (wir buchen ihn gern für Sie).", "title": "Anreise nach Pokhara"}, {"text": "Pflicht, mit Deckung für Hubschrauberrettung.", "title": "Reiseversicherung"}, {"text": "vor und nach dem Trek.", "title": "Hotels in Pokhara"}, {"text": "heiße Duschen, Akkuladen und WLAN.", "title": "Extras in den Lodges"}]'::jsonb, headline = 'Poon Hill Trek in 5 Tagen ab Pokhara (Reiseverlauf, Kosten, kompletter Ratgeber)', included = '[{"text": "privater Jeep von Pokhara zum Ausgangspunkt und zurück.", "title": "Transport vor Ort"}, {"text": "in Erster Hilfe geschult, versichert und fair bezahlt.", "title": "Lizenzierter Guide und Träger"}, {"text": "4 Nächte auf dem Trek in familiengeführten Teehäusern.", "title": "Unterkunft in Teehäusern"}, {"text": "Genehmigung für das Annapurna Conservation Area (ACAP) und TIMS-Karte, wo Kontrollpunkte danach fragen.", "title": "Genehmigungen"}, {"text": "Erste-Hilfe-Set, das Ihr Guide dabeihat.", "title": "Sicherheitsausrüstung"}, {"text": "Abholung und Rückbringung an Ihrem Hotel in Pokhara.", "title": "Abholung am Hotel"}]'::jsonb, days_note = 'Ab Pokhara', seo_title = 'Poon Hill Trek 5 Tage ab Pokhara: Reiseverlauf, Kosten $430', transport = 'Jeep von Pokhara zum Ausgangspunkt', card_badge = 'Ideal für Familien', highlights = '[{"text": "Ein Aufstieg vor der Morgendämmerung zu einem Panorama vom Dhaulagiri bis zur Annapurna South und zum Machapuchare.", "title": "Sonnenaufgang am Poon Hill (3.210 m / 10.531 ft)"}, {"text": "Einige der größten Rhododendronwälder Nepals, im März und April rot und rosa.", "title": "Rhododendronwald"}, {"text": "Steinhäuser, Schieferdächer und Blicke auf die Annapurna South von den Dorfwegen aus.", "title": "Ghandruk, ein Gurung-Dorf"}, {"text": "Vier Nächte auf dem Trek und keine Sorgen wegen der Höhe, die höchste Übernachtung liegt auf 2.860 m.", "title": "Kurz und niedrig"}, {"text": "Klare, trockene Tage von Dezember bis Februar, wenn höhere Treks kalt oder gesperrt sind.", "title": "Den ganzen Winter über gut"}, {"text": "Ein bis zwei Stunden mit dem Jeep zum Ausgangspunkt, und danach können Sie sich in Pokhara am See erholen.", "title": "Start und Ziel in Pokhara"}]'::jsonb, know_intro = 'Wichtiges Wissen von unseren einheimischen Trekkingguides.', route_line = 'Übersicht der Route des Poon Hill Trek (Pokhara – Ulleri – Ghorepani – Poon Hill – Ghandruk)', faq_heading = 'Häufige Fragen zum Poon Hill Trek', guide_ratio = '1 : 4 + Träger', know_topics = '[{"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Herbst und Winter (Oktober bis Februar):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " klare, trockene Morgen und die schärfste Sicht beim Sonnenaufgang.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Frühling (März bis April):", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Rhododendronwälder in voller Blüte, im Laufe des Tages mehr Dunst.", "type": "text"}]}]}, "icon": "wb_twilight", "note": "Im Winter können die Nächte in Ghorepani unter den Gefrierpunkt fallen. Der Monsun (Juni–Aug.) bringt Regen, Blutegel und wolkenverhangene Aussichten.", "title": "Beste Reisezeit und Wetterfenster", "photoId": null, "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Zimmer:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Zweibettzimmer mit Decken; einige Lodges in Ghorepani und Ghandruk haben eigene Bäder.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Heizung und Duschen:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " abends warme Speiseräume und heiße Duschen in den meisten Lodges.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "WLAN und Strom:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Aufladen und WLAN gibt es fast überall gegen eine kleine Gebühr.", "type": "text"}]}]}, "icon": "cottage", "note": "", "title": "Unterkunft und Ausstattung der Teehäuser", "photoId": null, "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Dal Bhat:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Reis, Linsensuppe, Gemüse und Pickles, mit kostenlosem Nachschlag.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Speisekarten unterwegs:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Pfannkuchen, Porridge, Nudeln, Pasta, Momos und in Ghorepani Apfelkuchen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Trinken:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " trinken Sie 2–3 Liter am Tag und bereiten Sie Ihr Wasser auf; verzichten Sie auf Einwegplastik.", "type": "text"}]}]}, "icon": "soup_kitchen", "note": "", "title": "Essen, Ernährung und sicheres Trinkwasser", "photoId": null, "videoId": null}, {"body": {"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Hilfe in der Nähe:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Straßen reichen bis Ulleri und Ghandruk, sodass ein Jeep Sie meist innerhalb weniger Stunden erreichen kann.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Unterwegs:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " Ihr Guide hat ein Erste-Hilfe-Set dabei und steht mit unserem Büro in Kontakt.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Versicherung:", "type": "text", "marks": [{"type": "bold"}]}, {"text": " eine Reiseversicherung mit Deckung für Notfallevakuierung ist für jeden Trekker Pflicht.", "type": "text"}]}]}, "icon": "emergency", "note": "", "title": "Notfallplan und Evakuierung", "photoId": null, "videoId": null}]'::jsonb, seo_keyword = 'Poon Hill Trek', guides_intro = 'Lizenzierte Guides aus den Ausläufern des Annapurna, geduldig mit Familien und Trekking-Neulingen und in Erster Hilfe geschult.', introduction = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Der Poon Hill Trek ist der klassische kurze Trek in den Ausläufern des Annapurna und die beste Möglichkeit, den Hohen Himalaya in weniger als einer Woche zu erleben. Von Pokhara aus steigen Sie über die berühmte Steintreppe nach Ulleri, wandern durch Rhododendronwald nach Ghorepani (2.860 m) und stehen vor der Morgendämmerung auf, um den Sonnenaufgang vom Poon Hill (3.210 m) zu sehen.", "type": "text"}]}, {"type": "paragraph", "content": [{"text": "Vom Gipfel aus reihen sich Dhaulagiri (8.167 m), Annapurna South, Annapurna I, Hiunchuli und Machapuchare am Horizont auf, während die Sonne aufgeht. Die Route folgt dann ruhigen Waldgraten nach Tadapani und ins Gurung-Dorf Ghandruk, bevor sie zurück zur Straße hinabführt. Sie bleibt in geringer Höhe und eignet sich daher für Familien, Trekking-Neulinge und Winterreisende.", "type": "text"}]}]}'::jsonb, know_heading = 'Poon Hill Trek: Reisezeit, Ausstattung und Sicherheit', packing_line = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Leichte Ausrüstung für die Ausläufer: von frostigen Morgenstunden am Poon Hill bis zu warmen Nachmittagen in den Dörfern.", "type": "text"}]}]}'::jsonb, photo_badges = '[{"icon": "landscape", "tone": "brand", "label": "Berühmter Sonnenaufgang"}, {"icon": "nordic_walking", "tone": "green", "label": "Mit einheimischem Guide"}, {"icon": "route", "tone": "brand", "label": "Kurz und leicht"}]'::jsonb, season_label = 'Okt.–Apr.', accommodation = 'Teehaus', daily_walking = '4 bis 6 Stunden am Tag', pricing_intro = 'Buchen Sie direkt bei unserem Team in Kathmandu, ohne Zwischenhändler. Jeder Trek ist ein Privattrek, Sie wählen Ihr Startdatum also selbst.', similar_intro = 'Treks, die wir mit Ihnen planen und die von lokalen Guides geführt werden.', elevation_note = 'Sie übernachten nie höher als in Ghorepani auf 2.860 m und steigen nur zum Sonnenaufgang auf den Poon Hill.', guides_heading = 'Lernen Sie Ihren Trekkingguide kennen', packing_groups = '[{"icon": "apparel", "items": [{"text": "2 schnell trocknende Oberteile und eine Trekkinghose.", "title": "Basisschichten"}, {"text": "ein warmes Fleece für die Abende.", "title": "Fleece als Mittelschicht"}, {"text": "eine leichte Daunen- oder Kunstfaserjacke für den Sonnenaufgang am Poon Hill.", "title": "Warme Jacke"}, {"text": "eine wasserdichte Jacke für Regenschauer.", "title": "Regenjacke"}], "title": "Kleidung und Schichten"}, {"icon": "footprint", "items": [{"text": "eingelaufen, mit gutem Grip für Steinstufen.", "title": "Trekkingschuhe oder -stiefel"}, {"text": "leichte Turnschuhe oder Sandalen für das Teehaus.", "title": "Hüttenschuhe"}, {"text": "3–4 Paar gepolsterte Trekkingsocken.", "title": "Socken"}, {"text": "Pflaster und Tape für die lange Treppe.", "title": "Blasenpflege"}], "title": "Schuhwerk und Fußpflege"}, {"icon": "backpack", "items": [{"text": "mit Regenhülle für Kleidungsschichten, Wasser und Snacks.", "title": "Tagesrucksack (20–30 l)"}, {"text": "wird von Ihrem Träger getragen (max. 15 kg).", "title": "Reisetasche (Duffel Bag)"}, {"text": "ein leichter Schlafsack, oder leihen Sie einen in Pokhara; die Lodges haben auch Decken.", "title": "Schlafsack"}, {"text": "für den Aufstieg zum Poon Hill im Dunkeln und die Stufen bergab.", "title": "Stirnlampe und Stöcke"}], "title": "Ausrüstung und Gepäck"}, {"icon": "medical_services", "items": [{"text": "Tabletten oder ein UV-Stift sowie eine 1-Liter-Flasche.", "title": "Wasseraufbereitung"}, {"text": "Blasenpflaster, Schmerzmittel, Elektrolytpulver.", "title": "Reiseapotheke"}, {"text": "Sonnencreme mit LSF 50, ein Hut und Lippenpflege.", "title": "Sonnenschutz"}, {"text": "Feuchttücher, Handdesinfektionsmittel und ein schnell trocknendes Handtuch.", "title": "Hygiene"}], "title": "Gesundheit, Hygiene und Wasser"}]'::jsonb, itinerary_intro = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Fünf leichte Tage ab Pokhara und zurück. Sie fahren zum Ausgangspunkt, steigen über Ulleri und durch den Rhododendronwald nach Ghorepani, erleben den Sonnenaufgang vom Poon Hill und wandern dann über den Waldgrat nach Tadapani und Ghandruk, bevor es mit dem Auto zurück nach Pokhara geht. Jede Nacht verbringen Sie in einem familiengeführten Teehaus.", "type": "text"}]}]}'::jsonb, meal_trail_tips = '[{"text": "unbegrenzter Nachschlag von Reis, Linsen und Gemüsecurry. Der beste Treibstoff für die Treppen.", "title": "„Dal-Bhat-Power“"}, {"text": "trinken Sie vor dem Poon Hill einen Tee und frühstücken Sie danach richtig in Ghorepani.", "title": "Frühstück nach dem Sonnenaufgang"}, {"text": "trinken Sie 2–3 Liter am Tag (Ingwer-Zitrone-Honig-Tee, abgekochtes Wasser).", "title": "Genug trinken"}, {"text": "auf dem Weg gibt es keine Geldautomaten. Bringen Sie genug Nepalesische Rupien aus Pokhara mit.", "title": "Bargeld ist König"}]'::jsonb, packing_heading = 'Packliste für den Poon Hill Trek', pricing_heading = 'Gruppenpreise nach Gruppengröße', seo_description = 'Privater Poon Hill Trek in 5 Tagen ab Pokhara mit lokalem Guide: Ulleri, Rhododendronwald, Ghandruk und Sonnenaufgang über dem Dhaulagiri.', similar_heading = 'Ähnliche Treks in Nepal', elevation_heading = 'Route und Höhenprofil', itinerary_heading = 'Reiseverlauf Tag für Tag', route_map_heading = 'Routenkarte des Poon Hill Trek', suitability_intro = 'Eine ehrliche Checkliste unserer Guides, die Ihnen hilft zu entscheiden, ob der Poon Hill Trek zu Ihren Plänen passt.', highlights_heading = 'Höhepunkte des Poon Hill Trek und warum Sie ihn lieben werden', inclusions_heading = 'Was enthalten ist · Was nicht enthalten ist', suitability_points = '[{"text": "4 bis 6 Stunden am Tag mit einer langen Steintreppe nach Ulleri. Wer regelmäßig wandert, schafft das.", "title": "Körperliche Anforderungen und Fitness"}, {"text": "Sie übernachten nie höher als auf 2.860 m und steigen zum Sonnenaufgang auf 3.210 m. Die Höhe ist selten ein Problem.", "title": "Höhe und Akklimatisierung"}, {"text": "Keine. Durchgehend Steinstufen und Waldwege.", "title": "Erforderliche Technik"}, {"text": "Komfortable, familiengeführte Teehäuser mit Zweibettzimmern, heißen Duschen und warmen Speiseräumen.", "title": "Komfort unterwegs und Unterkunft"}, {"text": "Ein guter erster Trek für Kinder, die das Wandern gewohnt sind. Auf Wunsch planen wir kürzere Etappen.", "title": "Familien und Kinder"}, {"text": "Bei Herz- oder Lungenerkrankungen sprechen Sie vor der Buchung mit Ihrem Arzt über die steilen Anstiege.", "title": "Gesundheitliche Voraussetzungen"}]'::jsonb, meal_teahouse_notes = '[{"text": "frühstücken und essen Sie zu Abend, wo Sie übernachten. Nur so können die Lodges die Zimmerpreise niedrig halten.", "title": "Teehaus-Regel"}, {"text": "bestellen Sie das Abendessen gegen 17 Uhr und legen Sie die Frühstückszeit am Vorabend fest.", "title": "Früh bestellen"}, {"text": "Duschen, Aufladen und WLAN kosten jeweils ein bis zwei Dollar.", "title": "Kleine Extras"}]'::jsonb, suitability_heading = 'Ist dieser Trek das Richtige für Sie?' where trek_id = 'e88b8cbe-aead-486c-9b32-ee91552f5d51' and locale = 'de';
update public.trek_day_translations set title = 'Fahrt von Pokhara nach Nayapul, Trek nach Tikhedhunga (1.540 m)', subtitle = 'Kurzer erster Tag · Entlang der Bhurungdi Khola', duration = '1,5 Std. Fahrt · 3–4 Std.', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Eine kurze Fahrt von Pokhara nach Nayapul, dann eine leichte Wanderung vorbei an Birethanti und entlang des Flusses ins Dorf Tikhedhunga.", "type": "text"}]}]}'::jsonb where day_id = '0887127f-5e80-4b8e-a979-dee7e75b6b59' and locale = 'de';
update public.trek_day_translations set title = 'Von Tikhedhunga nach Ghorepani (2.860 m) über Ulleri', subtitle = 'Die berühmte Steintreppe · Rhododendronwald', duration = '6–7 Std.', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Steigen Sie die lange Steintreppe nach Ulleri (2.020 m) hinauf und gehen Sie dann sanfter durch Rhododendron- und Eichenwald weiter nach Ghorepani, einem belebten Dorf auf einem Pass mit Blick auf den Dhaulagiri.", "type": "text"}]}]}'::jsonb where day_id = '74a6fdf7-16e8-449d-a0f0-2632bd35be2f' and locale = 'de';
update public.trek_day_translations set title = 'Sonnenaufgang vom Poon Hill (3.210 m), Trek nach Tadapani (2.630 m)', subtitle = 'Der Höhepunkt des Treks · Panorama von Dhaulagiri und Annapurna', duration = '6–7 Std.', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ein einstündiger Aufstieg im Dunkeln bringt Sie zum Sonnenaufgang über Dhaulagiri, den Annapurnas und dem Machapuchare auf den Poon Hill. Nach dem Frühstück in Ghorepani wandern Sie über den Waldgrat vorbei an Deurali nach Tadapani.", "type": "text"}]}]}'::jsonb where day_id = '69c4acc0-1b7b-4b8a-ac19-d9dbb378f02a' and locale = 'de';
update public.trek_day_translations set title = 'Von Tadapani nach Ghandruk (1.940 m)', subtitle = 'Bergab durch den Wald · Gurung-Dorf', duration = '3–4 Std.', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ein leichter Abstieg durch den Wald nach Ghandruk, einem der größten Gurung-Dörfer der Region. Am Nachmittag haben Sie Zeit, die Steingassen und das kleine Gurung-Museum zu erkunden.", "type": "text"}]}]}'::jsonb where day_id = '695dd693-c232-4d1b-a019-4fddc79c397e' and locale = 'de';
update public.trek_day_translations set title = 'Von Ghandruk nach Kimche, Fahrt nach Pokhara (820 m)', subtitle = 'Letzter Trekkingtag · Feiern mit Ihrem Team', duration = '1–2 Std. · 2 Std. Fahrt', description = '{"type": "doc", "content": [{"type": "paragraph", "content": [{"text": "Ein kurzer Abstieg zur Straße in Kimche und mit dem Jeep zurück nach Pokhara, rechtzeitig für einen Nachmittag am Phewa-See.", "type": "text"}]}]}'::jsonb where day_id = '724b0d9c-2bf5-47a4-9dab-a5f73569b6e0' and locale = 'de';
